      console.warn(`${colors.yellow}[${timestamp}] WARNING${colors.reset}: ${message}`);
      break;
    case 'test':
      console.log(`${colors.cyan}[${timestamp}] TEST${colors.reset}: ${message}`);
      break;
    default:
      console.log(`[${timestamp}]: ${message}`);
