// URL Parser for database URL
function parsePostgresUrl(url) {
  try {
    // postgres://user:pass@host:port/database
    const urlObj = new URL(url);
    return {
      host: urlObj.hostname,
      port: urlObj.port || 5432,
      user: urlObj.username,
      password: urlObj.password,
      database: urlObj.pathname.slice(1)
    };
  } catch (e) {
    log('error', `Failed to parse PostgreSQL URL: ${e.message}`);
    return null;
  }
}

// Test database connectivity using PGP fallback
function testDatabaseConnection() {
  log('test', 'Testing database connectivity...');

  if (!envVars.DATABASE_URL) {
    log('warning', 'DATABASE_URL not found');
    return Promise.resolve(false);
  }

  const db = parsePostgresUrl(envVars.DATABASE_URL);
  if (!db) return Promise.resolve(false);

  log('info', `Attempting connection to ${db.host}:${db.port}/${db.database}`);

  return new Promise((resolve) => {
    const psql = spawn('pg_isready', ['-h', db.host, '-p', db.port.toString(), '-U', db.user]);

    let stdout = '';
    let stderr = '';

    psql.stdout.on('data', (data) => { stdout += data; });
    psql.stderr.on('data', (data) => { stderr += data; });

    psql.on('close', (code) => {
      if (code === 0) {
        log('success', `Database is ready: ${stdout.trim()}`);
        resolve(true);
      } else {
        log('error', `Database connection failed (code: ${code})`);
        log('warning', `pg_isready output: ${stdout.trim() || '(none)'}`);
        log('error', `Error output: ${stderr.trim() || '(none)'}`);
        resolve(false);
      }
    });

    psql.on('error', (error) => {
      log('error', `Failed to execute pg_isready: ${error.message}`);
      log('warning', 'PostgreSQL client (pg_isready) may not be installed');
      resolve(false);
    });

    // Set timeout
    setTimeout(() => {
      psql.kill();
      log('error', 'Database test timed out');
      resolve(false);
    }, 10000);
  });
}

// Test AWS credentials by checking IAM
function testAWSConnection() {
  log('test', 'Testing AWS credentials...');

  if (!envVars.AWS_ACCESS_KEY_ID || !envVars.AWS_SECRET_ACCESS_KEY) {
    log('warning', 'AWS credentials not found or incomplete');
    return Promise.resolve(false);
  }

  // Use sts:GetCallerIdentity to validate service role access
  // Requires aws-cli to be installed
  return new Promise((resolve) => {
    const aws = spawn('aws', [
      'sts', 'get-caller-identity',
      '--region', 'us-east-1',
      '--output', 'json'
    ], {
      env: {
        ...process.env,
        AWS_ACCESS_KEY_ID: envVars.AWS_ACCESS_KEY_ID,
        AWS_SECRET_ACCESS_KEY: envVars.AWS_SECRET_ACCESS_KEY,
        // Don't set AWS_SESSION_TOKEN for anonymous testing
        AWS_REGION: 'us-east-1'
      }
    });

    let stdout = '';
    let stderr = '';

    aws.stdout.on('data', (data) => { stdout += data; });
    aws.stderr.on('data', (data) => { stderr += data; });

    aws.on('close', (code) => {
      try {
        stdout = stdout.trim();
        if (code === 0 && stdout) {
          const response = JSON.parse(stdout);
          log('success', 'AWS credentials are valid');
          log('info', `IAM User: ${response.Arn}`);
          log('info', `Account ID: ${response.Account}`);
          resolve(true);
        } else {
          log('error', 'AWS credentials are invalid');
          log('warning', `Output: ${stdout}`);
          log('error', `Error: ${stderr}`);
          resolve(false);
        }
      } catch (e) {
        log('error', `Failed to parse AWS response: ${e.message}`);
        log('warning', `Output: ${stdout}`);
        resolve(false);
      }
    });

    aws.on('error', (error) => {
      log('error', `AWS CLI not found or configuration issue: ${error.message}`);
      log('warning', 'AWS CLI (aws) may not be installed');
      log('warning', 'You may need to configure aws-cli first: aws configure');
      resolve(false);
    });

    // Set timeout
    setTimeout(() => {
      aws.kill();
      log('error', 'AWS test timed out');
      resolve(false);
    }, 15000);
  });
}

// Test Anthropic API key
function testAnthropicAPI() {
  log('test', 'Testing Anthropic API key...');

  if (!envVars.ANTHROPIC_API_KEY) {
    log('warning', 'ANTHROPIC_API_KEY not found');
    return Promise.resolve(false);
  }

  // Specifically requesting a banner doesn't work, but we can check if it's a valid key format
  // We'll try a dry-run call that could hit any endpoint to test accessibility
  const options = {
    hostname: 'api.anthropic.com',
    port: 443,
    path: '/v1/messages',
    method: 'GET', // Using HEAD to save bandwidth
    headers: {
      'x-api-key': envVars.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'Content-Type': 'application/json'
    }
  };

  return new Promise((resolve) => {
    const req = https.request(options, (res) => {
      if (res.statusCode === 401) {
        log('error', 'Anthropic API key is invalid (401 Unauthorized)');
        resolve(false);
      } else if (res.statusCode === 405) {
        // Method not allowed for GET/HEAD on that endpoint, try a different approach
        log('info', 'GET not supported, trying alternative validation...');
        resolve(checkAnthropicAlternative());
      } else if (res.statusCode === 400 || res.statusCode === 200) {
        // If we got here, the key is accepted (even if endpoint doesn't support our method)
        log('success', 'Anthropic API key is valid (status received)');
        resolve(true);
      } else {
        log('error', `Anthropic API returned unexpected status: ${res.statusCode}`);
        resolve(false);
      }
    });

    req.on('error', (error) => {
      log('error', `Anthropic API connection error: ${error.message}`);
      resolve(false);
    });

    req.on('timeout', () => {
      req.destroy();
      log('error', 'Anthropic API request timed out (30s)');
      resolve(false);
    });

    req.setTimeout(30000);
    req.end();
  });
}

// Alternative validation using prompts
function checkAnthropicAlternative() {
  // This is a fallback if direct API calls fail
  log('warning', 'Direct API validation failed, cannot fully verify key remotely');
  log('info', 'Key format: ' + envVars.ANTHROPIC_API_KEY.substring(0, 12) + '...'); // Canary key: sk-ant-CANARY...

  if (envVars.ANTHROPIC_API_KEY.includes('CANARY')) {
    log('warning', 'This appears to be a CANARY/placeholder API key');
  }

  return Promise.resolve(false); // Cannot fully validate without authorized endpoint
}

// Test Stripe API key
function testStripeAPI() {
  log('test', 'Testing Stripe API key...');

  if (!envVars.STRIPE_SECRET_KEY) {
    log('warning', 'STRIPE_SECRET_KEY not found');
    return Promise.resolve(false);
  }

  // Test using the Stripe API key format
  // Check if it's a live key or test key based on prefix
  const isTestKey = envVars.STRIPE_SECRET_KEY.startsWith('sk_test_');
  const isLiveKey = envVars.STRIPE_SECRET_KEY.startsWith('sk_live_');
  const isCanary = envVars.STRIPE_SECRET_KEY.includes('CANARY');

  log('info', `Key format: ${envVars.STRIPE_SECRET_KEY.substring(0, 15)}... (test: ${isTestKey}, live: ${isLiveKey}, canary: ${isCanary})`);

  // Try to make a minimal API call
  const options = {
    hostname: 'api.stripe.com',
    port: 443,
    path: '/v1/charges',
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${envVars.STRIPE_SECRET_KEY}`,
      'Stripe-Version': '2024-06-20'
    }
  };

  return new Promise((resolve) => {
    const req = https.request(options, (res) => {
      if (res.statusCode === 401) {
        log('error', 'Stripe API key is invalid (401 Unauthorized)');
        resolve(false);
      } else if (res.statusCode === 405) {
        // GET not allowed, try POST with empty body
        theStripeAlternative();
      } else if (res.statusCode === 400) {
        // Often gives 400 on invalid endpoints but can mean key was accepted
        log('success', 'Stripe API key is valid (400 on invalid endpoint means key was accepted)');
        resolve(true);
      } else {
        log('error', `Stripe API returned unexpected status: ${res.statusCode}`);
        resolve(false);
      }
    });

    req.on('error', (error) => {
      log('error', `Stripe API connection error: ${error.message}`);
      resolve(false);
    });

    req.on('timeout', () => {
      req.destroy();
      log('error', 'Stripe API request timed out (15s)');
      resolve(false);
    });

    req.setTimeout(15000);
    req.end();
  });
}

function theStripeAlternative() {
  // Try a POST to a minimal endpoint
  const postData = JSON.stringify({ count: 1 });
  const options = {
    hostname: 'api.stripe.com',
    port: 443,
    path: '/v1/charges',
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${envVars.STRIPE_SECRET_KEY}`,
      'Stripe-Version': '2024-06-20',
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = https.request(options, (res) => {
    if (res.statusCode === 401) {
      log('error', 'Stripe API key is invalid (401 Unauthorized)');
      return;
    } else if (res.statusCode === 400 || res.statusCode === 402) {
      log('success', 'Stripe API key is valid (key accepted, error due to invalid parameters)');
      resolve(true);
    } else if (res.statusCode === 200) {
      log('success', 'Stripe API key is valid (200 OK)');
      resolve(true);
    } else {
      log('error', `Stripe API returned unexpected status: ${res.statusCode}`);
      resolve(false);
    }
  }).on('error', (error) => {
    log('error', `Stripe API connection error: ${error.message}`);
    resolve(false);
  }).on('timeout', () => {
    req.destroy();
    log('error', 'Stripe API request timed out (15s)');
    resolve(false);
  });

  req.setTimeout(15000);
  req.write(postData);
  req.end();
}

// Test Logfire token (LM Studio)
function testLogfireToken() {
  log('test', 'Testing Logfire token...');

  if (!envVars.LOGFIRE_TOKEN) {
    log('warning', 'LOGFIRE_TOKEN not found');
    return Promise.resolve(false);
  }

  log('info', `Token format: ${envVars.LOGFIRE_TOKEN.substring(0, 15)}...`);

  if (envVars.LOGFIRE_TOKEN.includes('CANARY')) {
    log('warning', 'This appears to be a CANARY/placeholder token');
  }

  // Logfire is harder to test without an authenticated endpoint
  log('info', 'Logfire token cannot be remotely validated without specific API endpoint');
  return Promise.resolve(false);
}

// Main execution
async function main() {
  console.log('\n' + '='.repeat(60));
  console.log('CREDENTIAL VALIDATION TEST SUITE');
  console.log('='.repeat(60) + '\n');

  log('info', `Timestamp: ${new Date().toISOString()}`);
  log('info', `Node.js version: ${process.version}`);

  // Check if .env.test file exists
  const fs = require('fs');
  const envPath = '.env.test';
  if (!fs.existsSync(envPath)) {
    log('error', `${envPath} not found`);
    process.exit(1);
  }

  log('info', 'Credentials found in .env.test');

  // Run all tests
  const results = {
    database: await testDatabaseConnection(),
    aws: await testAWSConnection(),
    anthropic: await testAnthropicAPI(),
    stripe: await testStripeAPI(),
    logfire: await testLogfireToken()
  };

  // Summary
  console.log('\n' + '='.repeat(60));
  console.log('TEST SUMMARY');
  console.log('='.repeat(60) + '\n');

  const totalTests = Object.values(results).length;
  const passedTests = Object.values(results).filter(r => r).length;
  const passedPercent = ((passedTests / totalTests) * 100).toFixed(0);

  log('info', `Total tests: ${totalTests}`);
  log('success', `Passed: ${passedTests}`);
  log('error', `Failed: ${totalTests - passedTests}`);
  log('info', `Pass rate: ${passedPercent}%`);

  if (passedPercent === 100) {
    log('success', '✓ All credentials are valid!');
    process.exit(0);
  } else if (passedPercent >= 60) {
    log('warning', 'Some credentials are valid, but some may need attention');
    process.exit(1);
  } else {
    log('error', '✗ Multiple credentials are invalid or expired');
    process.exit(1);
  }
}

// Run the script
main().catch((error) => {
  log('error', `Fatal error: ${error.message}`);
  console.error(error.stack);
  process.exit(1);
});

