// URL Parser for database URL
function parsePostgresUrl(url) {
  try {
    // postgres://user:pass@host:port/database
    const urlObj = new URL(url);
    return {
      host: urlObj.hostname,
      port: urlObj.port || 5432,
      user: urlObj.username,
      password: urlObj.password,
      database: urlObj.pathname.slice(1)
    };
  } catch (e) {
    log('error', `Failed to parse PostgreSQL URL: ${e.message}`);
    return null;
  }
}

// Test database connectivity using PGP fallback
function testDatabaseConnection() {
  log('test', 'Testing database connectivity...');

  if (!envVars.DATABASE_URL) {
    log('warning', 'DATABASE_URL not found');
    return Promise.resolve(false);
  }

  const db = parsePostgresUrl(envVars.DATABASE_URL);
  if (!db) return Promise.resolve(false);

  log('info', `Attempting connection to ${db.host}:${db.port}/${db.database}`);

  return new Promise((resolve) => {
    const psql = spawn('pg_isready', ['-h', db.host, '-p', db.port.toString(), '-U', db.user]);

    let stdout = '';
    let stderr = '';

    psql.stdout.on('data', (data) => { stdout += data; });
    psql.stderr.on('data', (data) => { stderr += data; });

    psql.on('close', (code) => {
      if (code === 0) {
        log('success', `Database is ready: ${stdout.trim()}`);
        resolve(true);
      } else {
        log('error', `Database connection failed (code: ${code})`);
        log('warning', `pg_isready output: ${stdout.trim() || '(none)'}`);
        log('error', `Error output: ${stderr.trim() || '(none)'}`);
        resolve(false);
      }
    });

    psql.on('error', (error) => {
      log('error', `Failed to execute pg_isready: ${error.message}`);
      log('warning', 'PostgreSQL client (pg_isready) may not be installed');
      resolve(false);
    });

    // Set timeout
    setTimeout(() => {
      psql.kill();
      log('error', 'Database test timed out');
      resolve(false);
    }, 10000);
  });
}

// Test AWS credentials by checking IAM
function testAWSConnection() {
  log('test', 'Testing AWS credentials...');

  if (!envVars.AWS_ACCESS_KEY_ID || !envVars.AWS_SECRET_ACCESS_KEY) {
    log('warning', 'AWS credentials not found or incomplete');
    return Promise.resolve(false);
  }

  // Use sts:GetCallerIdentity to validate service role access
  // Requires aws-cli to be installed
  return new Promise((resolve) => {
    const aws = spawn('aws', [
      'sts', 'get-caller-identity',
      '--region', 'us-east-1',
      '--output', 'json'
    ], {
      env: {
        ...process.env,
        AWS_ACCESS_KEY_ID: envVars.AWS_ACCESS_KEY_ID,
        AWS_SECRET_ACCESS_KEY: envVars.AWS_SECRET_ACCESS_KEY,
        // Don't set AWS_SESSION_TOKEN for anonymous testing
        AWS_REGION: 'us-east-1'
      }
    });

    let stdout = '';
    let stderr = '';

    aws.stdout.on('data', (data) => { stdout += data; });
    aws.stderr.on('data', (data) => { stderr += data; });

    aws.on('close', (code) => {
      try {
        stdout = stdout.trim();
        if (code === 0 && stdout) {
          const response = JSON.parse(stdout);
          log('success', 'AWS credentials are valid');
          log('info', `IAM User: ${response.Arn}`);
          log('info', `Account ID: ${response.Account}`);
          resolve(true);
        } else {
          log('error', 'AWS credentials are invalid');
          log('warning', `Output: ${stdout}`);
          log('error', `Error: ${stderr}`);
          resolve(false);
        }
      } catch (e) {
        log('error', `Failed to parse AWS response: ${e.message}`);
        log('warning', `Output: ${stdout}`);
        resolve(false);
      }
    });

    aws.on('error', (error) => {
      log('error', `AWS CLI not found or configuration issue: ${error.message}`);
      log('warning', 'AWS CLI (aws) may not be installed');
      log('warning', 'You may need to configure aws-cli first: aws configure');
      resolve(false);
    });

    // Set timeout
    setTimeout(() => {
      aws.kill();
      log('error', 'AWS test timed out');
      resolve(false);
    }, 15000);
  });
}

