  }
});

// Apply rate limiting to all routes
app.use(limiter);

// Health check endpoint with basic validation
app.get(
  '/health',
  [
    query('dirty').optional().isBoolean().withMessage('dirty must be a boolean'),
  ],
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          success: false, 
          errors: errors.array() 
        });
      }

      const dirty = req.query.dirty === 'true';
      res.json({
        status: 'ok',
        timestamp: new Date().toISOString(),
        dirtyFlag: dirty
      });
    } catch (error) {
      console.error('Health check error:', error);
      res.status(500).json({ 
        success: false, 
        error: 'Internal server error' 
      });
    }
  }
);

// Users endpoint with comprehensive validation
app.get(
  '/users',
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('offset must be a non-negative integer'),
    query('search').optional().isLength({ min: 1, max: 100 }).trim().escape().withMessage('search must be 1-100 characters'),
  ],
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          success: false, 
          errors: errors.array() 
        });
      }

      // Validate and sanitize input
      const { limit = 10, offset = 0, search = '' } = req.query;

      // Normalize search query
      const sanitizedSearch = validator.escape(search);

      // In a real app, this would query a database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter users if search is provided
      const filteredUsers = sanitizedSearch 
        ? users.filter(u => 
            u.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
            u.email.toLowerCase().includes(sanitizedSearch.toLowerCase())
          )
        : users;

      // Apply limits to prevent excessive data return
      const paginatedUsers = filteredUsers.slice(offset, parseInt(offset) + parseInt(limit));

      res.json({
        success: true,
        data: paginatedUsers,
        meta: {
          total: filteredUsers.length,
          limit: parseInt(limit),
          offset: parseInt(offset),
          count: paginatedUsers.length
        }
      });
    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({ 
        success: false, 
        error: 'Internal server error' 
      });
    }
  }
);

// 404 handler for all routes
app.use((req, res) => {
  res.status(404).json({ 
    success: false,
    error: 'Route not found',
    path: req.path
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Security: Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorResponse = {
    success: false,
    error: 'Internal server error'
  };

  if (isDevelopment) {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// Graceful shutdown handler
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle server shutdown gracefully
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;
