  allowRemote: process.env.ALLOW_REMOTE_TESTS !== 'false', // Default to allow tests
  logOutgoing: process.env.LOG_TEST_REQUESTS === 'true'
};

/**
 * Output utility with security considerations
 */
function log(message, level = 'INFO') {
  const timestamp = new Date().toISOString();
  const prefix = `[${timestamp}] [${level}]`;

  // Avoid logging sensitive values in production/secure contexts
  if (config.logOutgoing) {
    console.log(prefix, message);
  } else {
    console.log(prefix, message.replace(/(secret|key|password|token):\s*\S+/gi, '$1: ***REDACTED***'));
  }
}

/**
 * HTTPS GET request helper
 */
function httpsGet(url, path, headers) {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(url);
    const options = {
      hostname: urlObj.hostname,
      port: urlObj.port || 443,
      path: path,
      method: 'GET',
      headers: {
        ...headers,
        'Accept': 'application/json',
        'User-Agent': `TestSuite/1.0 (Credentials Validator)`
      },
      timeout: config.timeout
    };

    if (config.logOutgoing) {
      log(`HTTPS GET: ${url}${path}`);
    }

    const request = https.request(options, (response) => {
      let data = '';

      response.on('data', (chunk) => {
        data += chunk;
      });

      response.on('end', () => {
        try {
          resolve({
            statusCode: response.statusCode,
            headers: response.headers,
            body: data,
            json: JSON.parse(data)
          });
        } catch (e) {
          resolve({
            statusCode: response.statusCode,
            headers: response.headers,
            body: data,
            json: null
          });
        }
      });
    });

    request.on('error', (error) => {
      log(`Request error: ${error.message}`, 'ERROR');
      reject(error);
    });

    request.on('timeout', () => {
      request.destroy();
      log(`Request timeout after ${config.timeout}ms`, 'ERROR');
      reject(new Error(`Request timeout after ${config.timeout}ms`));
    });

    request.end();
  });
}

/**
 * Test 1: AWS Access Key Format Validation
 */
async function testAwsAccessKeyFormat() {
