    return false;
  }

  log(`AWS Access Key ID: ${akid}`);

  // AWS Access Key ID format: 20 alphanumeric characters, starts with AKIA
  const awsFormatRegex = /^AKIA[0-9A-Z]{16}$/;
  const isValid = awsFormatRegex.test(akid);

  if (isValid) {
    log('✓ Format is valid (AKIA followed by 16 alphanumeric characters)', 'SUCCESS');
  } else {
    log('✗ Format is invalid - expected AKIA followed by 16 alphanumeric characters', 'ERROR');
  }

  return isValid;
}

/**
 * Test 2: Database Connection Test (with aggressive timeouts)
 */
async function testDatabaseConnection() {
  log('\n=== Test 2: Database Connection Test ===');

  const dbUrl = credentials.database.url;
  log(`Testing: ${dbUrl.replace(/:[^:@]+@/, ':***REDACTED***@')}`);

  // Validate PostgreSQL URL format
  const pgUrlPattern = /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/.+/;
  if (!pgUrlPattern.test(dbUrl)) {
