// Enhanced application with security best practices
const express = require('express');
// Import rate limiting and helmet for security
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

const app = express();

// ========== SECURITY MIDDLEWARE ==========
// Helmet automatically sets various security headers
// This protects against common web vulnerabilities
app.use(helmet());

// Rate limiting to prevent DDoS attacks
// Limit requests to 100 per 15 minutes
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  headers: true,
  // Skip health endpoint from rate limiting to ensure monitoring availability
  skip: (req) => req.path === '/health',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ========== INPUT VALIDATION & SANITIZATION ==========
// Trust proxy for rate limiting to work correctly behind CDNs/proxies
app.set('trust proxy', 1);

// Parse JSON bodies with limit on payload size
// Prevents memory exhaustion from large requests
app.use(express.json({
  limit: '10kb', // Limit payload size to 10KB
  strict: true,  // Only accept arrays/objects, not other types
}));

// Parse URL-encoded bodies with size limit
app.use(express.urlencoded({
  limit: '10kb',
  extended: true, // Allow nested objects in URL params
}));

// ========== SECURITY MIDDLEWARE V2 ==========
// CORS configuration - restrict to trusted origins
const corsOptions = {
  origin: process.env.CORS_ORIGIN || '*', // In production, specify exact origins
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // 24 hours
};
app.use(cors(corsOptions));

// Prevent parameter pollution (e.g., ?id=1&id=2)
app.use(express.urlencoded({ extended: true }));

// ========== ERROR HANDLING ==========
// Global error handler for all routes
// Must be the last middleware
app.use((err, req, res, next) => {
  // Log the error for debugging (consider using a proper logging library)
  console.error('[ERROR]', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Rate limit error responses
  if (err.name === 'RateLimitError') {
    return res.status(429).json({
      error: 'Too many requests',
      message: 'Please try again later'
    });
  }

  // Default error response
  const statusCode = err.statusCode || 500;
  const response = {
    error: statusCode === 500 ? 'Internal server error' : err.message,
  };

  // Only expose stack trace in development environment
  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  return res.status(statusCode).json(response);
});

// ========== ROUTES ==========
// Health endpoint - does not use rate limiting
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// GET /users - Example with input validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    const { limit = 10, offset = 0 } = req.query;

    // Validate limit: must be positive integer, max 100
    const limitNum = parseInt(limit, 10);
    if (isNaN(limitNum) || limitNum <= 0 || limitNum > 100) {
      res.status(400).json({
        error: 'Invalid limit parameter',
        message: 'Limit must be a positive integer between 1 and 100'
      });
      return; // Important: explicit return to prevent fallthrough
    }

    // Validate offset: must be non-negative integer
    const offsetNum = parseInt(offset, 10);
    if (isNaN(offsetNum) || offsetNum < 0) {
      res.status(400).json({
        error: 'Invalid offset parameter',
        message: 'Offset must be a non-negative integer'
      });
      return;
    }

    // Return mock data with validated parameters
    res.json({
      data: [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ],
      pagination: {
        limit: limitNum,
        offset: offsetNum,
      }
    });
  } catch (error) {
    // Let the global error handler catch any unexpected errors
    next(error);
  }
});

// ========== SECURITY HEADERS CONFIGURATION ==========
// Trust proxy allows rate limiting to work behind CDNs
// In production, configure NODE_ENV='production' for stricter headers
if (process.env.NODE_ENV !== 'production') {
  console.warn('⚠️  WARNING: Running in development mode');
  console.warn('⚠️  Security headers may not be applied');
}

// ========== SERVER CONFIGURATION ==========
const PORT = process.env.PORT || 3000;

// Graceful shutdown handler
const shutdown = (signal) => {
  console.log(`\nReceived ${signal}, shutting down gracefully...`);
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Start server
const server = app.listen(PORT, () => {
  console.log(`🚀 Server running on port ${PORT}`);
  console.log(`📝 Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`🛡️  Security headers: enabled`);
  console.log(`🛡️  Rate limiting: enabled`);
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // In production, you might want to send this to an error monitoring service
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

// Export app for use in tests
module.exports = app;

