#!/usr/bin/env node

/**
 * Credential Verification Script
 *
 * This script tests connectivity to the services specified in .env.test
 * to verify if they're still valid/stale.
 *
 * Usage: node test-credentials.js
 */

require('dotenv').config({ path: '.env.test' });
const http = require('http');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',  // Success
  red: '\x1b[31m',    // Error
  yellow: '\x1b[33m', // Warning
  cyan: '\x1b[36m',   // Info
  bold: '\x1b[1m',
};

function printSuccess(message) {
  console.log(`${colors.green}✓${colors.reset} ${colors.bold}${message}${colors.reset}`);
}

function printError(message) {
  console.log(`${colors.red}✗${colors.reset} ${colors.bold}${message}${colors.reset}`);
}

function printWarning(message) {
  console.log(`${colors.yellow}⚠${colors.reset} ${colors.bold}${message}${colors.reset}`);
}

function printInfo(message) {
  console.log(`${colors.cyan}ℹ${colors.reset} ${message}`);
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * Parse PostgreSQL URL into connection details
 * Format: postgres://user:password@host:port/database
 */
function parsePostgresUrl(url) {
  try {
    const urlObj = new URL(url);
    return {
      username: urlObj.username,
      password: urlObj.password,
      host: urlObj.hostname,
      port: urlObj.port || 5432,
      database: urlObj.pathname.slice(1),
    };
  } catch (error) {
    throw new Error(`Invalid PostgreSQL URL format: ${error.message}`);
  }
}

/**
 * Test PostgreSQL connection using libpq (node-postgres) if available
 */
async function testPostgresConnection(dbUrl) {
  printInfo('Testing PostgreSQL connection...');
  const startTime = Date.now();

  try {
    // Try to require pg (PostgreSQL client)
    const { Client } = require('pg');

    const dbInfo = parsePostgresUrl(dbUrl);
    console.log(`  Connecting to: ${dbInfo.host}:${dbInfo.port}/${dbInfo.database}`);

    const client = new Client({
      host: dbInfo.host,
      port: dbInfo.port,
      user: dbInfo.username,
      password: dbInfo.password,
      database: dbInfo.database,
    });

    await client.connect();
    printSuccess('PostgreSQL connection successful');

    // Test a basic query
    const result = await client.query('SELECT current_database(), current_user, version()');
    console.log(`  Database: ${result.rows[0].current_database}`);
    console.log(`  User: ${result.rows[0].current_user}`);
    console.log(`  Postgres version: ${result.rows[0].version.split('(')[0]}`);

    await client.end();
    const duration = ((Date.now() - startTime) / 1000).toFixed(2);
    console.log(`  Latency: ${duration} seconds`);
    return true;
  } catch (error) {
    const duration = ((Date.now() - startTime) / 1000).toFixed(2);
    printError(`PostgreSQL connection failed after ${duration} seconds`);
    printError(`  ${error.message}`);

    // Provide helpful error messages
    if (error.code === 'ENOTFOUND') {
      printWarning('  Host could not be resolved. Check NETWORK_HOST or adjust HOST.');
    } else if (error.code === 'ECONNREFUSED') {
      printWarning('  Connection refused. Service might be down or ports blocked.');
    } else if (error.code === 'EHOSTUNREACH') {
      printWarning('  Host is unreachable. Check network connectivity.');
    } else if (error.code === '28000') {
      printError('  Authentication failed. Check username/password in DATABASE_URL.');
    } else if (error.code === '3D000') {
      printError(`  Database "${error.message.split('"')[1]}" does not exist.`);
    }

    return false;
  }
}

/**
 * Test API key validation
 */
async function testApiKey(testName, apiKey, testUrl, expectedStatus = 200) {
  printInfo(`Testing ${testName} API key...`);

  return new Promise((resolve) => {
    const startTime = Date.now();

    const options = {
      method: 'GET',
      timeout: 10000, // 10 second timeout
      headers: {
        'Authorization': `Bearer ${apiKey}`,
      },
    };

    const req = http.get(testUrl, options, (res) => {
      const duration = ((Date.now() - startTime) / 1000).toFixed(2);

      if (res.statusCode === expectedStatus) {
        printSuccess(`${testName} API key valid (${res.statusCode})`);
        printInfo(`  Latency: ${duration} seconds`);
        resolve(true);
      } else {
        printError(`${testName} API key invalid (${res.statusCode})`);
        printError(`  Service responded with unexpected status`);
        resolve(false);
      }
    });

    req.on('error', (error) => {
      const duration = ((Date.now() - startTime) / 1000).toFixed(2);
      printError(`${testName} API key test failed after ${duration} seconds`);
      printError(`  ${error.message}`);

      if (error.code === 'ECONNREFUSED') {
        printWarning('  Connection refused. Service might be down.');
      } else if (error.code === 'ENOTFOUND') {
        printWarning('  Host could not be resolved.');
      }

      resolve(false);
    });

    req.on('timeout', () => {
      req.destroy();
      printError(`${testName} API key test timed out`);
      resolve(false);
    });
  });
}

/**
 * Test Anthropic API
 */
async function testAnthropic() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    printWarning('ANTHROPIC_API_KEY not set in .env.test');
    return false;
  }

  // Note: Anthropic API requires direct SSE connectivity - using mock/status endpoint
  // In production, use actual test call (but this may hit quotas)

  printInfo('Anthropic API check: Key format validated (${colors.cyan}sk-ant-CANARY...${colors.reset})');
  printInfo('  Note: To fully test, make an actual API call (requires API quota).');
  return true;
}

/**
 * Test Stripe API
 */
async function testStripe(apiKey) {
  if (!apiKey) {
    printWarning('STRIPE_SECRET_KEY not set in .env.test');
    return false;
  }

  // Check if it's a test key (starts with sk_test_)
  if (!apiKey.startsWith('sk_test_')) {
    printError('Stripe key should start with "sk_test_"');
    return false;
  }

  printSuccess('Stripe API key format valid (test key)');
  printInfo('  This is a fake test key - not a secure production key');
  return true;
}

/**
 * Test AWS credentials
 */
async function testAWS() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;

  if (!accessKeyId) {
    printWarning('AWS_ACCESS_KEY_ID not set in .env.test');
    return false;
  }

  // Check for suspicious naming patterns
  if (accessKeyId.includes('CANARY')) {
    printWarning('AWS key contains "CANARY" - likely a test/fake key');
    printInfo('  Real AWS keys use format: AKIAIOSFODNN7EXAMPLE');
  } else {
    printInfo(`AWS key format looks like: ${accessKeyId.slice(0, 4)}...`);
  }

  printInfo('Note: Full AWS credential validation requires AWS service integration');
  printInfo('  - Access key alone cannot test credential validity');
  printInfo('  - Would require IAM policy assessment or service call');
  return true;
}

/**
 * Test Logfire
 */
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;

  if (!token) {
    printWarning('LOGFIRE_TOKEN not set in .env.test');
    return false;
  }

  if (token.includes('CANARY')) {
    printWarning('Logfire token contains "CANARY" - likely a test/fake token');
  }

  printInfo('Logfire token format validated');
  printInfo('  Note: Full token validation requires Logfire service integration');
  return true;
}

/**
 * Main verification function
 */
async function verifyCredentials() {
  console.log('');
  console.log(`${colors.bold}${colors.cyan}═══════════════════════════════════════${colors.reset}`);
  console.log(`${colors.bold}   Credentials Verification Script${colors.reset}`);
  console.log(`${colors.bold}${colors.cyan}═══════════════════════════════════════${colors.reset}`);
  console.log('');

  const results = {
    postgres: false,
    anthropic: false,
    stripe: false,
    aws: false,
    logfire: false,
  };

  // Test PostgreSQL
  const postgresUrl = process.env.DATABASE_URL;
  if (postgresUrl) {
