  console.log('');

  // Test API Keys (format validation only)
  results.antrophic = await testAnthropic().catch(() => false);
  results.stripe = await testStripe(process.env.STRIPE_SECRET_KEY)?.catch(() => false) ?? false;
  results.aws = await testAWS().catch(() => false);
  results.logfire = await testLogfire().catch(() => false);

  console.log('');
  console.log(`${colors.bold}${colors.cyan}═══════════════════════════════════════${colors.reset}`);
  console.log(`${colors.bold}   Verification Summary${colors.reset}`);
  console.log(`${colors.bold}${colors.cyan}═══════════════════════════════════════${colors.reset}`);
  console.log('');

  // Count passing/failing tests
  const passed = Object.values(results).filter(Boolean).length;
  const total = Object.keys(results).length;

  console.log(`Tests passed: ${passed}/${total}`);

  // Detailed results
  if (results.postgres) {
