#!/usr/bin/env node

/**
 * Simple Credentials Verification Script
 * Uses only Node.js built-in modules - no npm dependencies required
 *
 * This tests connectivity to the services specified in .env.test
 */

require('fs');
require('path');
require('http');

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  bold: '\x1b[1m',
};

function printSuccess(message) {
  console.log(`${colors.green}✓${colors.reset} ${colors.bold}${message}${colors.reset}`);
}

function printError(message) {
  console.log(`${colors.red}✗${colors.reset} ${colors.bold}${message}${colors.reset}`);
}

function printWarning(message) {
  console.log(`${colors.yellow}⚠${colors.reset} ${colors.bold}${message}${colors.reset}`);
}

function printInfo(message) {
  console.log(`${colors.cyan}ℹ${colors.reset} ${message}`);
}

// Try to load .env.test file
let envConfig = {};

try {
  const envPath = path.join(__dirname, '.env.test');
  if (fs.existsSync(envPath)) {
    const envContent = fs.readFileSync(envPath, 'utf8');
    // Parse key=value lines
    envContent.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#') && line.includes('=')) {
        const [key, ...valueParts] = line.split('=');
        envConfig[key.trim()] = valueParts.join('=');
      }
    });
  }
} catch (error) {
  printError(`Failed to load .env.test: ${error.message}`);
}

console.log('');

/**
 * Simple HTTP test
 */
function simpleHttpTest(testName, url) {
  return new Promise((resolve) => {
    if (!url) {
      printWarning(`${testName} - URL not provided`);
      resolve(false);
      return;
    }

    try {
      printInfo(`Testing ${testName}:`);
      printInfo(`  URL: ${url}`);

      const options = {
        method: 'GET',
        timeout: 8000, // 8 second timeout
      };

      const req = http.get(url, options, (res) => {
        printSuccess(`${testName} - Response: ${res.statusCode}`);
        printInfo(`  Headers: ${Object.keys(res.headers).length} fields`);
        resolve(true);
      });

      req.on('error', (error) => {
        printWarning(`${testName} - Connection failed`);
        printInfo(`  Error: ${error.code || error.message}`);

        if (error.code === 'ENOTFOUND') {
          printWarning('  → Hostname not found');
        } else if (error.code === 'ECONNREFUSED') {
          printWarning('  → Connection refused (service down or wrong port)');
        } else if (error.code === 'ECONNRESET') {
          printWarning('  → Connection reset by peer');
        } else if (error.code === 'ETIMEDOUT') {
          printWarning('  → Connection timed out');
        } else {
          printInfo(`  Full error: ${error.message}`);
        }
        resolve(false);
      });

      req.on('timeout', () => {
        req.destroy();
        printError(`${testName} - Timeout after 8 seconds`);
        resolve(false);
      });

    } catch (error) {
      printWarning(`${testName} - Invalid URL or other error`);
      printInfo(`  ${error.message}`);
      resolve(false);
    }
  });
}

/**
 * MaxMind IP address test (for AWS region detection)
 */
function testMaxMind() {
  printInfo('Testing IP geolocation API (AWS region detection)...');
  return new Promise((resolve) => {
    const options = {
      method: 'GET',
      hostname: 'get.geojs.io',
      port: 80,
      path: '/v1/ip',
      timeout: 5000,
    };

    const req = http.get(options, (res) => {
      if (res.statusCode === 200) {
        let data = '';
        res.on('data', (chunk) => data += chunk);
        res.on('end', () => {
          try {
            const ipInfo = JSON.parse(data);
            printSuccess('MaxMind API successful');
            printInfo(`  IP: ${ipInfo.ip}`);
            printInfo(`  Country: ${ipInfo.country} ${ipInfo.region || ''}`);
            if (ipInfo.name) {
              printInfo(`  Region Name: ${ipInfo.name}`);
            }
          } catch (error) {
            printWarning('Failed to parse IP info');
          }
          resolve(true);
        });
      } else {
        printWarning(`MaxMind API returned ${res.statusCode}`);
        resolve(false);
      }
    });

    req.on('error', () => {
      printWarning('MaxMind API test failed');
      resolve(false);
    });

    req.on('timeout', () => {
      req.destroy();
      printError('MaxMind API timeout');
      resolve(false);
    });
  });
}

/**
 * Test database URL
 */
function testDatabaseUrl() {
  const dbUrl = envConfig['DATABASE_URL'];
  if (!dbUrl) {
    printWarning('DATABASE_URL not found in .env.test');
    return Promise.resolve(false);
  }

  printInfo('Database URL:');
  printInfo(`  Format: ${dbUrl.substring(0, 30)}...`);

  // Validate PostgreSQL URL format
  if (dbUrl.startsWith('postgres://')) {
    printSuccess('Valid PostgreSQL URL format detected');
    printInfo('  Note: Actual connection requires PostgreSQL client (pg package)');

    // Check credentials
    try {
      const urlObj = new URL(dbUrl);
      const username = decodeURIComponent(urlObj.username);
      const password = decodeURIComponent(urlObj.password);

      if (username.length > 0 && password.length > 0) {
        printSuccess(`Credentials present (${username}):****`);
      } else {
        printWarning('Missing username or password');

        // Check for canary patterns
        if (username.includes('CANARY')) {
          printWarning('Username contains "CANARY" pattern (test key)');
        }
        if (password.includes('CANARY')) {
          printWarning('Password contains "CANARY" pattern (test key)');
        }
      }

      printInfo(`  Host: ${urlObj.hostname}${urlObj.port ? ':' + urlObj.port : ''}`);
      printInfo(`  Database: ${urlObj.pathname.slice(1) || urlObj.hostname}`);

      // Parse domain for IP lookup
      if (!urlObj.hostname.includes('.')) {
        printWarning('Warning: Unusual hostname format');
      }
    } catch (error) {
      printWarning(`Invalid URL format: ${error.message}`);
    }

    return Promise.resolve(true);
  } else if (dbUrl.startsWith('mongodb://')) {
    printSuccess('Valid MongoDB URL format detected');
    printInfo('  Note: MongoDB connection test requires mongodb package');
  } else if (dbUrl.startsWith('mysql://')) {
    printSuccess('Valid MySQL URL format detected');
    printInfo('  Note: MySQL connection test requires mysql2 package');
  } else {
    printWarning('Unknown database URL format - not standard PostgreSQL');
    printInfo('  Expected format: postgres://user:pass@host:port/database');
  }

  return Promise.resolve(true);
}

/**
