 */
function testApiKey(testName, apiKey, placeholderCheck = null) {
  if (!apiKey) {
    printWarning(`${testName} not set in .env.test`);
    return Promise.resolve(false);
  }

  printInfo(`${testName}:`);
  printInfo(`  Value: ${apiKey.substring(0, 25)}${apiKey.length > 25 ? '...' : ''}`);

  // Check for canary pattern
  if (apiKey.includes('CANARY')) {
    printWarning('Contains "CANARY" pattern - likely a test/fake key');
