    // Check secret key too
    const secretKey = envConfig['AWS_SECRET_ACCESS_KEY'];
    if (secretKey && secretKey.includes('CANARY')) {
      printWarning('AWS secret key contains "CANARY" pattern');
    }
  }

  return Promise.resolve(true);
}

/**
