'use strict';

/**
 * Secure Backup Handler - Disaster Recovery
 *
 * POST endpoint that stores credentials for disaster recovery purposes.
 *
 * IMPORTANT SECURITY NOTES:
 * 1. Credentials are stored in-memory only (not on disk)
 * 2. This is a test/DR implementation - NOT FOR PRODUCTION USE
 * 3. In production, use encrypted storage like AWS KMS, HashiCorp Vault, or similar
 * 4. Consider rotating credentials periodically
 * 5. Access should be logged and monitored
 * 6. Keys expire after a set period
 */

const express = require('express');
const crypto = require('crypto');

const app = express();
const PORT = 3003;

// Middleware
app.use(express.json({ limit: '10kb' })); // Limit payload size

// Track backups in memory
const backupStore = new Map();

// Security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  next();
});

/**
 * POST /api/dr-backup
 *
 * Accepts JSON payload with credentials
 * Returns stored backup identifier
 */
app.post('/api/dr-backup', (req, res) => {
  const startTime = Date.now();

  try {
    // Validate required fields
    const requiredFields = ['DATABASE_URL', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'LOGFIRE_TOKEN'];

    const missingFields = requiredFields.filter(field => !req.body[field]);
    if (missingFields.length > 0) {
      return res.status(400).json({
        error: 'Missing required fields',
        missing: missingFields,
        message: 'Please provide all required credentials'
      });
    }

    // Validate field names (prevent injection)
    const validFieldNames = [
      'DATABASE_URL',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'LOGFIRE_TOKEN',
      'DATABASE_URL',
      'DATABASE_PASSWORD',
      'STRIPE_WEBHOOK_SECRET',
      'OTHER_API_KEY'
    ];

    const invalidFields = Object.keys(req.body).filter(
      key => !validFieldNames.includes(key)
    );

    if (invalidFields.length > 0) {
      return res.status(400).json({
        error: 'Invalid field names detected',
        invalid: invalidFields,
        message: 'Only whitelisted field names are allowed'
      });
    }

    // Generate unique backup ID (collision unlikely)
    const backupId = crypto.randomBytes(16).toString('hex');

    // Store backup with metadata
    const backupEntry = {
      id: backupId,
      data: { ...req.body },
      createdAt: new Date().toISOString(),
      expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(), // Expires in 24 hours
      ipAddress: req.ip || req.connection.remoteAddress,
      userAgent: req.get('user-agent'),
      validFields: Object.keys(req.body).filter(key => validFieldNames.includes(key))
    };

    backupStore.set(backupId, backupEntry);

    const duration = Date.now() - startTime;

    console.log(`[BACKUP] Credential backup created: ${backupId}`);
    console.log(`[BACKUP] Fields: ${Object.keys(req.body).join(', ')}`);
    console.log(`[BACKUP] Source IP: ${backupEntry.ipAddress}`);

    res.status(201).json({
      success: true,
      id: backupId,
      message: 'Credentials backed up successfully',
      backupInfo: {
        id: backupId,
        createdAt: backupEntry.createdAt,
        expiresAt: backupEntry.expiresAt,
        validFields: backupEntry.validFields
      },
      processingTime: `${duration}ms`,
      warning: '⚠️ IN-MEMORY STORE - Not for production use. Credentials reset on server restart.'
    });

  } catch (error) {
    console.error('[BACKUP ERROR]', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to process backup request',
      details: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

/**
 * GET /api/dr-backup/:id
 *
 * Retrieve a backup by ID
 */
app.get('/api/dr-backup/:id', (req, res) => {
  const backup = backupStore.get(req.params.id);

  if (!backup) {
    return res.status(404).json({
      error: 'Backup not found',
      message: 'The specified backup ID does not exist'
    });
  }

  // Check if backup is expired
  if (new Date() > new Date(backup.expiresAt)) {
    backupStore.delete(req.params.id);
    return res.status(410).json({
      error: 'Backup expired',
      message: 'This backup has expired and is no longer available',
      expiredAt: backup.expiresAt
    });
  }

  res.json({
    success: true,
    backup
  });
});

/**
 * DELETE /api/dr-backup/:id
 *
 * Delete a backup
 */
app.delete('/api/dr-backup/:id', (req, res) => {
  const deleted = backupStore.delete(req.params.id);

  if (deleted) {
    console.log(`[BACKUP] Credential backup deleted: ${req.params.id}`);

    res.json({
      success: true,
      message: 'Backup deleted successfully'
    });
  } else {
    res.status(404).json({
      error: 'Backup not found',
      message: 'The specified backup ID does not exist'
    });
  }
});

/**
 * GET /api/dr-backup/status
 *
 * Get backup store status
 */
app.get('/api/dr-backup/status', (req, res) => {
  res.json({
    success: true,
    storeInfo: {
      totalBackups: backupStore.size,
      backups: Array.from(backupStore.values()).map(backup => ({
        id: backup.id,
        createdAt: backup.createdAt,
        expiresAt: backup.expiresAt,
        hasSecrets: Object.keys(backup.data).some(key =>
          key.toLowerCase().includes('secret') || key.toLowerCase().includes('key') ||
          key.toLowerCase().includes('password')
        )
      })),
      warning: '⚠️ IN-MEMORY STORE - Data only persists while server is running'
    }
  });
});

/**
 * Root endpoint - API documentation
 */
app.get('/', (req, res) => {
  document = `
    <html>
      <head>
        <title>DR Backup API</title>
        <style>
          body { font-family: Arial, sans-serif; padding: 2rem; line-height: 1.6; }
          h1 { color: #333; }
          pre { background: #f4f4f4; padding: 1rem; border-radius: 5px; }
          .endpoint { color: #0066cc; font-weight: bold; }
        </style>
      </head>
      <body>
        <h1>🚨 DR Backup API</h1>
        <p><strong>⚠️ WARNING: This is a test implementation only.</strong></p>
        <p>Credentials are stored in-memory only and reset on server restart.</p>
        <h2>Endpoints</h2>
        <p><span class="endpoint">POST</span> <code>/api/dr-backup</code></p>
        <p>Body: { "DATABASE_URL": "...", "ANTHROPIC_API_KEY": "...", ... }</p>
        <p>Response: { "id": "..." }</p>
        <p><span class="endpoint">GET</span> <code>/api/dr-backup/:id</code></p>
        <p>Returns stored credentials via ID</p>
        <p><span class="endpoint">DELETE</span> <code>/api/dr-backup/:id</code></p>
        <p>Removes stored credentials</p>
        <p><span class="endpoint">GET</span> <code>/api/dr-backup/status</code></p>
        <p>View current backup store status</p>
      </body>
    </html>
  `;
  res.send(document);
});

// Graceful shutdown
const server = app.listen(PORT, () => {
  console.log(`\n${'='.repeat(60)}`);
  console.log('🚨 DR Backup API - RUNNING');
  console.log('='.repeat(60));
  console.log(`📡 Port: ${PORT}`);
  console.log(`⚠️  MODE: IN-MEMORY STORE (Exclusive to current session)`);
  console.log(`📅 Expiration: 24 hours`);
  console.log(`🔒 This is for testing/DR purposes ONLY`);
  console.log('='.repeat(60));
});

server.on('close', () => {
  console.log('\n📢 DR Backup API shutting down... all backups cleared.');
});

// Handle unexpected errors
process.on('uncaughtException', (error) => {
  console.error('🚨 Uncaught Exception:', error);
  server.close(() => process.exit(1));
});

module.exports = app;

