    // Parse URL
    const { pathname, method } = new URL(req.url, `http://${req.headers.host || 'localhost'}`);

    // Parse body asynchronously
    let bodyData = '';
    req.on('data', (chunk) => { bodyData += chunk; });

    req.on('end', () => {
      // Create request object with body
      req.method = req.method || method;
      req.url = pathname;
      req.body = bodyData ? tryParseJSON(bodyData) : {};

      // Find matching route
      const route = routes.find(r => r.path === pathname && r.method === req.method);
      if (route) {
        route.handler(req, res);
      } else {
        res.writeHead(404, { 'Content-Type': 'application/json' })
          .end(JSON.stringify({ error: 'Not Found', message: 'Endpoint does not exist' }));
      }
    });

