    if (new Date() > new Date(backup.expiresAt)) {
      backups.delete(backupId);
      res.writeHead(410, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Expired' }));
      return;
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ backup }));
    return;
  }

  if (method === 'GET' && pathname === '/api/dr-backup/status') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      total: backups.size,
      backups: Array.from(backups.entries()).map(([id, b]) => ({
        id,
        createdAt: b.createdAt,
        expiresAt: b.expiresAt,
      })),
    }));
    return;
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not Found' }));
});

server.listen(PORT, () => {
  console.log('DR Backup Server running on port ' + PORT);
});

module.exports = { server, backups };
