};

const isDryRun = process.argv.includes('--dry-run') || process.argv.includes('--test');

// ==============================================
// DATABASE VERIFICATION
// ==============================================

async function testDatabaseConnection() {
  console.log('\n📋 Testing Database Connection...\n');
  console.log(`Service: ${credentials.database.name}`);
  console.log(`URL: ${maskSensitive(credentials.database.url)}`);

  const databaseUrl = credentials.database.url;
  const isStale = databaseUrl.includes('db.internal') ||
                  databaseUrl.includes('CANARY');

  console.log('\n🔍 Checking for stale configuration...');
  console.log('   Stale indicators found:', isStale ? 'YES' : 'NO');

  if (isStale) {
    console.log('   ❌ Stale credential detected:');
    console.log('      - Hostname "db.internal" is likely internal/internal');
    console.log('      - Contains "CANARY" prefix (not production format)');
  }

  if (isDryRun) {
    console.log('\n   [DRY RUN - Would connect to PostgreSQL if running live]');
    console.log('   Status: SKIPPED (dry run mode)');
    return { result: 'skipped', reason: 'dry-run-mode', databaseUrl };
  }

  try {
    // Quick validation of URL format before attempting connection
    const pgUrlParser = new URL(databaseUrl);

    console.log('\n   Connection parameters:');
    console.log(`     Host: ${pgUrlParser.hostname}`);
    console.log(`     Port: ${pgUrlParser.port || '5432'}`);
    console.log(`     Database: ${pgUrlParser.pathname.slice(1) || 'default'}`);
    console.log(`     User: ${pgUrlParser.username}`);

    // Check for local/internal hosts that can't be accessed externally
    const hostname = pgUrlParser.hostname.toLowerCase();
    const isInternal = hostname.includes('localhost') ||
                       hostname.includes('127.0.0.1') ||
                       hostname.startsWith('10.') ||
                       hostname.startsWith('192.168.') ||
                       hostname === 'db.internal';

    if (isInternal) {
      console.log('\n   ❌ Database not accessible from external network');
      console.log('      This is expected if database is local-only');
      console.log('      Run with --dry-run to test format validation only');
      return { result: 'internal-host', isInternal };
    }

    // Try to load pg package
    try {
      const { Client } = require('pg');

      console.log('\n   Attempting connection...');
      const startTime = Date.now();

      const client = new Client({
        host: pgUrlParser.hostname,
        port: parseInt(pgUrlParser.port) || 5432,
        database: pgUrlParser.pathname.slice(1) || 'postgres',
        user: pgUrlParser.username,
        password: pgUrlParser.password
      });

      await client.connect();
      const connTime = Date.now() - startTime;
      console.log(`   ✅ Connection established in ${connTime}ms`);

      const queryStart = Date.now();
      const result = await client.query('SELECT NOW()');
      const queryTime = Date.now() - queryStart;

      console.log(`   Query executed in ${queryTime}ms`);

      await client.end();
      return { result: 'valid', connTime, queryTime };
    } catch (e) {
      if (e.code === 'MODULE_NOT_FOUND') {
        console.log('\n   ❌ PostgreSQL client not installed');
        console.log('   Run: npm install pg');
        return { result: 'missing-dep', error: 'MODULE_NOT_FOUND' };
      } else if (e.code === 'ECONNREFUSED') {
        console.log('\n   ❌ Connection refused');
        console.log('   Target server is not reachable');
        console.log('   This indicates the database URL is stale');
        return { result: 'connection-refused', hostname: hostname };
      } else {
        console.log('\n   ❌ Connection failed');
        console.log(`   ${e.code}: ${e.message}`);
        return { result: 'failed', error: e.message, code: e.code };
      }
    }
  } catch (error) {
    console.log('\n   ❌ Invalid database URL format');
    console.log(`   Error: ${error.message}`);
    return { result: 'invalid-url', error: error.message };
  }
}

