  return Promise.resolve({ result: 'unknown', message: 'No verification available without docs' });
}

// ==============================================
// UTILITY FUNCTIONS
// ==============================================

function maskSensitive(value) {
  const SECRET_REDACT = '••••••••••••';

  if (typeof value === 'string') {
    // API keys: show first few chars
    if (value.startsWith('AKI') || value.match(/^sk-[a-z]*/)) {
      return value.substring(0, Math.min(15, value.length)) + SECRET_REDACT + value.substring(value.length - 4);
    }
    // PostgreSQL URLs: show first part masked
    if (value.includes('@') && value.includes('://postgres')) {
      const [clean, rest] = value.split('@');
      return clean.substring(0, clean.indexOf(':') + 1) + SECRET_REDACT + '@' + rest;
    }
    // Logfire tokens
    if (value.includes('/') && value.length > 30) {
      return value.substring(0, 12) + SECRET_REDACT;
    }
  }

  // Mask any URL-encoded or hashed values
  return value.toString().replace(/[a-zA-Z0-9]+/, '_redacted_');
}

