// MAIN EXECUTION
// ==============================================

async function runVerification() {
  console.log('╔════════════════════════════════════════════════════════╗');
  console.log('║     CREDENTIAL VERIFICATION & VALIDATION              ║');
  console.log('╚════════════════════════════════════════════════════════╝');
  console.log(`\nTest mode: ${isDryRun ? 'DRY RUN (skips live connections)' : 'LIVE verification'}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'Development'}`);
  console.log(`Input source: Environment variables or fallback to package data\n`);

  const startTime = Date.now();
  const results = {
    database: { name: credentials.database.name },
    aws: { name: credentials.aws.name },
    anthropic: { name: credentials.anthropic.name },
    stripe: { name: credentials.stripe.name },
    logfire: { name: credentials.logfire.name }
  };

  console.log('══════════════════════════════════════════════════════\n');

  // Run verifications in parallel
  await Promise.all([
    testDatabaseConnection().then(r => results.database.result = r),
    testAWSConnection().then(r => results.aws.result = r),
    testAnthropicConnection().then(r => results.anthropic.result = r),
    testStripeConnection().then(r => results.stripe.result = r),
    testLogfireConnection().then(r => results.logfire.result = r)
  ]);

  const totalTime = Date.now() - startTime;

  // Summary
  console.log('╔════════════════════════════════════════════════════════╗');
  console.log('║                      SUMMARY                          ║');
  console.log('╚════════════════════════════════════════════════════════╝');

  const passed = Object.values(results).filter(r => r.result === 'valid' || r.result === 'response-received' || r.result === 'may-be-valid' || r.result === 'internal-host').length;
  const total = Object.keys(results).length;

  console.log(`\nTotal runtime: ${totalTime}ms`);
  console.log(`Passed: ${passed}/${total} services`);
  console.log('\nService Status:\n');

  Object.entries(results).forEach(([service, result]) => {
    console.log(`  ${service.toUpperCase().padEnd(10)}: ${formatStatus(result.result, result)}`);
  });

  console.log('\n══════════════════════════════════════════════════════');
  console.log('\nSummary:\n');
  if (passed === total) {
    console.log('  ✅ All credentials appear valid');
  } else if (passed > 0) {
    console.log('  ⚠️  Some services have issues (see details above)');
  } else {
    console.log('  ❌ All services failed to connect');
  }

  console.log('\n💡 Note:');
  console.log('   - Test credentials (CANARY) may return expected failures');
  console.log('   - `db.internal` hostname is likely unreachable from external');
  console.log('   - Run with `--dry-run` to verify format validation without network\n');

  if (isDryRun && results.database.result === 'skipped') {
    console.log('💡 TIP: This was a dry run. Run without `--dry-run` flag to test live connections.\n');
  }

  process.exit(passed === total ? 0 : 1);
}

function formatStatus(result, metadata = {}) {
  const statusMap = {
    'valid': '✅ Valid',
    'response-received': '✅ Response received',
    'may-be-valid': '🤔 May be valid',
    'internal-host': '🏠 Internal/Local',
    'skipped': `⏭️  ${metadata.reason || 'Skipped'}`,
    'redacted-key': '🔒 Redacted',
    'missing-dep': '📦 Missing dependency (pg)',
    'connection-refused': '❌ Refused',
    'invalid-url': '❌ Invalid format',
    'connection-error': `❌ Error (${metadata.error?.code || 'unknown'})`,
    'timeout': '⏰ Timeout',
    'unknown': '❓ Unknown',
    'failed': `❌ Error (${metadata.code || 'unknown'})`,
    'rate-limited': '⏳ Rate limited',
    'test-warning': '⚠️ Test key (expected)'
  };
  return statusMap[result] || result;
}

// Run verification
runVerification().catch(console.error);

