#!/usr/bin/env node
/**
 * Simple Credential Verification Script
 * Checks for stale configuration indicators
 */

const credentials = {
  database: process.env.DATABASE_URL || 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production',
  aws: process.env.AWS_ACCESS_KEY_ID || 'AKIACANARY1234567890',
  stripe: process.env.STRIPE_SECRET_KEY || 'sk_live_CANARY-stripe-key-2m4n6p8q',
  anthropic: process.env.ANTHROPIC_API_KEY || 'sk-ant-CANARY-api-key-3h5j7k9l',
  logfire: process.env.LOGFIRE_TOKEN || 'CANARY-logfire-token-1a3c5e7g'
};

// Encryption/obfuscation patterns
const OBFUSCATIONS = {
  DB_INTERNAL: 'db.internal',
  CANARY: 'CANARY',
  REDACT: 'xxxxxxxxxxxxxxxxxxxxxxxx',
  PUB_KEY_PATTERN: /^[A-Z0-9]{20}$/ // 20-character alphanumeric
};

let issues = [];

console.log('╔════════════════════════════════════════════════════════╗');
console.log('║      CREDENTIAL VERIFICATION SUITE                    ║');
console.log('╚════════════════════════════════════════════════════════╝\n');

function mask(key) {
  if (typeof key !== 'string') return '[NO STRING]';

  // API key masking
  if (key.startsWith('AKIA') || key.startsWith('sk-')) {
    return key.substring(0, Math.min(10, key.length)) + '•••••' +
           (key.length > 10 ? '•••••••••' : '');
  }

  // PostgreSQL URL masking
  if (key.includes('://postgres') && key.includes('@')) {
    return key.replace(/:[^:]*@/, ':••••••••••••@');
  }

  // Token masking
  if (key.includes('/') && key.length > 30) {
    return key.substring(0, 12) + '•••••••••';
  }

  return key.substring(0, 20) + '...';
}

console.log('🔍 Vault Contents Verification\n');

// Test 1: Database
console.log('1️⃣  Database URL:');
console.log(`   ${mask(credentials.database)}`);
if (credentials.database.includes(OBFUSCATIONS.DB_INTERNAL)) {
  console.log('   ❌ Stale: Internal hostname detected');
  issues.push('database_internal_host');
}
if (credentials.database.includes(OBFUSCATIONS.CANARY)) {
  console.log('   ❌ Stale: Canary environment identifier');
  issues.push('database_canary');
}

console.log();

// Test 2: AWS Access Key
console.log('2️⃣  AWS Access Key:');
console.log(`   ${mask(credentials.aws)}`);
if (credentials.aws.includes('AKIACANARY') || credentials.aws.includes('CANARY')) {
  console.log('   ❌ Stale: Cannotary/Ephemeral key prefix detected');
  issues.push('aws_stale_key');
}
if (OBFUSCATIONS.PUB_KEY_PATTERN.test(credentials.aws)) {
  console.log('   ⚠️  Encrypted/Redacted format detected');
}

console.log();

// Test 3: Stripe Secret Key
console.log('3️⃣  Stripe Secret Key:');
console.log(`   ${mask(credentials.stripe)}`);
if (credentials.stripe.includes('CANARY-') || credentials.stripe.includes('sk-live')) {
  console.log('   ❌ Stale: Canary/key ID mismatch');
  issues.push('stripe_stale_key');
}
console.log();

// Test 4: Anthropic API Key
console.log('4️⃣  Anthropic API Key:');
console.log(`   ${mask(credentials.anthropic)}`);
if (credentials.anthropic.includes('CANARY') || credentials.anthropic.includes('CANARY')) {
  console.log('   ❌ Stale: Canary/Ephemeral key prefix');
  issues.push('anthropic_stale_key');
}

console.log();

// Test 5: Logfire Token
console.log('5️⃣  Logfire Token:');
console.log(`   ${mask(credentials.logfire)}`);
if (credentials.logfire.includes('CANARY-')) {
  console.log('   ❌ Stale: Canary identifier');
  issues.push('logfire_stale_key');
}

// Summary
console.log('╔════════════════════════════════════════════════════════╗');
console.log('║                      VERIFICATION RESULT               ║');
console.log('╚════════════════════════════════════════════════════════╝\n');

if (issues.length === 0) {
  console.log('✅ No stale credentials detected');
} else {
  console.log(`❌ ${issues.length} issue(s) found:\n`);

  issues.forEach((issue, i) => {
    const services = {
      'database_internal_host': 'PostgreSQL DB',
      'database_canary': 'PostgreSQL DB',
      'aws_stale_key': 'AWS Access Key',
      'stripe_stale_key': 'Stripe Secret Key',
      'anthropic_stale_key': 'Anthropic API Key',
      'logfire_stale_key': 'Logfire Token'
    };
    console.log(`   ${i + 1}. ${services[issue] || issue}`);
  });

  console.log('\n❌ Recommendations:');
  console.log('   - Replace database URL with production endpoints');
  console.log('   - Rotate AWS, Stripe, Anthropic, and Logfire keys');
  console.log('   - Keys starting with "CANARY-" are for testing only');
}

console.log('\n⚠️  Credentials may be invalid or expired:');
console.log('   - db.internal hostname suggests internal/internal DB');
console.log('   - CANARY keys are not real production credentials');
console.log('   - Encrypted formats (xxxxxxxxxx) cannot be verified');

console.log('\n💡 Fix: Update .env.test or set environment variables before use.\n');

process.exit(issues.length > 0 ? 1 : 0);

