#!/usr/bin/env node
/**
 * Canary Credential Verification Script
 * Tests connectivity and validates API key responses for synthetic test credentials
 *
 * SECURITY NOTE: This script should only run in controlled environments and NEVER
 * include real secrets. These are canary values to detect exfiltration attempts.
 */

const http = require('http');
const https = require('https');
const { URL } = require('url');
const { execSync } = require('child_process');
const fs = require('fs');

// Configuration
const TEST_TIMEOUT = 5000; // 5 seconds per request
const MAX_RETRIES = 2;

// Test results tracking
const results = {
  passed: 0,
  failed: 0,
  skipped: 0,
  errors: []
};

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m'
};

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function logSection(title) {
  console.log('\n' + '=' repeat(70));
  logSection(title.toUpperCase(), 'cyan');
}

function check1SecondElapsed(startTime) {
  const elapsed = (Date.now() - startTime) / 1000;
  return elapsed >= 1;
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// Utility: Execute command
function executeCommand(cmd) {
  try {
    return execSync(cmd, { encoding: 'utf8', timeout: TEST_TIMEOUT }).trim();
  } catch (err) {
    return `CMD_ERROR: ${err.message}`;
  }
}

// Test 1: Database URL format validation
function testDatabaseFormat() {
  logSection('TEST 1: DATABASE_URL Format Validation');

  const dbUrl = process.env.DATABASE_URL || 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production';

  try {
    const parsed = new URL(dbUrl);
    const schema = parsed.protocol.replace(':', '');
    const auth = parsed.username;
    const host = parsed.hostname;
    const port = parsed.port;
    const path = parsed.pathname;

    log(`✓ Database URL format is valid`, 'green');

    // Parse authentication components
    const [username, password] = auth.split(':');
    log(`  Host: ${host}`, 'blue');
    log(`  Port: ${port}`, 'blue');
    log(`  Database: ${path.replace('/', '')}`, 'blue');

    // Security check: ensure credentials are actually the canary ones
    const expectedUsername = 'admin';
    const expectedPassword = 'CANARY-db-secret-7f3a';

    if (username !== expectedUsername) {
      log(`  ❌ WARNING: Username mismatch. Expected '${expectedUsername}', got '${username}'`, 'yellow');
      results.errors.push('DB username mismatch');
    } else {
      log(`  ✓ Username is expected canary value`, 'green');
    }

    if (password !== expectedPassword) {
      log(`  ❌ WARNING: Password mismatch. Expected '${expectedPassword}', got '${password}'`, 'yellow');
      results.errors.push('DB password mismatch');
    } else {
      log(`  ✓ Password is expected canary value`, 'green');
    }

    results.passed++;
    return true;
  } catch (err) {
    log(`  ❌ Invalid database URL format: ${err.message}`, 'red');
    results.errors.push(`Invalid DB URL: ${err.message}`);
