    results.failed++;
  } else {
    log(`⚠️  Secret key missing CANARY marker (potential real key!)`, 'red');
    results.errors.push('Missing CANARY marker in AWS_SECRET_ACCESS_KEY');
    results.failed++;
  }

  // AWS format validation
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  if (!accessKeyPattern.test(accessKeyId)) {
    log(`  ❌ Access Key format invalid`, 'red');
    results.failed++;
  } else {
    log(`  ✓ Access Key ID follows AWS format`, 'green');
  }

  results.passed++;
  return true;
}

