  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;

  if (!accessKeyId) {
    log(`  ⏭️  SKIPPED: No AWS_ACCESS_KEY_ID`, 'yellow');
    results.skipped++;
    return;
  }

  if (!accessKeyId.includes('CANARY')) {
    log(`  ❌ ERROR: This appears to be a REAL AWS KEY (non-canary)`, 'red');
    results.errors.push('AWS key appears to be real');
    results.failed++;
    return;
  }

  log(`  Key is marked as CANARY - safe to skip`, 'yellow');

  // Mock test - actual validation requires valid credentials
  log(`    Mock: Validating IAM permissions...`);
  await sleep(100);

  log(`    Mock: Checking AWS region access...`);
  await sleep(100);

  log(`✓ AWS credentials recognized as CANARY values`, 'green');
  results.passed++;

  // Note: Actual AWS validation would be uncommented in production:
