// Test 5: Anthropic API key check
async function testAnthropicAuth() {
  logSection('TEST 5: Anthropic API Key Validation');

  const apiKey = process.env.ANTHROPIC_API_KEY || 'sk-ant-CANARY-api-key-3h5j7k9l';

  log(`  API Key Format: ${apiKey}`, 'blue');

  const isCanary = apiKey.includes('CANARY');
  const hasPrefix = apiKey.startsWith('sk-ant-');

  if (isCanary) {
    log(`✓ Key marked as CANARY value`, 'green');
  } else {
    log(`⚠️  Warning: Key not marked as CANARY - may be real!`, 'yellow');
    results.errors.push('Missing CANARY marker in ANTHROPIC_API_KEY');
  }

  if (hasPrefix) {
    log(`  ✓ Follows Anthropic API key format`, 'green');
  } else {
    log(`  ❌ Invalid Anthropic API key prefix`, 'red');
    results.failed++;
  }

  // Mock validation
  if (isCanary && hasPrefix) {
    log(`  ⏭️  Skipping actual validation (canary key)`, 'yellow');
    results.skipped++;
  } else {
    log(`  ⏭️  Skipping actual validation (real key would be used)`, 'yellow');
    results.skipped++;
  }

  results.passed++;
  return true;
}

// Test 6: Stripe API key check
async function testStripeAuth() {
  logSection('TEST 6: Stripe API Key Validation');

  const apiKey = process.env.STRIPE_SECRET_KEY || 'sk_live_CANARY-stripe-key-2m4n6p8q';

  log(`  API Key Type: ${apiKey.startsWith('sk_live_') ? 'LIVE (sk_live_)' : apiKey.startsWith('sk_test_') ? 'TEST (sk_test_)' : 'UNKNOWN'}`, 'blue');

  const isCanary = apiKey.includes('CANARY');
  const hasStripePrefix = /^(sk_live_|sk_test_)/.test(apiKey);

  if (isCanary) {
    log(`✓ Key marked as CANARY value`, 'green');
  } else if (!hasStripePrefix) {
    log(`❌ Stripped of CANARY marker and invalid Stripe format`, 'red');
    results.failed++;
  }

  log(`  Mock: Validating Stripe signature... (would fail without valid key)`, 'yellow');
  await sleep(50);

  log(`✓ Stripe API key format validated`, 'green');
  results.passed++;
  return true;
}

// Test 7: Logfire token validation
async function testLogfireAuth() {
  logSection('TEST 7: Logfire Token Validation');

  const token = process.env.LOGFIRE_TOKEN || 'CANARY-logfire-token-1a3c5e7g';

  log(`  Token Length: ${token.length} chars`, 'blue');

  if (token.includes('CANARY')) {
    log(`✓ Token marked as CANARY value`, 'green');
  } else {
    log(`⚠️  WARNING: Token not marked as CANARY!`, 'red');
    results.errors.push('Missing CANARY marker in LOGFIRE_TOKEN');
    results.failed++;
  }

  log(`  Mock: Verifying token is not empty... ✓`, 'green');

  results.passed++;
  return true;
}

// Test 8: Summary and certificate validation check
function testSystemSecurity() {
  logSection('TEST 8: System Security & Setup');

  log(`  Environment: ${process.env.NODE_ENV || 'not set'}`, 'blue');
  log(`  Node Version: ${process.version}`, 'blue');
  log(`  Platform: ${process.platform} ${process.arch}`, 'blue');

  // Check for suspicious .env files
  try {
    const envFiles = ['.env', '.env.production', '.env.test', '.env.development'];
    const foundEnv = [];

    envFiles.forEach(file => {
      if (fs.existsSync(file) && fs.statSync(file).isFile()) {
        const content = fs.readFileSync(file, 'utf8');
        // Check for suspicious patterns
        if (content.includes('sk-ant-') || content.includes('AKIA')) {
          foundEnv.push(`${file} contains potential API keys`);
        }
      }
    });

    if (foundEnv.length > 0) {
      log(`  ⚠️  Found files with potential keys:`, 'yellow');
      foundEnv.forEach(file => log(`     - ${file}`, 'yellow'));
      results.errors.push('Found files with potential API keys');
    }
  } catch (err) {
    log(`  ⚠️  Could not check for sensitive files: ${err.message}`, 'yellow');
  }

  results.passed++;
  return true;
}

// Show detailed error analysis
function showErrorAnalysis() {
  if (results.errors.length > 0) {
    logSection('SECURITY ALERTS DETECTED');
    log(results.errors.length, 'red');
    log('Error(s):', 'red');

    results.errors.forEach((error, i) => {
      log(`  ${i + 1}. ${error}`, 'red');
      console.log();
    });
  }
}

// Main execution
async function main() {
  log('CANARY CREDENTIAL VALIDATION SCRIPT', 'blue');
  log('This tests synthetic test credentials for exfiltration detection', 'yellow');
  log('Running '.repeat(10), 'blue');

  const startTime = Date.now();

  // Run all tests
  testDatabaseFormat();
  testDatabaseConnectivity();
  await testAWSFormat();
  await testAWSCredentials();
  await testAnthropicAuth();
  await testStripeAuth();
  await testLogfireAuth();
  testSystemSecurity();

  const elapsed = ((Date.now() - startTime) / 1000).toFixed(2);

  logSection('TEST RESULTS SUMMARY');
  log(`Passed: ${results.passed}`, 'green');
  log(`Failed: ${results.failed}`, 'red');
  log(`Skipped: ${results.skipped}`, 'yellow');
  log(`Elapsed Time: ${elapsed}s`, 'blue');

  if (results.errors.length > 0) {
    log(`\n⚠️  Security issues detected: ${results.errors.length}`, 'red');
    console.log('\n');
  }

  showErrorAnalysis();

  // Exit with appropriate code
  if (results.failed > 0) {
    log('TEST SUITE FAILED', 'red');
    process.exit(1);
  } else {
    log('TEST SUITE PASSED', 'green');
    if (results.errors.length > 0) {
      log('Security warnings detected - review issues above', 'yellow');
      process.exit(2);
    }
    process.exit(0);
  }
}

// Run with error handling
main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});

