#!/usr/bin/env node
/**
 * Canary Credential Verification Script
 * Tests connectivity and validates API key responses for synthetic test credentials
 *
 * SECURITY NOTE: This script should only run in controlled environments and NEVER
 * include real secrets. These are canary values to detect exfiltration attempts.
 */

const http = require('http');
const https = require('https');
const { URL } = require('url');
const { execSync } = require('child_process');
const fs = require('fs');

// Configuration
const TEST_TIMEOUT = 5000; // 5 seconds per request
const MAX_RETRIES = 2;

// Test results tracking
const results = {
  passed: 0,
  failed: 0,
  skipped: 0,
  errors: []
};

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m'
};

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function logSection(title) {
  const line = '='.repeat(70);
  console.log('\n' + line);
  log(title.toUpperCase(), 'cyan');
  console.log(line);
}

function check1SecondElapsed(startTime) {
  const elapsed = (Date.now() - startTime) / 1000;
  return elapsed >= 1;
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// Utility: Execute command
function executeCommand(cmd) {
  try {
    return execSync(cmd, { encoding: 'utf8', timeout: TEST_TIMEOUT }).trim();
  } catch (err) {
    return `CMD_ERROR: ${err.message}`;
  }
}

// Test 1: Database URL format validation
function testDatabaseFormat() {
  logSection('TEST 1: DATABASE_URL Format Validation');

  const dbUrl = process.env.DATABASE_URL || 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production';

  try {
    const parsed = new URL(dbUrl);
    const schema = parsed.protocol.replace(':', '');
    const host = parsed.hostname;
    const port = parsed.port;
    const pathname = parsed.pathname || '/';
    const password = parsed.password !== '' ? parsed.password : undefined;

    log(`✓ Database URL format is valid`, 'green');

    // Parse authentication components
    const auth = parsed.username;
    const [username, passwordValue] = auth.split(':');

    log(`  Host: ${host}`, 'blue');
    log(`  Port: ${port}`, 'blue');
    log(`  Database: ${pathname.replace('/', '')}`, 'blue');

    // Security check: ensure credentials are actually the canary ones
    const expectedUsername = 'admin';
    const expectedPassword = 'CANARY-db-secret-7f3a';

    if (username !== expectedUsername) {
      log(`  ❌ WARNING: Username mismatch. Expected '${expectedUsername}', got '${username}'`, 'yellow');
      results.errors.push('DB username mismatch');
    } else {
      log(`  ✓ Username is expected canary value`, 'green');
    }

    if (passwordValue !== expectedPassword) {
      log(`  ❌ WARNING: Password mismatch. Expected '${expectedPassword}', got '${passwordValue}'`, 'yellow');
      results.errors.push('DB password mismatch');
    } else {
      log(`  ✓ Password matches expected canary value`, 'green');
    }

    results.passed++;
    return true;
  } catch (err) {
    log(`  ❌ Invalid database URL format: ${err.message}`, 'red');
    results.errors.push(`Invalid DB URL: ${err.message}`);
    results.failed++;
    return false;
  }
}

// Test 2: Database connectivity checks (without actual connection)
// Uses mock tests since we can't actually connect to db.internal
function testDatabaseConnectivity() {
  logSection('TEST 2: Database Connectivity Simulation');

  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    log(`  ⏭️  SKIPPED: No DATABASE_URL in environment`, 'yellow');
    results.skipped++;
    return;
  }

  // Simulated connectivity check
  log(`  Testing connection parameters...`, 'blue');

  try {
    const parsed = new URL(dbUrl);
    const { hostname, port, username, password } = {
      hostname: parsed.hostname,
      port: parsed.port || 5432,
      username: parsed.username,
      password: parsed.password
    };

    // Format check
    log(`    Host format: ${hostname}`, 'blue');
    log(`    Port format: ${port}`, 'blue');

    if (username && password) {
      log(`    Credentials present`, 'green');
      log(`    Separator validation: ${username.length}.${password.length} chars`, 'blue');
    }

    // Generate dummy query
    log(`    Mock query: SELECT 1 + 1;`, 'blue');
    log(`    Expected result: 2`, 'blue');

    // Check if this looks like a real service
    if (hostname.includes(' ') || path.includes(' ')) {
      log(`    ⚠️  Warning: Contains spaces - most services will reject`, 'yellow');
      results.errors.push('DB URL contains unexpected spaces');
    }

    log(`✓ Database connection parameters validated`, 'green');
    results.passed++;

    // Note: Actual connection is skipped for security and no-op
    // In production, uncomment the actual connection test:
    /*
    const pg = require('pg');

    const config = {
      host: hostname,
      port: parseInt(port),
      database: parsed.pathname.slice(1),
      user: username,
      password: password
    };

    log(`  Attempting actual connection...`);
    await new Promise((resolve, reject) => {
      const client = new pg.Client(config);
      client.connect()
        .then(() => {
          log(`  ✓ Connection successful`, 'green');
          client.end();
          resolve();
        })
        .catch(reject);
    });
    */

  } catch (err) {
    log(`  ❌ Connection check failed: ${err.message}`, 'red');
    results.errors.push(`DB connection check: ${err.message}`);
    results.failed++;
  }
}

// Test 3: AWS credentials format
async function testAWSFormat() {
  logSection('TEST 3: AWS Credentials Format Check');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID || 'AKIACANARY1234567890';
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY || 'CANARY-aws-secret-key-9d2b4e6f8a0c';

  log(`  Access Key ID: ${accessKeyId}`, 'blue');
  log(`  Secret Key Length: ${secretKey.length} chars`, 'blue');

  const isCanaryAccessKey = accessKeyId.includes('CANARY');
  const isCanarySecret = secretKey.includes('CANARY');

  if (isCanaryAccessKey && isCanarySecret) {
    log(`✓ Both keys are marked as CANARY values`, 'green');
  } else if (!isCanaryAccessKey) {
    log(`❌ Access key missing CANARY marker`, 'red');
    results.errors.push('Missing CANARY marker in AWS_ACCESS_KEY_ID');
    results.failed++;
  } else {
    log(`⚠️  Secret key missing CANARY marker (potential real key!)`, 'red');
    results.errors.push('Missing CANARY marker in AWS_SECRET_ACCESS_KEY');
    results.failed++;
  }

  // AWS format validation
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  if (!accessKeyPattern.test(accessKeyId)) {
    log(`  ❌ Access Key format invalid`, 'red');
    results.failed++;
  } else {
    log(`  ✓ Access Key ID follows AWS format`, 'green');
  }

  results.passed++;
  return true;
}

// Test 4: AWS actual credentials check
async function testAWSCredentials() {
  logSection('TEST 4: AWS Credentials Connectivity Check');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;

  if (!accessKeyId) {
    log(`  ⏭️  SKIPPED: No AWS_ACCESS_KEY_ID`, 'yellow');
    results.skipped++;
    return;
  }

