#!/usr/bin/env node

/**
 * Security Validation Script for app.js
 * Tests various security scenarios and validates improvements
 */

const { performAttackTests } = require('./security-tests');

console.log('\n=== Security Validation Tests for app.js ===\n');

async function runSecurityTests() {
  try {
    // Run attack simulations
    const results = await performAttackTests();

    console.log('\n--- Attack Test Results ---\n');

    console.log('✅ Successful Tests (No vulnerabilities detected):');
    results.passed.forEach(test => {
      console.log(`  • ${test.description}`);
    });

    console.log('\n❌ Failed Tests (Potential security issues):');
    if (results.failed.length === 0) {
      console.log('  No critical security vulnerabilities detected!');
    } else {
      results.failed.forEach(test => {
        console.log(`  • ${test.description}`);
        console.log(`    Risk: ${test.risk}`);
      });
    }

    console.log('\n--- Security Score ---');
    const score = Math.round((results.passed.length / (results.passed.length + results.failed.length)) * 100);
    console.log(`Overall Security Score: ${score}%`);

    console.log('\n--- Recommendations ---');
    const recommendations = getRecommendations(results);
    recommendations.forEach(rec => {
      console.log(`  • ${rec}`);
    });

    console.log('\n=== Security Validation Complete ===\n');
    process.exit(results.failed.length === 0 ? 0 : 1);

  } catch (error) {
    console.error('Error running security tests:', error);
    process.exit(1);
  }
}

function getRecommendations(results) {
  const recommendations = [];

  // Check for common vulnerabilities
  results.failed.forEach(test => {
    if (test.type === 'rate-limiting') {
      recommendations.push('Implement rate limiting to prevent DoS attacks');
    }
    if (test.type === 'cors') {
      recommendations.push('Configure CORS to only allow approved origins');
    }
    if (test.type === 'input-validation') {
      recommendations.push('Add input validation for all user inputs');
    }
    if (test.type === 'error-handling') {
      recommendations.push('Implement proper error handling middleware');
    }
  });

  if (results.passed.length >= 5) {
    recommendations.push('Server appears to be well-protected');
  }

  return recommendations.length > 0 ? recommendations : [
    'Consider enabling Content Security Policy for additional protection',
    'Regularly update dependencies with npm audit fix',
    'Implement HTTPS/TLS certificates for data encryption'
  ];
}

// Run the tests if run directly
if (require.main === module) {
  runSecurityTests();
}

module.exports = { runSecurityTests };

