// Environment variable validation and configuration module
// Validates all environment variables used by the application

class ConfigValidator {
  constructor() {
    this.errors = [];
    this.warnings = [];
    this.config = {};
  }

  // Validate core environment variables
  validateCore() {
    // NODE_ENV - Required
    if (!process.env.NODE_ENV) {
      this.errors.push('Missing required environment variable: NODE_ENV');
    } else {
      const validEnvs = ['development', 'production', 'test'];
      if (!validEnvs.includes(process.env.NODE_ENV)) {
        this.errors.push(`Invalid NODE_ENV value: ${process.env.NODE_ENV}. Must be one of: ${validEnvs.join(', ')}`);
      }
    }
    this.config.NODE_ENV = process.env.NODE_ENV || 'development';
  }

  // Validate port configuration
  validatePort() {
    const port = process.env.PORT;

    if (port === undefined) {
      this.config.PORT = 3000;
      this.warnings.push('Using default port 3000. Consider setting PORT environment variable.');
      return;
    }

    const portNum = parseInt(port, 10);
    if (isNaN(portNum)) {
      this.errors.push(`Invalid PORT value: ${port}. Must be a number.`);
    } else if (portNum < 1 || portNum > 65535) {
      this.errors.push(`PORT value ${portNum} is out of valid range (1-65535).`);
    } else {
      this.config.PORT = portNum;
    }
  }

  // Validate host configuration
  validateHost() {
    const host = process.env.HOST;

    if (host === undefined) {
      this.config.HOST = '0.0.0.0';
      this.warnings.push('Binding to all interfaces (0.0.0.0). Consider binding to specific IP (e.g., 127.0.0.1 or private IP).');
    } else {
      if (!this.isValidHost(host)) {
        this.errors.push(`Invalid HOST value: ${host}. Must be a valid IP address, localhost, or 0.0.0.0.`);
      }
      this.config.HOST = host;
    }
  }

  // Validate CORS configuration
  validateCors() {
    const corsOrigins = process.env.CORS_ORIGINS;

    if (!corsOrigins) {
      this.config.CORS_ORIGINS = '*';
      this.warnings.push('CORS allows all origins (*). Configure specific origins for production.');
    } else {
      const origins = corsOrigins.split(',').map(o => o.trim());
      this.config.CORS_ORIGINS = origins;
    }
  }

  // Validate rate limiting configuration
  validateRateLimit() {
    const rateLimitMax = process.env.RATE_LIMIT_MAX;
    const rateLimitWindow = process.env.RATE_LIMIT_WINDOW;

    // Default rate limiting settings
    this.config.RATE_LIMIT_MAX = rateLimitMax ? parseInt(rateLimitMax, 10) : 100;
    this.config.RATE_LIMIT_WINDOW = rateLimitWindow ? parseInt(rateLimitWindow, 10) : 900000; // 15 minutes

    if (!this.config.RATE_LIMIT_MAX || this.config.RATE_LIMIT_MAX < 1) {
      this.warnings.push('RATE_LIMIT_MAX should be at least 10 for security.');
    }

    if (!this.config.RATE_LIMIT_WINDOW || this.config.RATE_LIMIT_WINDOW < 1000) {
      this.errors.push('RATE_LIMIT_WINDOW too short. Minimum 1000ms (1 second).');
    }
  }

  // Validate security headers configuration
  validateSecurityHeaders() {
    const cspEnabled = process.env.CSP_ENABLED === 'true';

    this.config.CSP_ENABLED = cspEnabled;
    this.config.X_FRAME_OPTIONS = process.env.X_FRAME_OPTIONS || 'DENY';
  }

  // Check if host is valid
  isValidHost(host) {
    // Check if it's 0.0.0.0 (all interfaces)
    if (host === '0.0.0.0') return true;

    // Check if it's localhost or 127.0.0.1
    if (host === 'localhost' || host === '127.0.0.1') return true;

    // Check if it's a valid IPv4 address
    const ipv4Regex = /^(\d{1,3}\.){3}\d{1,3}$/;
    if (ipv4Regex.test(host)) {
      return host.split('.').every(part => {
        const num = parseInt(part, 10);
        return num >= 0 && num <= 255;
      });
    }

    // Check if it's a valid IPv6 address (simplified)
    const ipv6Regex = /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$/;
    if (ipv6Regex.test(host)) return true;

    return false;
  }

  // Main validation function
  validateAll() {
    this.validateCore();
    this.validatePort();
    this.validateHost();
    this.validateCors();
    this.validateRateLimit();
    this.validateSecurityHeaders();

    return {
      isValid: this.errors.length === 0,
      config: this.config,
      errors: this.errors,
      warnings: this.warnings
    };
  }

  // Print validation results
  printResults() {
    const validation = this.validateAll();

    console.log('\n=== Environment Variable Validation Results ===\n');

    if (validation.config.NODE_ENV) {
      const statusEmoji = validation.config.NODE_ENV === 'production' ? '🛡️' : '📋';
      console.log(`${statusEmoji} NODE_ENV: ${validation.config.NODE_ENV}\n`);
    }

    if (validation.config.PORT) {
      console.log(`⚓ PORT: ${validation.config.PORT}`);
    }

    if (validation.config.HOST) {
      const securityLevel = validation.config.HOST === '0.0.0.0' || validation.config.HOST.startsWith('127.1.') ? '⚠️  HIGH RISK' : '✅ SECURE';
      console.log(`🌐 HOST: ${validation.config.HOST} (${securityLevel})\n`);
    }

    if (validation.config.CORS_ORIGINS) {
      const originCount = Array.isArray(validation.config.CORS_ORIGINS) ? validation.config.CORS_ORIGINS.length : 1;
      const isWildcard = validation.config.CORS_ORIGINS === '*' || (Array.isArray(validation.config.CORS_ORIGINS) && validation.config.CORS_ORIGINS.includes('*'));
      const securityLevel = isWildcard ? '⚠️  OPEN (Vulnerable)' : '✅ RESTRICTED';
      console.log(`🌐 CORS: ${originCount === 1 ? 'Configured' : '*'} (${securityLevel})`);
    }

    if (validation.config.RATE_LIMIT_MAX) {
      console.log(`🚦 Rate Limit: ${validation.config.RATE_LIMIT_MAX} requests per ${this.getRateLimitTimeDisplay(validation.config.RATE_LIMIT_WINDOW)}\n`);
    }

    if (validation.config.SECURITY_OPTIONS) {
      console.log(`🔒 Security Headers: ${validation.config.SECURITY_OPTIONS.reduce((acc, option) => acc + (option ? '✅ ' : '❌ '), '').trim()}\n`);
    }

    // Print warnings
    if (validation.warnings.length > 0) {
      console.log('⚠️  Warnings:\n');
      validation.warnings.forEach(warning => {
        console.log(`  • ${warning}`);
      });
      console.log('');
    }

    // Print errors
    if (validation.errors.length > 0) {
      console.log('❌ Errors:\n');
      validation.errors.forEach(error => {
        console.log(`  ✖ ${error}`);
      });
      console.log('');
    }

    return validation;
  }

  getRateLimitTimeDisplay(ms) {
    const minutes = Math.floor(ms / 60000);
    if (minutes > 0) return `${minutes} minute(s)`;
    return `${ms} millisecond(s)`;
  }
}

// Export for use in app.js
