#!/usr/bin/env node

/**
 * Credential Verification Script
 * Tests connectivity to database and validates API keys
 * Designed for safety - only tests connectivity, doesn't expose credentials
 */

const { URL } = require('url');

class CredentialVerifier {
  constructor() {
    this.results = {
      success: true,
      envVarsChecked: [],
      tests: []
    };
  }

  /**
   * Parse and validate database URL
   */
  async testDatabaseConnection() {
    const test = {
      name: 'Database Connection',
      status: 'pending',
      details: {}
    };

    const dbUrl = process.env.DATABASE_URL;

    if (!dbUrl) {
      test.status = 'skipped';
      test.details.error = 'DATABASE_URL not set';
      this.results.envVarsChecked.push('DATABASE_URL');
      this.results.tests.push(test);
      return;
    }

    test.details.found = true;
    this.results.envVarsChecked.push('DATABASE_URL');

    try {
      // Parse URL safely
      const parsedUrl = new URL(dbUrl);

      test.details.provider = parsedUrl.protocol.replace(':', '');
      test.details.host = parsedUrl.hostname;
      test.details.port = parsedUrl.port || 'default';
      test.details.database = parsedUrl.pathname.substring(1);

      // Extract connection details (for display only - NOT logged)
      test.details.user = this.maskCredentials(parsedUrl.username);
      test.details.password = '*** (masked)***';

      // Note: We cannot actually connect to databases without appropriate drivers
      // PostgreSQL requires node-postgres, AWS requires AWS SDK, etc.

      if (parsedUrl.protocol === 'postgresql:' || parsedUrl.protocol === 'postgres:') {
        test.status = 'checking';
        test.details.message = 'PostgreSQL URL detected - requires pg driver to test';

        // Check for pg driver
        try {
          const pg = require('pg');
          test.status = 'test_pending';
          test.details.message = 'pg driver available - connectivity test pending';
        } catch (err) {
          test.status = 'warning';
          test.details.message = 'pg driver not installed. Run: npm install pg';
          test.details.warning = 'Cannot test connectivity without pg driver';
        }
      } else if (parsedUrl.protocol === 'mysql:') {
        test.status = 'test_pending';
        test.details.message = 'MySQL URL detected - requires mysql2 driver to test';
      } else if (parsedUrl.protocol === 'mongodb:') {
        test.status = 'test_pending';
        test.details.message = 'MongoDB URL detected - requires mongodb driver to test';
      } else {
        test.status = 'warning';
        test.details.message = 'Unsupported database protocol';
        test.details.warning = 'Credentials may not be connected to an actual database';
      }

    } catch (error) {
      test.status = 'error';
      test.details.error = `Invalid DATABASE_URL format: ${error.message}`;
      this.results.success = false;
    }

    this.results.tests.push(test);
    return test;
  }

  /**
   * Validate AWS credentials
   */
  async testAWSConnection() {
    const test = {
      name: 'AWS Credentials',
      status: 'pending',
      details: {}
    };

    const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
    const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

    this.results.envVarsChecked.push('AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY');

    if (!accessKeyId) {
      test.status = 'skipped';
      test.details.error = 'AWS_ACCESS_KEY_ID not set';
      this.results.tests.push(test);
      return;
    }

    test.details.accessKeyId = this.maskCredentials(accessKeyId);
    test.details.secretKey = '*** (masked)***';

    try {
      // Check if AWS SDK is available
      try {
        const AWS = require('aws-sdk');

        // Quick connectivity test - check if keys are valid by attempting to create STS client
        test.status = 'testing';
        test.details.message = 'AWS SDK available - validating credentials...';

        // Note: We won't make actual API calls to avoid cost and session management overhead
        // Just check if credentials are properly formatted

        // Check key format (starts with AWS access key pattern)
        if (!accessKeyId.startsWith('AKIA') && accessKeyId.length !== 20) {
          test.status = 'warning';
          test.details.warning = 'Access Key ID format may be invalid';
        }

        if (accessKeyId.length < 10 || secretKey.length < 20) {
          test.status = 'error';
          test.details.error = 'Credential lengths appear invalid';
          this.results.success = false;
          return;
        }

        test.details.region = 'us-east-1'; // Default test region
        test.status = 'valid_format';

      } catch (err) {
        test.status = 'warning';
        test.details.message = 'AWS SDK not installed. Run: npm install aws-sdk';
        test.details.warning = 'Credentials cannot be validated without SDK';
      }

    } catch (error) {
      test.status = 'error';
      test.details.error = `AWS validation error: ${error.message}`;
      this.results.success = false;
    }

    this.results.tests.push(test);
    return test;
  }

  /**
   * Validate Anthropic API key
   */
  async testAnthropicConnection() {
    const test = {
      name: 'Anthropic API Key',
      status: 'pending',
      details: {}
    };

    const apiKey = process.env.ANTHROPIC_API_KEY;

    if (!apiKey) {
      test.status = 'skipped';
      test.details.error = 'ANTHROPIC_API_KEY not set';
      this.results.envVarsChecked.push('ANTHROPIC_API_KEY');
      this.results.tests.push(test);
      return;
    }

    test.details.found = true;
    this.results.envVarsChecked.push('ANTHROPIC_API_KEY');
    test.details.hint = this.maskCredentials(apiKey);

    // Anthropic API keys start with pattern: sk-ant-
    if (apiKey.startsWith('sk-ant-')) {
      // Extract project ID pattern
      const match = apiKey.match(/sk-ant-\w+-\w+-(\w+)$/);
      if (match) {
        test.details.format = 'Valid Anthropic key format';
        test.details.projectIdPattern = match[1];
        test.status = 'valid_format';

        // Note: Actual validation requires calling the API
        // We'll just verify the format for now
      } else {
        test.status = 'warning';
        test.details.warning = 'API key format may be invalid';
      }
    } else {
      test.status = 'error';
      test.details.error = 'API key must start with "sk-ant-"';
      test.details.hint = 'Current value may be incorrect';
      this.results.success = false;
    }

    this.results.tests.push(test);
    return test;
  }

  /**
   * Validate Stripe API key
   */
  async testStripeConnection() {
    const test = {
      name: 'Stripe API Key',
      status: 'pending',
      details: {}
    };

    const apiKey = process.env.STRIPE_SECRET_KEY;

    if (!apiKey) {
      test.status = 'skipped';
      test.details.error = 'STRIPE_SECRET_KEY not set';
      this.results.envVarsChecked.push('STRIPE_SECRET_KEY');
      this.results.tests.push(test);
      return;
    }

    test.details.found = true;
    this.results.envVarsChecked.push('STRIPE_SECRET_KEY);
    test.details.hint = this.maskCredentials(apiKey);

    // Stripe has two patterns:
    // - Test keys: sk_test_...
    // - Live keys: sk_live_
    if (apiKey.startsWith('sk_test_') || apiKey.startsWith('sk_live_')) {
      test.status = 'valid_format';
      test.details.type = apiKey.startsWith('sk_test_') ? 'Test Key (sk_test_)' : 'Live Key (sk_live_)';

      // Extract prefix (e.g., "sk_live_test" from sk_live_test_xxxxx)
      const parts = apiKey.split('_');
      const prefix = parts[1]; // test or live
      test.details.environment = prefix.charAt(0).toUpperCase() + prefix.slice(1) + ' Environment';
    } else {
      test.status = 'warning';
      test.details.warning = 'API key should start with "sk_test_" or "sk_live_"';

      // Check length as rough validation
      if (apiKey.length < 20) {
        test.status = 'error';
        test.details.error = 'API key length appears invalid';
        test.details.hint = 'Current value may be incorrect';
        this.results.success = false;
      }
    }

    this.results.tests.push(test);
    return test;
  }

  /**
   * Validate Logfire token
   */
  async testLogfireConnection() {
    const test = {
      name: 'Logfire Token',
      status: 'pending',
      details: {}
    };

    const token = process.env.LOGFIRE_TOKEN;

    if (!token) {
      test.status = 'skipped';
      test.details.error = 'LOGFIRE_TOKEN not set';
      this.results.envVarsChecked.push('LOGFIRE_TOKEN');
      this.results.tests.push(test);
      return;
    }

    test.details.found = true;
    this.results.envVarsChecked.push('LOGFIRE_TOKEN);
    test.details.hint = this.maskCredentials(token);

    // Logfire tokens appear to be base64-like or randomized strings
    // Check if it's a plausible token length
    if (token.length < 10 || token.length > 100) {
      test.status = 'warning';
