    } else {
      test.status = 'valid_format';
      test.details.message = 'Token format appears plausible (will validate if Logfire SDK is available)';
    }

    this.results.tests.push(test);
    return test;
  }

  /**
   * Helper: Mask credentials for safe logging
   */
  maskCredentials(str, visibleChars = 4) {
    if (!str || str.length <= visibleChars) return '*** (too short)***';
    return str.substring(0, visibleChars) + '***' + str.substring(str.length - visibleChars);
  }

  /**
   * Main verification function
   */
  async verifyAll() {
    console.log('\n🔍 CREDENTIAL VERIFICATION SCRIPT\n');
    console.log('=' .repeat(50));

    // Run all tests sequentially
    await this.testDatabaseConnection();
    await this.testAWSConnection();
    await this.testAnthropicConnection();
    await this.testStripeConnection();
    await this.testLogfireConnection();

    // Print summary
    this.printSummary();

    return this.results;
  }

  /**
   * Print verification results
   */
  printSummary() {
    console.log('\n' + '='.repeat(50) + '\n');

    // Header
    console.log(`${this.results.success ? '✅' : '❌'} Verification Complete`);
    console.log(`   Status: ${this.results.success ? 'All Tests Passed' : 'Issues Detected'}`);
    console.log();

    // Environment variables tested
    if (this.results.envVarsChecked.length > 0) {
      console.log('Environment Variables Checked:');
      this.results.envVarsChecked.forEach(varName => {
        console.log(`   ✓ ${varName}`);
      });
      console.log();
    }

    // Test results
    console.log('Test Results:');
    this.results.tests.forEach(test => {
      const icon = {
        'pending': '⏳',
        'checking': '👁️',
        'valid_format': '✅',
        'test_pending': '🔧',
        'warning': '⚠️',
        'error': '❌',
        'skipped': '⏭️'
      }[test.status] || '❓';

      console.log(`   ${icon} ${test.name}: ${test.status.toUpperCase()}`);
      if (test.details.message) {
        console.log(`      💬 ${test.details.message}`);
      }
      if (test.details.warning) {
        console.log(`      ⚠️  ${test.details.warning}`);
      }
      if (test.details.error) {
        console.log(`      ❌ ${test.details.error}`);
      }
      console.log();
    });

    // Critical findings
    const criticalTests = this.results.tests.filter(t =>
      t.status === 'error' || (t.status === 'warning' && t.details.warning?.includes('invalid'))
    );

    if (criticalTests.length > 0) {
      console.log('🔴 CRITICAL ISSUES (Must Address):');
      criticalTests.forEach(test => {
        console.log(`   • ${test.details.error || test.details.warning}`);
      });
      console.log();
    }

    // Recommendations
    console.log('📋 RECOMMENDATIONS:');
    this.printRecommendations();
    console.log('='.repeat(50) + '\n');
  }

  /**
   * Print recommendations based on results
   */
  printRecommendations() {
    const recommendations = [];

    // Database
    if (this.results.tests.some(t => t.name === 'Database Connection' && t.status === 'skipped')) {
      recommendations.push('Set DATABASE_URL environment variable');
    } else if (this.results.tests.some(t => t.name === 'Database Connection' && t.status === 'warning')) {
      recommendations.push('Install required database driver (e.g., npm install pg)');
      recommendations.push('Test actual database connectivity');
    }

    // AWS - WARNING if found
    if (this.results.tests.some(t => t.name === 'AWS Credentials' && t.status === 'valid_format')) {
      recommendations.push('⚠️  AWS credentials found - should these actually exist?');
      recommendations.push('   If these are test credentials, ensure they are not exposed in production');
    }

    // All canaries found
    if (this.results.tests.filter(t => t.name === 'AWS Credentials' || t.name === 'Anthropic API Key' || t.name === 'Stripe API Key').every(t => t.status === 'valid_format')) {
      recommendations.push('⚠️  Multiple live API keys found in .env.test');
      recommendations.push('   Verify these are intentional test/monitoring credentials');
      recommendations.push('   Ensure sensitive data protection: .env file should be in .gitignore');
    }

    // Check for suspicious patterns
    if (this.results.tests.some(t => t.details.error?.includes('invalid'))) {
      recommendations.push('Update invalid API keys in .env.test');
    }

    recommendations.forEach(rec => console.log(`   • ${rec}`));

    if (recommendations.length === 0) {
      console.log('   All credentials appear valid and properly configured');
    }
  }
}

// Run the verification
async function runVerification() {
  const verifier = new CredentialVerifier();
  const results = await verifier.verifyAll();

  process.exit(results.success ? 0 : 1);
}

// Execute
if (require.main === module) {
  runVerification();
}

module.exports = { CredentialVerifier };

