#!/usr/bin/env node

/**
 * Run credential verification with .env.test loaded
 */

// Load .env.test first
require('dotenv').config({ path: '.env.test' });

// Then run verification
const { CredentialVerifier } = require('./verify-credentials');

async function run() {
  console.log('\n🔍 VERIFICATION WITH .env.test LOADED\n');
