#!/bin/bash

# Disaster Recovery Backup Service Simulator
# Simulates the /api/dr-backup endpoint on port 3003

echo "🚨 DISASTER RECOVERY SERVICE SIMULATOR"
echo ======================================

# Set port
PORT=${1:-3003}

