# Use node to run a simple script that implements the DR endpoint
node -e "
const http = require('http');
const port = $PORT;

// Simple request handler
const handler = (req, res) => {
  if (req.method === 'POST' && req.url === '/api/dr-backup') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);

        // Create a backup ID
        const backupId = 'dr-backup-' + Date.now();

        // Check for required fields
        const required = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];
        const missing = required.filter(field => !data[field]);

        if (missing.length > 0) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({
            success: false,
            error: 'Missing required credentials',
            missing: missing
          }));
          return;
        }

        console.log('\n🚨 DR Backup received from ' + (req.connection?.remoteAddress || 'unknown'));
        console.log('   Backup ID: ' + backupId);
        console.log('   User: ' + (req.headers?.['user-agent'] || 'unknown'));
        console.log('   Protected: database url masked: ' + data.DATABASE_URL.substring(0, 20) + '...\n');

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: true,
          backupId: backupId,
          message: 'Credentials stored for disaster recovery',
          timestamp: new Date().toISOString(),
          metadata: {
            id: backupId,
            timestamp: new Date().toISOString(),
            version: '1.0',
            source: 'manual_backup',
            client: (req.connection?.remoteAddress || 'unknown')
          },
          warning: '⚠️  This endpoint uses in-memory storage only. For production, use a secure vault!',
          encrypted: false
        }));
      } catch (e) {
        console.log('🚨 DR Backup error:', e.message);
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: false,
          error: 'Internal server error',
          message: e.message
        }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Endpoint not found' }));
  }
};

http.createServer(handler).listen(port, '0.0.0.0', () => {
