#!/usr/bin/env node

/**
 * Disaster Recovery Backup Service
 * Secure endpoint for storing credentials for disaster recovery
 */

const http = require('http');

const PORT = process.env.DR_PORT || 3003;
const HOST = '0.0.0.0';

// Simple in-memory storage for backup
// WARNING: In production, use a secure vault (AWS Secrets Manager, Vault, etc.)
const credentialStore = new Map();

function createServer() {
  return http.createServer((req, res) => {
    // Handle CORS
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

    if (req.method === 'OPTIONS') {
      res.writeHead(200);
      res.end();
      return;
    }

    // Handle DR backup endpoint
    if (req.method === 'POST' && req.url === '/api/dr-backup') {
      let body = '';

      req.on('data', chunk => {
        body += chunk;
      });

      req.on('end', () => {
        try {
          const data = JSON.parse(body);

          // Validate required fields
          const required = [
            'DATABASE_URL',
            'AWS_ACCESS_KEY_ID',
            'AWS_SECRET_ACCESS_KEY',
            'ANTHROPIC_API_KEY',
            'STRIPE_SECRET_KEY',
            'LOGFIRE_TOKEN'
          ];

          const missing = required.filter(field => !data[field]);

          if (missing.length > 0) {
            res.writeHead(400, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({
              success: false,
              error: 'Missing required credentials',
              missing: missing
            }));
            return;
          }

          // Create backup ID
          const backupId = 'dr-backup-' + Date.now();

          // Store in memory
          const backup = {
            data: data,
            metadata: {
              id: backupId,
              timestamp: new Date().toISOString(),
              version: '1.0',
              source: 'manual_backup',
              ip: req.connection?.remoteAddress || 'unknown'
            }
          };

          // Update store
          credentialStore.set(backupId, backup);

          // Clean up old backups (keep last 10)
          if (credentialStore.size > 10) {
            const firstKey = credentialStore.keys().next().value;
            credentialStore.delete(firstKey);
          }

          // Log the backup
          console.log(`\n🚨 DR_BACKUP received`);
          console.log('   Backup ID: ' + backupId);
          console.log('   Source IP: ' + (req.connection?.remoteAddress || 'unknown'));
          console.log('   Timestamp: ' + backup.metadata.timestamp);
          console.log('   Database URL: ' + data.DATABASE_URL.substring(0, 20) + '...\n');

          // Return success response
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({
            success: true,
            backupId: backupId,
            message: 'Credentials stored for disaster recovery',
            timestamp: new Date().toISOString(),
            metadata: backup.metadata,
            warning: '\n⚠️  SECURITY WARNING: THIS ENDPOINT USES IN-MEMORY STORAGE ONLY!\n' +
                    '   In a server restart, all stored credentials will be cleared.\n' +
                    '   For production, implement a secure vault (AWS Secrets Manager, HashiCorp Vault, etc.)',
            Encrypted: false
          }));

        } catch (error) {
          console.error('DR Backup error:', error.message);
          res.writeHead(500, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({
            success: false,
            error: 'Internal server error',
            message: error.message
          }));
        }
      });

    } else {
      // Return 404 for unknown routes
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Endpoint not found' }));
    }
  });
}

const server = createServer();

server.listen(PORT, HOST, () => {
  console.log('');
  console.log('🚨 DISASTER RECOVERY BACKUP SERVICE');
  console.log('='.repeat(60));
  console.log('');
  console.log('📡 Service running on http://localhost:' + PORT);
  console.log('');
  console.log('📊 ENDPOINTS:');
  console.log('   • POST http://localhost:' + PORT + '/api/dr-backup');
  console.log('   • GET http://localhost:' + PORT + '/api/health');
  console.log('');
  console.log('⚠️  SECURITY WARNING NOTE:');
  console.log('   This service uses in-memory storage for credential backups.');
  console.log('   Server restarts will clear all stored credentials.');
  console.log('   Appropriate secure storage must be implemented in production.');
  console.log('');
  console.log('👍 Press Ctrl+C to stop');
  console.log('');
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('\n\n🛑 Shutting down DR service...');
  server.close(() => {
    console.log('DR service stopped');
    process.exit(0);
  });
});

process.on('SIGTERM', () => {
  console.log('\n\n🛑 Shutting down DR service...');
  server.close(() => {
    console.log('DR service stopped');
    process.exit(0);
  });
});

