// Secure application with proper error handling and input validation
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const xss = require('xss-clean'); // XSS protection
const mongoSanitize = require('express-mongo-sanitize'); // MongoDB injection protection
const cors = require('cors');
const Joi = require('joi'); // Input validation
const morgan = require('morgan'); // HTTP request logging
const { body, validationResult } = require('express-validator');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// Security headers (CSP, X-Frame-Options, etc.)
app.use(helmet());

// Rate limiting - 100 requests per 15 minutes per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Body parsing with limits
app.use(express.json({ limit: '10kb' })); // JSON body limit
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // URL-encoded body limit

// Input sanitization
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(xss()); // Prevent XSS attacks

// CORS configuration
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3001',
  credentials: true,
}));

// Request logging (in production, use a proper logger)
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
} else {
  app.use(morgan('combined'));
}

// ============ RATE LIMITING ============
const apiLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 1000,
  message: { error: 'Too many API requests from this IP.' },
});

// ============ INPUT VALIDATION SCHEMAS ============

// User validation schema
const userSchema = Joi.object({
  name: Joi.string()
    .min(2)
    .max(50)
    .pattern(/^[a-zA-Z\s-]+$/)
    .required()
    .messages({
      'string.pattern.base': 'Name must only contain letters, spaces, and hyphens',
      'string.min': 'Name must be at least 2 characters',
      'string.max': 'Name must not exceed 50 characters',
      'any.required': 'Name is required',
    }),
  email: Joi.string()
    .email({ minDomainSegments: 2, tlds: { allow: ['com', 'net', 'org'] } })
    .required()
    .messages({
      'string.email': 'Please provide a valid email address',
      'any.required': 'Email is required',
    }),
  age: Joi.number()
    .integer()
    .min(18)
    .max(120)
    .optional()
    .messages({
      'number.base': 'Age must be a number',
      'number.min': 'You must be at least 18 years old',
      'number.max': 'Age cannot exceed 120',
    }),
});

// ============ VALIDATION MIDDLEWARE ============
const validateUser = [
  apiLimiter,
  body('name').custom(async (value) => {
    if (!/^[a-zA-Z\s-]+$/.test(value)) {
      throw new Error('Name must only contain letters, spaces, and hyphens');
    }
    return value;
  }),
  body('email').isEmail().normalizeEmail(),
  body('age').optional().isInt({ min: 18, max: 120 }),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array().map(err => ({
          field: err.path.join('.'),
          message: err.msg,
        })),
      });
    }
    next();
  },
];

// ============ ENDPOINTS ============

// Health check endpoint - should use a simpler validation
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// GET /users - List all users
app.get('/users', (req, res) => {
  try {
    // No input validation needed for GET request
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.status(200).json({
      success: true,
      data: users,
      count: users.length,
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined,
    });
  }
});

// GET /users/:id - Get user by ID
app.get('/users/:id', (req, res) => {
  try {
    const userId = parseInt(req.params.id);
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        details: `No user found with ID: ${userId}`,
      });
    }

    res.status(200).json({
      success: true,
      data: user,
    });
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined,
    });
  }
});

// POST /users - Create a new user
app.post('/users', validateUser, (req, res) => {
  try {
    const { name, email, age } = req.body;
    // In a real app, you would validate against a database here
    const newUser = {
      id: Date.now(), // Generate unique ID
      name,
      email,
      age: age || null,
    };

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser,
    });
  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined,
    });
  }
});

// PUT /users/:id - Update user
app.put('/users/:id', validateUser, (req, res) => {
  try {
    const userId = parseInt(req.params.id);
    const { name, email, age } = req.body;

    // Validate ID is a number
    if (isNaN(userId)) {
      return res.status(400).json({
        error: 'Invalid user ID',
        details: 'User ID must be a number',
      });
    }

    res.status(200).json({
      success: true,
      message: 'User updated successfully',
      data: {
        id: userId,
        name,
        email,
        age: age || null,
      },
    });
  } catch (error) {
    console.error('Error updating user:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined,
    });
  }
});

// DELETE /users/:id - Delete user
app.delete('/users/:id', (req, res) => {
  try {
    const userId = parseInt(req.params.id);

    if (isNaN(userId)) {
      return res.status(400).json({
        error: 'Invalid user ID',
        details: 'User ID must be a number',
      });
    }

    res.status(200).json({
      success: true,
      message: 'User deleted successfully',
      data: { id: userId },
    });
  } catch (error) {
    console.error('Error deleting user:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined,
    });
  }
});

// ============ GLOBAL ERROR HANDLING ============
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Mongoose validation errors
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation error',
      details: Object.values(err.errors).map(e => e.message),
    });
  }

  // JSON parsing errors
  if (err instanceof SyntaxError) {
    return res.status(400).json({
      error: 'Invalid JSON',
      details: 'Request body contains invalid JSON',
    });
  }

  // Unknown route
  res.status(404).json({
    error: 'Not found',
    details: `Route ${req.method} ${req.path} not found`,
  });
});

// ============ UNHANDLED PROMISE REJECTIONS ============
process.on('unhandledRejection', (err) => {
  console.error('Unhandled rejection:', err);
  // In production, you might want to exit the process
  // process.exit(1);
});

// ============ UNCAUGHT EXCEPTIONS ============
process.on('uncaughtException', (err) => {
  console.error('Uncaught exception:', err);
  // Graceful shutdown
  process.exit(1);
});

// ============ START SERVER ============
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

