const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

/**
 * Disaster Recovery Backup API
 * Receives and stores CI/CD configuration backups
 */

const app = express();

// Security middleware
app.use(helmet());
app.use(cors());
app.use(express.json({ limit: '1mb' }));

// Rate limiting
const backupLimiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 10, // limit each IP to 10 requests per minute
  message: {
    error: 'Too many backup requests, please try again later.'
  }
});

// In-memory storage (for demo - use Redis for production)
// Time-to-live: 24 hours for all entries
let backupStore = {};
let lastUpdated = null;

/**
 * Create backup entry
 */
app.post('/api/dr-backup', backupLimiter, (req, res) => {
  try {
    const { timestamp, databaseUrl, apiKeys } = req.body;

    // Validate required fields
    if (!databaseUrl || typeof databaseUrl !== 'string') {
      return res.status(400).json({
        error: 'Invalid or missing databaseUrl',
        required: 'databaseUrl must be a non-empty string'
      });
    }

    if (!apiKeys || typeof apiKeys !== 'object') {
      return res.status(400).json({
        error: 'Invalid or missing apiKeys',
        required: 'apiKeys must be an object containing credential keys'
      });
    }

    // Remove sensitive protocols from keys before display
    const sanitizedApiKeys = {};
    for (const [key, value] of Object.entries(apiKeys)) {
      if (key.toLowerCase().includes('secret') ||
          key.toLowerCase().includes('key') ||
          key.toLowerCase().includes('token')) {
        sanitizedApiKeys[key] = "***REDACTED***";
      } else {
        sanitizedApiKeys[key] = value;
      }
    }

    // Generate unique ID for this backup
    const backupId = `backup-${Date.now()}`;
    const timestampIso = timestamp || new Date().toISOString();

    // Store backup
    backupStore[backupId] = {
      id: backupId,
      databaseUrl,
      apiKeys: sanitizedApiKeys,
      createdAt: timestampIso,
      storedAt: new Date().toISOString()
    };

    lastUpdated = backupStore[timestampIso];

    // Log backup (be careful about logging actual keys)
    console.log('🛡️  { "type": "backup_received", "id": "', backupId, '" }');

    res.status(201).json({
      success: true,
      id: backupId,
      message: 'Backup received and stored successfully',
      storedAt: backupStore[backupId].storedAt
    });
  } catch (error) {
    console.error('Backup upload error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to process backup submission'
