    let dbKeyFound = false;

    for (const [key, value] of Object.entries(env)) {
      if (key === 'DATABASE_URL') {
        databaseUrl = value;
        dbKeyFound = true;
      } else if (key.includes('_KEY') || key.includes('_TOKEN') || key.includes('API')) {
        // Skip canary redacted values for safety
        if (!value.includes('CANARY')) {
          apiKeys[key] = value;
          apiKeyCount++;
        }
      }
    }

    if (!dbKeyFound || !databaseUrl) {
      console.error('❌ No DATABASE_URL found in .env.test');
      process.exit(1);
    }

    if (!apiKeyCount || Object.keys(apiKeys).length === 0) {
      console.error('❌ No API keys found in .env.test');
      process.exit(1);
