    return null;
  }
  return validator.normalizeEmail(email);
};

const validateUserId = (id) => {
  const sanitized = String(id).trim();
  if (!/^uuid$/i.test(sanitized) && isNaN(Number(sanitized))) {
    return false;
  }
  return true;
};

const handleApiError = (res, statusCode, message, errorCode = 'ERROR') => {
  res.status(statusCode).json({ 
    success: false, 
    errorCode,
    message 
  });
};

const sendSuccessResponse = (res, statusCode = 200, data = null) => {
  res.status(statusCode).json({ 
    success: true, 
    data,
    timestamp: new Date().toISOString()
  });
};

// Routes

