    // Validate pagination parameters
    const page = parseInt(req.query.page) || 1;
    const limit = Math.min(parseInt(req.query.limit) || 10, 100); // Max 100 results
    const offset = (page - 1) * limit;

    // Securely get users - use parameterization to prevent injection
    // Ideally, this would query your database
    const mockUsers = [
      { id: 1, name: 'Alice', email: sanitizeEmail('alice@example.com') },
      { id: 2, name: 'Bob', email: sanitizeEmail('bob@example.com') },
