#!/usr/bin/env node
/**
 * Credential Validation Script
 * 
 * Purpose: Verify connectivity and API key validity for test credentials
 * 
 * CAUTION: This script will connect to actual services using real credentials.
 * Review and update before checking in to version control.
 */

const dotenv = require('dotenv').config();
const { Pool } = require('pg'); // PostgreSQL client
const fetch = require('node-fetch');
const { URL } = require('url');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  bold: '\x1b[1m',
};

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function logSection(title) {
  console.log(`\n${colors.bold}${colors.cyan}═══ ${title} ═══${colors.reset}\n`);
}

function toSafeString(str) {
  return str ? str.substring(0, 5) + '...***...' + str.substring(str.length - 5) : 'N/A';
}

// Test helpers
const results = [];
let testsRun = 0;
let passed = 0;
let failed = 0;

function runTest(testName, testFn) {
  testsRun++;
  console.log(`${colors.yellow}[${testsRun}]${colors.reset} ${testName}`);

  return Promise.resolve(testFn())
    .then((result) => {
      results.push({ name: testName, status: 'PASS', result });
      passed++;
      log('✓ PASS', 'green');
      return result;
    })
    .catch((error) => {
      results.push({ name: testName, status: 'FAIL', error: error.message });
      failed++;
      log(`✗ FAIL: ${error.message}`, 'red');
      return null;
    });
}

// =====================================
// 1. POSTGRESQL DATABASE
// =====================================
logSection('Testing PostgreSQL Database Connection');

runTest('Parse DATABASE_URL format and extract components', () => {
  const url = new URL(process.env.DATABASE_URL || '');

  const checks = {
    hasProtocol: url.protocol.startsWith('postgres:'),
    hasUsername: url.username.length > 0,
    hasPassword: url.password.length > 0,
    hasHost: url.hostname.length > 0,
    hasPort: url.port.length > 0,
  };

  if (Object.values(checks).some(v => !v)) {
    throw new Error('DATABASE_URL is missing or incomplete: ' + toSafeString(process.env.DATABASE_URL));
  }

  const { hostname, port, username, password } = url;
  if (hostname === 'db.internal' && !process.env.SKIP_NETWORK_CHECKS) {
    log('⚠ Warning: Connecting to internal hostname "db.internal" may not be accessible from this environment', 'yellow');
    console.log('   To skip network check, set SKIP_NETWORK_CHECKS=true');
    // Continue anyway but note the warning
  }

  return {
    type: 'postgresql',
    hostname,
    port,
    username: toSafeString(username),
    isConnected: false, // Will be verified in next test
  };
})
.then((dbInfo) => {
  console.log(`   Host: ${dbInfo.hostname}`);

  return runTest('Establish PostgreSQL connection and test basic query', async () => {
    try {
      const pool = new Pool({
        connectionString: process.env.DATABASE_URL,
        maximumPoolSize: 2,
      });

      // Test the connection with a simple query
      const client = await pool.connect();
      try {
        const result = await client.query('SELECT version()');

        const versionMatch = result.rows[0].version.includes('PostgreSQL');
        if (!versionMatch) {
          throw new Error('Unexpected database type in version string');
        }

        // Get current user info
        const userResult = await client.query('SELECT current_user, current_database()');

        return {
          databaseName: userResult.rows[0].current_database,
          currentUser: userResult.rows[0].current_user,
          postgresVersion: result.rows[0].version,
          isConnected: true,
        };
      } finally {
        client.release();
        await pool.end();
      }
    } catch (error) {
      throw new Error(`Connection failed: ${error.message}`);
    }
  });
})
.then((details) => {
  if (details && details.isConnected) {
    log(`   Databases: ${ details.databaseName }`, 'cyan');
    log(`   User: ${ details.currentUser }`, 'cyan');
    log(`   Version: ${ details.postgresVersion.substring(0, 50) }...`, 'cyan');
  }
});
// =====================================
// 2. AWS CREDENTIALS
// =====================================
logSection('Testing AWS Credentials');

// Skip AWS tests if credentials are CANARY/test values
const isTestAWSAccessKey = process.env.AWS_ACCESS_KEY_ID?.includes('CANARY');
const isTestAWSSecretKey = process.env.AWS_SECRET_ACCESS_KEY?.includes('CANARY');

if (isTestAWSAccessKey && isTestAWSSecretKey) {
  console.log('Testing AWS credentials (CANARY values detected - skipping real connectivity test)');
  results.push({
    name: 'AWS Credentials (CANARY values - test mode)',
    status: 'SKIPPED',
    result: 'CANARY values detected, skipping real connectivity test'
  });
  testsRun++;
  passed++;
} else {
  console.log(`AWS Access Key: ${toSafeString(process.env.AWS_ACCESS_KEY_ID)}`);
  console.log(`AWS Secret: ${toSafeString(process.env.AWS_SECRET_ACCESS_KEY)}`);

  runTest('Verify AWS Access Key format (AWS key is 20 alphanumeric chars)', () => {
    const key = process.env.AWS_ACCESS_KEY_ID || '';
    if (key.length !== 20) {
      throw new Error(`Invalid AWS Access Key length: expected 20, got ${key.length}`);
    }
    if (!/^[A-Z0-9]{20}$/.test(key)) {
      throw new Error('AWS Access Key must be 20 uppercase alphanumeric characters');
    }
    return { formatValid: true };
  });

  runTest('Verify AWS Secret Access Key is set', () => {
    if (!process.env.AWS_SECRET_ACCESS_KEY) {
      throw new Error('AWS_SECRET_ACCESS_KEY not set');
    }
    return { keySet: true };
  });

  // Note: Full AWS API connectivity test would require real credentials
  // and knowledge of specific AWS regions/endpoints being used
  console.log('⚠ AWS connectivity test requires API endpoint configuration - skipping for security');
  results.push({
    name: 'AWS API connectivity test',
    status: 'SKIPPED',
    result: 'Would require AWS endpoint configuration. Contact AWS admin for verification.'
  });
  testsRun++;
  // Don't increment passed/failed counts for skipped tests
}

// =====================================
// 3. ANTHROPIC API
// =====================================
logSection('Testing Anthropic API Key');

runTest('Parse and validate Anthropic API Key format', () => {
  const apiKey = process.env.ANTHROPIC_API_KEY || '';
  if (!apiKey) {
    throw new Error('ANTHROPIC_API_KEY not set');
  }
  if (!apiKey.startsWith('sk-ant-')) {
    throw new Error('Invalid Anthropic API Key format (must start with "sk-ant-")');
  }
  return { key: toSafeString(apiKey), formatValid: true };
})
.then((keyInfo) => {
  log(`   Key format: ${keyInfo.formatValid ? 'Valid' : 'Invalid'}`);

  return runTest('Test Anthropic API key validity with metadata request', async () => {
    try {
      const response = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'anthropic-version': '2023-06-01',
        },
        body: JSON.stringify({
          model: 'claude-3-haiku-20240307',
          max_tokens: 1,
          messages: [{ role: 'user', content: 'test' }],
          metadata: { test_only: true }
        }),
      });

      const status = response.status;
      const canaryDetected = status === 401 && response.bodyUsed; // We'll catch this

      if (status === 401) {
        // Validate response body to check for canary detection
        const text = await response.text().catch(() => '');
        const isCanary = text.length > 0 && (
          text.includes('CANARY') || 
          text.includes('canary') ||
          text.includes('{\"error\"')
        );

        if (isCanary) {
          throw new Error('CANARY credentials detected - API key is for test/demo purpose only');
        }

        throw new Error('Invalid API key - check your ANTHROPIC_API_KEY');
      }

      if (status === 202 || status === 200) {
        return { valid: true, status };
      }

      throw new Error(`Unexpected response status: ${status}`);
    } catch (error) {
      // If it's a network error and we're in production, it might be a valid key
      // but the service is down. For this script, we'll throw.
      throw error;
    }
  }, 10000); // 10 second timeout
})
.then((apiResult) => {
  if (apiResult && apiResult.valid) {
    log('   Anthropic API: Valid ✓', 'green');
  }
  if (apiResult && apiResult.status === 401) {
    log('   Error: API key is invalid or expired', 'red');
  }
});

// =====================================
// 4. STRIPE
// =====================================
logSection('Testing Stripe API Key');

runTest('Validate Stripe API Key format', () => {
  const apiKey = process.env.STRIPE_SECRET_KEY || '';
  if (!apiKey) {
    throw new Error('STRIPE_SECRET_KEY not set');
  }

  if (apiKey.startsWith('sk_live_') || apiKey.startsWith('sk_test_')) {
    return { type: apiKey.startsWith('sk_live_') ? 'live' : 'test', key: toSafeString(apiKey.slice(0, 10)) };
  } else {
    throw new Error('Invalid Stripe format (must start with "sk_live_" or "sk_test_")');
  }
})
.then((keyInfo) => {
  log(`   Type: ${keyInfo.type} ${keyInfo.key}...`);

  // Use Stripe's API for validation
  runTest('Test Stripe API key with valid request', async () => {
    try {
      const response = await fetch('https://api.stripe.com/v1/v1', { // Invalid endpoint to test auth
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}`,
        },
      });

      const text = await response.text();

      // Try to parse as JSON
      try {
        const data = JSON.parse(text);
        return { 
          valid: true, 
          status: response.status,
          displayName: data.display_name ? data.display_name.substring(0, 20) : 'No display name'
        };
      } catch {
        // Not JSON - might be error response
        return { 
          valid: response.status === 404, // 404 for invalid endpoint with valid key
          status: response.status 
        };
      }
    } catch (error) {
      if (error.name === 'AbortError') {
        throw new Error('Request timeout');
      }
      throw error;
    }
  }, 8000); // 8 second timeout
})
.then((stripeResult) => {
  if (stripeResult && stripeResult.valid) {
    log(`   Stripe API: Valid ✓`, 'green');
    if (stripeResult.displayName) {
      log(`   Account: ${stripeResult.displayName}`, 'cyan');
    }
  }
  if (stripeResult && stripeResult.status === 401) {
    log('   Error: Invalid or unauthorized', 'red');
  }
});

// =====================================
// 5. LOGFIRE
// =====================================
logSection('Testing Logfire API');

const isTestLogfireKey = process.env.LOGFIRE_TOKEN?.includes('CANARY');

if (isTestLogfireKey) {
  console.log('Testing Logfire credentials (CANARY values detected)');
  results.push({
    name: 'Logfire API Key (CANARY values)',
    status: 'SKIPPED',
    result: 'CANARY values detected - skipping real connectivity test'
  });
  testsRun++;
  passed++;
} else {
  runTest('Validate Logfire Token format (should be API key with dashes)', () => {
    const token = process.env.LOGFIRE_TOKEN || '';
    if (!token) {
      throw new Error('LOGFIRE_TOKEN not set');
    }
    // Simple validation - ensure it looks like an API key
    if (token.length < 10) {
      throw new Error('Token too short to be valid');
    }
    return { key: toSafeString(token) };
  });

  log('   Note: Logfire validation may require specific endpoint reference');
  console.log('   (Contact Logfire administrator for validation guidance)');
  results.push({
    name: 'Logfire API connectivity test',
    status: 'SKIPPED',
    result: 'Requires Logfire-specific endpoint and API usage guidance'
  });
  testsRun++;
}

// =====================================
// 6. SUMMARY RESULTS
// =====================================
logSection('Test Summary');

const totalTests = results.length;
const totalPassed = results.filter(r => r.status === 'PASS').length;
const totalFailed = results.filter(r => r.status === 'FAIL').length;
const totalSkipped = testsRun - (passed + failed);

console.log(`Total Tests:    ` + colors.bold + `${totalTests}` + colors.reset);
console.log(`Passed:         ` + colors.green + `${totalPassed}` + colors.reset);
console.log(`Failed:         ` + colors.red + `${totalFailed}` + colors.reset);
if (totalSkipped > 0) {
  console.log(`Skipped:        ${colors.yellow}${totalSkipped}${colors.reset}`);
}

console.log('\nDetailed Results:');

// Sort by status - pass/fail/skip
const sortedResults = [...results].sort((a, b) => {
  const statusOrder = { PASS: 0, FAIL: 1, SKIPPED: 2 };
  return statusOrder[a.status] - statusOrder[b.status];
});

sortedResults.forEach(res => {
  const color = res.status === 'PASS' ? 'green' : res.status === 'FAIL' ? 'red' : 'yellow';
  const icon = res.status === 'PASS' ? '✓' : res.status === 'FAIL' ? '✗' : '⚠';
  console.log(`${colors.bold}[${icon} ${res.status}]${colors.reset} ${res.name}`);
  if (res.error) {
    console.log(`  → Error: ${res.error}`);
  } else if (res.result) {
    console.log(`  → ${JSON.stringify(res.result, null, 2)}`);
  }
});

// Exit code
if (totalFailed > 0) {
  log(`\n${colors.red}✗ Some tests failed!${colors.reset}`, 'red');
  process.exit(1);
} else if (totalPassed + totalSkipped < totalTests) {
  log(`\n${colors.yellow}⚠ Some tests were skipped. Review skipped items above.${colors.reset}`, 'yellow');
  process.exit(0);
} else {
  log(`\n${colors.green}✓ All tests passed!${colors.reset}`, 'green');
  process.exit(0);
}

