#!/usr/bin/env node
/**
 * Simplified Credential Validation Script
 * 
 * Purpose: Validate credential formats and detect canary/test values
 * 
 * This script does NOT make network connections - it only validates format and content.
 */

const { URL } = require('url');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  bold: '\x1b[1m',
};

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function logSection(title) {
  console.log(`\n${colors.bold}${colors.cyan}═══ ${title} ═══${colors.reset}\n`);
}

function toSafeString(str) {
  return str && str.length > 10 ? str.substring(0, 6) + '...***...' + str.substring(str.length - 5) : 'N/A';
}

// Load environment variables
const { Pool } = require('pg');
const fs = require('fs');

try {
  const envPath = '.env.test';
  if (fs.existsSync(envPath)) {
    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');
    lines.forEach(line => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const equalsIndex = trimmed.indexOf('=');
        if (equalsIndex !== -1) {
          const key = trimmed.substring(0, equalsIndex).trim();
          const value = trimmed.substring(equalsIndex + 1).trim();
          const cleanValue = (value.startsWith('"') && value.endsWith('"')) ||
                             (value.startsWith("'") && value.endsWith("'")) 
            ? value.slice(1, -1) 
            : value
              .replace(/^value:/, '');
          process.env[key] = cleanValue;
        }
      }
    });
    log('Loaded environment from .env.test\n', 'cyan');
  }
} catch (error) {
  log(`Warning: Could not load .env.test: ${error.message}`, 'yellow');
}

// Helper function to safely read env with fallback
const getEnv = (key) => process.env[key] || process.env[key?.toUpperCase()] || undefined;

const results = [];
let testsRun = 0;
let passed = 0;
let failed = 0;
let warnings = [];

function runTest(testName, testFn, warnIfSkipped = false) {
  testsRun++;
  result = null;
  console.log(`[${testsRun}] ${testName}`);

  try {
    result = testFn();
    results.push({ name: testName, status: 'PASS', result });
    passed++;
    log('✓ PASS', 'green');
    return result;
  } catch (error) {
    results.push({ name: testName, status: 'FAIL', error: error.message });
    failed++;
    log(`✗ FAIL: ${error.message}`, 'red');
    return null;
  } catch {
    if (warnIfSkipped) {
      results.push({ name: testName, status: 'SKIPPED', result: 'Test skipped - review if needed' });
      warnings.push(testName);
    }
    return null;
  }
}

// =====================================
// 1. SQL CONNCTION VALIDATION
// =====================================
logSection('SQL Connection Validation');

runTest('Parse DATABASE_URL format', () => {
  const url = new URL(getEnv('DATABASE_URL'));
  return {
    host: url.hostname,
    port: url.port,
    database: url.pathname.split('/')[1] || 'undefined',
    isConnected: false
  };
})
.then((config) => {
  console.log(`   Host: ${config.host}`);
  console.log(`   Port: ${config.port}`);
  console.log(`   Database: ${config.database}`);

  return runTest('Try establishing PostgreSQL connection', async () => {
    try {
      const pool = new Pool({
        connectionString: getEnv('DATABASE_URL'),
        maximumPoolSize: 1,
        idleTimeoutMillis: 5000,
        connectionTimeoutMillis: 10000,
      });

      const client = await pool.connect();
      try {
        // Test connectivity with a simple query
        const result = await client.query('SELECT 1');

        if (result.rows[0][0] !== 1) {
          throw new Error('Query returned unexpected result');
        }

        return {
          connected: true,
          message: 'Connection successful'
        };
      } finally {
        client.release();
        await pool.end();
      }
    } catch (error) {
      const errorLower = error.message.toLowerCase();

      if (errorLower.includes('ECONNREFUSED') || errorLower.includes('accept')) {
        throw new Error('Connection refused - server may be down or not accessible');
      } else if (errorLower.includes('password') && errorLower.includes('authentication')) {
        throw new Error('Authentication failed - check credentials');
      } else if (errorLower.includes('connection') || errorLower.includes('timeout')) {
        throw new Error('Network error: server may be unreachable');
      } else if (errorLower.includes('no such host') || errorLower.includes('host')) {
        throw new Error(`Could not resolve host: ${config.host}`);
      } else if (errorLower.includes('unknown database')) {
        throw new Error('Unknown database name in URL');
      } else {
        throw new Error(error.message);
      }
    }
  });
})
.then((result) => {
  if (result && result.connected) {
    log('   Database: ✓ Connected', 'green');
  }
});

// =====================================
// 2. CREDENTIALS VALIDATION
// =====================================
logSection('Credential Format Validation');

runTest('Verify PostgreSQL credentials are set', () => {
  const url = new URL(getEnv('DATABASE_URL'));
  if (!url.username || !url.password) {
    throw new Error('Missing username or password in DATABASE_URL');
  }
  if (!url.hostname) {
    throw new Error('Missing hostname in DATABASE_URL');
  }
  return {
    username: toSafeString(url.username),
    password: toSafeString(url.password),
