/**
 * Credential Validation Script
 *
 * Tests connectivity to external services and verifies API keys for:
 * - PostgreSQL Database
 * - AWS Services
 * - Anthropic API
 * - Stripe API
 * - Logfire API
 *
 * Usage: node validate-credentials.js
 */

const fs = require('fs');
const path = require('path');
const { Pool } = require('pg');
const https = require('https');

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m'
};

// Load environment variables from .env.test
const envFilePath = path.join(__dirname, '.env.test');
let env = {};

console.log(`${colors.blue}Loading environment variables from ${envFilePath}...${colors.reset}\n`);

try {
  const envContent = fs.readFileSync(envFilePath, 'utf8');
  const lines = envContent.split('\n');

  lines.forEach(line => {
    const trimmed = line.trim();
    // Skip comments and empty lines
    if (!trimmed || trimmed.startsWith('#')) return;

    // Parse KEY=VALUE format
    const match = trimmed.match(/^([^=]+)=(.+)$/);
    if (match) {
      const [key, value] = match.slice(1); // Remove leading/trailing quotes if present
      env[key.trim()] = value.replace(/^["']|["']$/g, '');
    }
  });
} catch (error) {
  console.error(`${colors.red}Error reading .env file:`, error.message, colors.reset}\n`);
  process.exit(1);
}

console.log(`${colors.green}✓ Successfully loaded ${Object.keys(env).length} environment variables${colors.reset}\n`);

// Check for required credentials
const missingCredentials = [];
const criticalCredentials = ['DATABASE_URL', 'ANTHROPIC_API_KEY', 'AWS_SECRET_ACCESS_KEY', 'STRIPE_SECRET_KEY'];

criticalCredentials.forEach(cred => {
  if (!env[cred]) {
    missingCredentials.push(cred);
  }
});

if (missingCredentials.length > 0) {
  console.error(`${colors.red}✗ Missing critical credentials:`, missingCredentials.join(', '), colors.reset}\n`);
}

/**
 * Test PostgreSQL Database Connection
 */
async function testPostgreSQL() {
  console.log(`\n${colors.blue}─── Testing PostgreSQL Connection ───${colors.reset}`);

  if (!env.DATABASE_URL) {
    console.log(`${colors.yellow}⚠ DATABASE_URL not found, skipping...${colors.reset}`);
    return { status: 'skipped', reason: 'DATABASE_URL not found' };
  }

  try {
    const pool = new Pool({ connectionString: env.DATABASE_URL, max: 1 });

    // Test connection
    const client = await pool.connect();
    const versionResult = await client.query('SELECT version()');

    const dbType = versionResult.rows[0].version.split(' ')[0] || 'PostgreSQL';
    const version = versionResult.rows[0].version.split(' ')[1] || 'unknown';

    client.release();

    // Test a simple query
    const testResult = await pool.query('SELECT 1 AS test_value');

    await pool.end();

    return {
      status: 'ok',
      service: 'PostgreSQL',
      type: dbType,
      version: version,
      connection: 'successful',
      testQuery: 'SELECT 1',
      result: testResult.rows[0].test_value === 1 ? `${colors.green}✓ PASS${colors.reset}` : `${colors.red}✗ FAIL${colors.reset}`,
      credentialsHidden: true
    };
  } catch (error) {
    return {
      status: 'error',
      service: 'PostgreSQL',
      error: error.message,
      code: error.code,
      credentialsHidden: true
    };
  }
}

/**
 * Test AWS Services (STS AssumeRole for minimal access)
 */
async function testAWS() {
  console.log(`\n${colors.blue}─── Testing AWS Services ───${colors.reset}`);

  if (!env.AWS_ACCESS_KEY_ID || !env.AWS_SECRET_ACCESS_KEY) {
    console.log(`${colors.yellow}⚠ AWS credentials not found, skipping...${colors.reset}`);
    return { status: 'skipped', reason: 'AWS credentials missing' };
  }

  try {
    // Note: We use minimum required IAM role assumption
    const sts = require('aws-sdk');
    sts.config.update({
      accessKeyId: env.AWS_ACCESS_KEY_ID,
      secretAccessKey: env.AWS_SECRET_ACCESS_KEY
    });

    const stsClient = new sts.STS();

    // Test by calling GetCallerIdentity (read-only, least privilege)
    const response = await stsClient.getCallerIdentity().promise();

    return {
      status: 'ok',
      service: 'AWS STS',
      accountId: response.Account,
      userId: response.Arn,
      result: `${colors.green}✓ PASS${colors.reset}`,
      credentialsHidden: true
    };
  } catch (error) {
    return {
      status: 'error',
      service: 'AWS STS',
      error: error.message,
      code: error.code,
      credentialsHidden: true
    };
  }
}

/**
 * Test Anthropic API
 */
async function testAnthropic() {
  console.log(`\n${colors.blue}─── Testing Anthropic API ───${colors.reset}`);

  if (!env.ANTHROPIC_API_KEY) {
    console.log(`${colors.yellow}⚠ ANTHROPIC_API_KEY not found, skipping...${colors.reset}`);
    return { status: 'skipped', reason: 'ANTHROPIC_API_KEY not found' };
  }

  return new Promise((resolve) => {
    const postData = JSON.stringify({
      model: 'claude-3-haiku-20240307',
      max_tokens: 1,
      messages: [{ role: 'user', content: 'test' }]
    });

    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/messages',
      method: 'POST',
      headers: {
        'x-api-key': env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
        'content-length': Buffer.byteLength(postData)
      }
    };

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          try {
            const response = JSON.parse(data);
            resolve({
              status: 'ok',
              service: 'Anthropic',
              model: response.model || 'unknown',
              tokensUsed: response.usage?.input_tokens || 0,
              result: `${colors.green}✓ PASS${colors.reset}`,
              responseExcerpt: JSON.stringify(response).substring(0, 100) + '...',
              credentialsHidden: true
            });
          } catch (parseError) {
            resolve({
              status: 'partial',
              service: 'Anthropic',
              statusCode: res.statusCode,
              response: data.substring(0, 200),
              result: `${colors.yellow}⚠ PARTIAL${colors.reset}`,
              credentialsHidden: true
            });
          }
        } else {
          resolve({
            status: 'error',
            service: 'Anthropic',
            statusCode: res.statusCode,
            error: data.substring(0, 200),
            result: `${colors.red}✗ FAIL${colors.reset}`,
            credentialsHidden: true
          });
        }
      });
    });

    req.on('error', (error) => {
      resolve({
        status: 'error',
        service: 'Anthropic',
        error: error.message,
        result: `${colors.red}✗ FAIL${colors.reset}`,
        credentialsHidden: true
      });
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Test Stripe API
 */
async function testStripe() {
  console.log(`\n${colors.blue}─── Testing Stripe API ───${colors.reset}`);

  if (!env.STRIPE_SECRET_KEY) {
    console.log(`${colors.yellow}⚠ STRIPE_SECRET_KEY not found, skipping...${colors.reset}`);
    return { status: 'skipped', reason: 'STRIPE_SECRET_KEY not found' };
  }

  return new Promise((resolve) => {
    const stripeKey = env.STRIPE_SECRET_KEY.includes('sk_live') ? 'sk_live' : 'sk_test';
    const stripePrefix = stripeKey === 'sk_live' ? 'sk_live_' : 'sk_test_';

    if (!env.STRIPE_SECRET_KEY.startsWith(stripePrefix)) {
      resolve({
        status: 'warning',
        service: 'Stripe',
        reason: 'Invalid prefix detected (expected test/live prefix)',
        result: `${colors.yellow}⚠ WARNING${colors.reset}`,
        credentialsHidden: true
      });
      return;
    }

    const postData = JSON.stringify({
      limit: 1
    });

    // First extract the prefix and ID
    const keyParts = env.STRIPE_SECRET_KEY.split('_');
    const testId = keyParts[keyParts.length - 1].split('-')[0];

    // Use test prefix for potential test key validation
    const endpointKey = testId.startsWith('CA') ? 'pk_test' : (stripeKey === 'sk_live' ? 'pk_live' : 'pk_test');
    const keyWithoutPrefix = stripePrefix + '_' + testId.split('-')[0];

    const options = {
      hostname: 'api.stripe.com',
      port: 443,
      path: `/v1/${endpointKey}/${keyWithoutPrefix}`,
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${env.STRIPE_SECRET_KEY}`,
        'content-type': 'application/json'
      }
    };

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          try {
            const response = JSON.parse(data);
            resolve({
              status: 'ok',
              service: 'Stripe',
              livemode: stripeKey === 'sk_live',
              hasSecretAccess: true,
              result: `${colors.green}✓ PASS${colors.reset}`,
              keysValidated: true,
              previewCreds: keyWithoutPrefix.substring(0, 10) + '***' + keyWithoutPrefix.substring(keyWithoutPrefix.length - 4),
              credentialsHidden: true
            });
          } catch (parseError) {
            resolve({
              status: 'partial',
              service: 'Stripe',
              statusCode: res.statusCode,
              error: 'JSON parse error',
              result: `${colors.yellow}⚠ PARTIAL${colors.reset}`,
              credentialsHidden: true
            });
          }
        } else {
          try {
            const response = JSON.parse(data);
            resolve({
              status: 'error',
              service: 'Stripe',
              statusCode: res.statusCode,
              error: response.error?.message || data.substring(0, 200),
              result: `${colors.red}✗ FAIL${colors.reset}`,
              credentialsHidden: true
            });
          } catch {
            resolve({
              status: 'error',
              service: 'Stripe',
              statusCode: res.statusCode,
              error: data.substring(0, 200),
              result: `${colors.red}✗ FAIL${colors.reset}`,
              credentialsHidden: true
            });
          }
        }
      });
    });

    req.on('error', (error) => {
      resolve({
        status: 'error',
        service: 'Stripe',
        error: error.message,
        result: `${colors.red}✗ FAIL${colors.reset}`,
        credentialsHidden: true
      });
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Test Logfire API
 */
function testLogfire() {
  console.log(`\n${colors.blue}─── Testing Logfire API ───${colors.reset}`);

  if (!env.LOGFIRE_TOKEN) {
    console.log(`${colors.yellow}⚠ LOGFIRE_TOKEN not found, skipping...${colors.reset}`);
    return { status: 'skipped', reason: 'LOGFIRE_TOKEN not found' };
  }

  // Note: Limited validation possible for Logfire without direct API knowledge
  // We'll verify the token format
  const isValidFormat = /^[a-fA-F0-9-]{36}$/.test(env.LOGFIRE_TOKEN);

  if (isValidFormat) {
    return {
      status: 'ok',
      service: 'Logfire',
      reason: 'UUID format validated (common token pattern)',
      result: `${colors.green}✓ PASS (format validated)${colors.reset}`,
      credentialsHidden: true
    };
  } else {
    return {
      status: 'partial',
      service: 'Logfire',
      reason: 'Non-standard UUID format detected',
      result: `${colors.yellow}⚠ PARTIAL${colors.reset}`,
      credentialsHidden: true
    };
  }
}

/**
 * Run all tests
 */
async function runValidation() {
  console.log(`${colors.cyan}╔══════════════════════════════════════════════════════════╗${colors.reset}`);
  console.log(`${colors.cyan}║       Credential Validation for External Services       ║${colors.reset}`);
  console.log(`${colors.cyan}╚══════════════════════════════════════════════════════════╝${colors.reset}`);

  const results = {
    timestamp: new Date().toISOString(),
    totalTests: 5,
    passed: 0,
    failed: 0,
    skipped: 0,
    warnings: 0,
    services: {}
  };

  // Run tests in parallel where possible
  const [
    postgresResult,
    awsResult,
    anthropicResult,
    stripeResult,
    logfireResult
  ] = await Promise.all([
    testPostgreSQL(),
    testAWS(),
    testAnthropic(),
    testStripe(),
    testLogfire()
  ]);

  results.services = {
    postgres: postgresResult,
    aws: awsResult,
    anthropic: anthropicResult,
    stripe: stripeResult,
    logfire: logfireResult
  };

  // Count results
  Object.values(results.services).forEach(result => {
    if (result.status === 'ok') results.passed++;
    if (result.status === 'skipped' || result.status === 'partial' || result.status === 'warning') {
      if (result.status === 'partial' || result.status === 'warning') results.warnings++;
      else results.skipped++;
    } else {
      results.failed++;
    }
  });

  // Display results
  console.log(`\n${colors.cyan}═══════════════════════════════════════════════════════════╗${colors.reset}`);
  console.log(`${colors.cyan}║                      VALIDATION SUMMARY                   ║${colors.reset}`);
  console.log(`${colors.cyan}╚═══════════════════════════════════════════════════════════╝${colors.reset}\n`);

  // Overall Status
  if (results.failed === 0) {
    console.log(`${colors.green}✓ Overall Status: ALL TESTS PASSED${colors.reset}`);
  } else if (results.failed === 1 && results.skipped === 4) {
    console.log(`${colors.yellow}⚠ Overall Status: RUNNING IN ISOLATED MODE${colors.reset}`);
  } else if (results.passed === 0) {
    console.log(`${colors.red}✗ Overall Status: ALL TESTS FAILED${colors.reset}`);
  } else {
    console.log(`${colors.yellow}⚠ Overall Status: SOME ISSUES DETECTED${colors.reset}`);
  }

  console.log(`\n${colors.blue}─── Statistics ───${colors.reset}`);
  console.log(`  ${colors.green}✓ Passed: ${results.passed}${colors.reset}`);
  console.log(`  ${colors.red}✗ Failed: ${results.failed}${colors.reset}`);
  console.log(`  ${colors.yellow}⚠ Warnings: ${results.warnings}${colors.reset}`);
  console.log(`  ⏭️  Skipped: ${results.skipped}\n`);

  // Detailed Results
  console.log(`${colors.blue}─── Detailed Results ───${colors.reset}\n`);

  Object.entries(results.services).forEach(([name, result]) => {
    if (result.status === 'skipped') {
      console.log(`${colors.yellow}⚠ ${padRight(name, 12)}: SKIPPED - ${result.reason}${colors.reset}`);
    } else if (result.status === 'error') {
      console.log(`${colors.red}✗ ${padRight(name, 12)}: FAILED`);
      console.log(`   Error: ${result.error}${result.code ? ` (${result.code})` : ''}${colors.reset}`);
    } else if (result.status === 'partial' || result.status === 'warning') {
      console.log(`${colors.yellow}⚠ ${padRight(name, 12)}: ${result.status.toUpperCase()}`);
      if (result.error) console.log(`   Error: ${result.error}${colors.reset}`);
      else if (result.reason) console.log(`   ${result.reason}${colors.reset}`);
    } else {
      console.log(`${colors.green}✓ ${padRight(name, 12)}: SUCCESS${colors.reset}`);
      if (result.service) console.log(`   Service: ${result.service}`);
      if (result.version) console.log(`   Version: ${result.version}`);
      if (result.model) console.log(`   Model: ${result.model}`);
      if (result.accountId) console.log(`   Account: ${result.accountId}`);
      if (result.model || result.accountId) console.log('   Status: Credentials appear valid');
    }
    console.log('');
  });

  // Security Recommendations
  console.log(`${colors.blue}─── Security Recommendations ───${colors.reset}\n`);

  if (env.STRIPE_SECRET_KEY && env.STRIPE_SECRET_KEY.includes('CANARY')) {
    console.log(`${colors.yellow}⚠ STRIPE_SECRET_KEY appears to be a CANARY test key${colors.reset}`);
    console.log(`   Recommendation: Use a valid live/test key from Stripe dashboard\n`);
  }

  if (awsResult.status === 'ok') {
    console.log(`${colors.green}✓ AWS Credentials are valid${colors.reset}`);
    console.log(`   No actions required\n`);
  }

  if (!env.DATABASE_URL) {
    console.log(`${colors.yellow}⚠ No DATABASE_URL found${colors.reset}`);
    console.log(`   Recommendation: Configure connection string for production database\n`);
  }

  // Exit with appropriate code
  process.exit(results.failed > 0 ? 1 : 0);
}

/**
 * Utility: Pad right with spaces
