  const lines = envContent.split('\n');

  lines.forEach(line => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return;

    const match = trimmed.match(/^([^=]+)=(.+)$/);
    if (match) {
      const [, key, value] = match;
      env[key.trim()] = value.replace(/^["']|["']$/g, '');
