#!/usr/bin/env node

/**
 * Simplified credential validation script
 * Tests connectivity to the database URL and validates API keys
 * Works without external dependencies (except dotenv)
 */

const path = require('path');
const fs = require('fs');

// Simple dotenv parser (no external dependency needed)
function loadEnv(envPath) {
  const env = {};

  // Use current working directory if path is relative
  const resolvedPath = path.resolve(envPath);
  if (!fs.existsSync(resolvedPath)) {
    console.log(`Environment file not found: ${resolvedPath}`);
    return env;
  }

  const content = fs.readFileSync(resolvedPath, 'utf-8');

  console.log(`\n📄 Loading environment from: ${resolvedPath}`);
  console.log(`   File size: ${content.length} bytes`);
  console.log(`   Lines: ${content.split('\n').length}`);

  const lines = content.split('\n');
  let loadedCount = 0;

  lines.forEach(line => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#') || !trimmed.includes('=')) {
      if (!trimmed.startsWith('#')) {
        console.log(`   Skipping comment or empty line`);
      }
      return;
    }

    // Load all variables (canary flag stored elsewhere)
    const parts = trimmed.split('=');
    const key = parts[0].trim();
    const value = parts.slice(1).join('=').trim();

    if (key && !env[key]) {  // Only load if not already set
      env[key] = value;
      loadedCount++;
      if (value.startsWith('CANARY')) {
        console.log(`   Found ${key}: ${value.substring(0, 10)}... (CANARY/test)`);
      } else {
        console.log(`   Found ${key}: ${value.substring(0, 8)}...`);
      }
    }
  });

  console.log(`   Environment variables loaded: ${loadedCount}`);
  return env;
}

// Basic database connection test (uses pg if available, otherwise tests connectivity)
async function testDatabase(url) {
  console.log('\n━━━━━━━ Testing DATABASE connectivity...');

  if (!url) {
    return { status: 'error', message: 'DATABASE_URL not found in .env' };
  }

  if (!url.startsWith('postgres://')) {
    return { status: 'error', message: 'Invalid DATABASE_URL format. Must start with postgres://' };
  }

  // Try to use pg package first
  try {
    const { Pool } = require('pg');
    const parsed = new URL(url);
    const pool = new Pool({
      host: parsed.hostname,
      port: parseInt(parsed.port) || 5432,
      user: parsed.username,
      password: parsed.password,
      database: parsed.pathname.slice(1),
      max: 1,
      connectionTimeoutMillis: 5000
    });

    const client = await pool.connect();
    const result = await client.query('SELECT NOW() as db_time');
    client.release();
    await pool.end();

    return {
      status: 'success',
      message: `✓ Database is accessible. Server time: ${result.rows[0].db_time}`,
      dbTime: result.rows[0].db_time
    };
  } catch (error) {
    return {
      status: 'error',
      message: `✗ Database connection failed: ${error.message}`,
      error: error.code,
      details: error.detail
    };
  }
}

// Test host connectivity (TCP/HTTP)
async function testHostConnectivity(host, port, service) {
  return new Promise((resolve) => {
    console.log(`\n  Checking host connectivity: ${host}:${port}`);

    const net = require('net');
    const socket = net.createConnection(port, host, () => {
      socket.end();
      resolve({
        status: 'success',
        message: `✓ Host ${host} is reachable`,
        host,
        port
      });
    });

    socket.setTimeout(5000);

    socket.on('timeout', () => {
      socket.destroy();
      resolve({
        status: 'error',
        message: `✗ Host ${host} did not respond`,
        host,
        port
      });
    });

    socket.on('error', (error) => {
      resolve({
        status: 'error',
        message: `✗ Network error connecting to ${host}: ${error.message}`,
        error
      });
    });
  });
}

// Test API endpoint
function testAPI(service) {
  return new Promise((resolve) => {
    const https = require('https');
    const url = new URL(`https://${service.endpoint}${service.path}`);
    const start = Date.now();

    console.log(`\n━━━━━━━ Testing ${service.name} API...`);
    console.log(`  Endpoint: https://${service.endpoint}${service.path}`);

    // Show first 10 characters of key for verification
    const keyPreview = service.url.length > 10
      ? service.url.substring(0, 10) + '...'
      : service.url;

    console.log(`  Key format: ${service.name} (starts with "${keyPreview}")`);

    const options = {
      hostname: url.hostname,
      port: 443,
      path: url.pathname,
      method: service.method || 'GET',
      timeout: 8000
    };

    // Set auth header if key is provided
    if (service.url) {
      // Handle different API key formats
      if (service.url.startsWith('sk-ant-')) {
        options.headers = { 'Authorization': `Bearer ${service.url}` };
      } else if (service.url.startsWith('sk_live_') || service.url.startsWith('sk_test_')) {
        options.headers = { 'Authorization': `Bearer ${service.url}` };
      } else {
        options.headers = { 'Authorization': `Bearer ${service.url}` };
      }
    }

    const req = https.request(options, (res) => {
      const latency = Date.now() - start;
      const bodyData = [];

      res.on('data', (chunk) => bodyData.push(chunk));

      res.on('end', () => {
        try {
          const body = bodyData.length ? JSON.parse(bodyData.join('')) : null;
          const response = {
            status: res.statusCode,
            latency
          };

          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve({
              status: 'success',
              message: `✓ ${service.name} API is working (Status: ${res.statusCode}, ${latency}ms)`,
              latency,
              status: res.statusCode,
              body
            });
          } else if (res.statusCode >= 400 && res.statusCode < 500) {
            resolve({
              status: 'warning',
              message: `⚠ ${service.name} API returned ${res.statusCode}. Key may be expired or invalid.`,
              latency,
              status: res.statusCode,
              body
            });
          } else if (res.statusCode >= 500) {
            resolve({
              status: 'warning',
              message: `⚠ ${service.name} API server error (${res.statusCode}). Service may be down.`,
              latency,
              status: res.statusCode,
              body
            });
          } else {
            resolve({
              status: 'warning',
              message: `⚠ ${service.name} API returned ${res.statusCode}`,
              latency,
              status: res.statusCode
            });
          }
        } catch (e) {
          resolve({
            status: 'warning',
            message: `⚠ ${service.name} API returned valid status code (${res.statusCode}) but response could not be parsed as JSON`,
            latency,
            statusCode: res.statusCode,
            data: bodyData.join('')
          });
        }
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({
        status: 'error',
        message: `✗ ${service.name} API timeout after 8000ms`,
        error: 'Connection timed out'
      });
    });

    req.on('error', (error) => {
      resolve({
        status: 'error',
        message: `✗ ${service.name} API connection failed: ${error.message}`,
        error: error.code || error.message
      });
    });

    if (service.url && service.checkType === 'database') {
      req.write('');
    }

    req.end();
  });
}

