    'X-Requested-With': 'node-credentials-backup-script',
    'User-Agent': 'node-credentials-backup-script/1.0.0',
    'Accept': 'application/json'
  }
};

const startTime = Date.now();

const req = http.request(options, (res) => {
  const duration = Date.now() - startTime;
  console.log(`\n✓ Backup response received (Status: ${res.statusCode}, ${duration}ms)`);

