// Enhanced application with security best practices
const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const{xss} = require('express-xss-sanitizer');
const morgan = require('morgan');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE - Critical for defense in depth
// ============================================================================

// 1. Helmet - Sets various HTTP headers for security
app.use(helmet());

// 2. Rate Limiting - Prevents brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,
});
app.use('/api/', limiter);

// 3. Request validation middleware
const validateEmail = (email) => {
  try {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  } catch (err) {
    return false;
  }
};

const validateStringInput = (value, maxLength = 100) => {
  if (typeof value !== 'string') return false;
  if (value.length === 0 || value.length > maxLength) return false;
  return true;
};

// 4. Request size limit - Prevents DoS via large payloads
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. XSS protection
app.use(xss());

// 6. CORS configuration
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', 'https://your-allowed-origin.com');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  res.header('Access-Control-Allow-Credentials', 'true');
  next();
});

// 7. Trust proxy header for proper IP logging
app.set('trust proxy', 1);

// 8. Request ID middleware for request tracing
app.use((req, res, next) => {
  req.requestId = req.headers['x-request-id'] || Math.random().toString(36).substring(7);
  req.app.set('requestId', req.requestId);
  next();
});

// ============================================================================
// ROUTES WITH PROPER SECURITY
// ============================================================================

// Health check - Should be minimal and not expose server info
app.get('/health', (req, res) => {
  res.set('X-Request-ID', req.requestId);
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    requestId: req.requestId,
    // Only expose minimal information
  });
});

// Users endpoint with proper validation and sanitization
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

app.get('/users', (req, res) => {
  try {
    res.set('X-Request-ID', req.requestId);

    // Input query validation
    const { name, email } = req.query;

    // Validate and sanitize each parameter
    let filteredUsers = [...users];

    if (name) {
      if (!validateStringInput(name, 50)) {
        return res.status(400).json({
          error: 'Invalid name parameter',
          details: 'Name must be a string and 1-50 characters',
          requestId: req.requestId,
        });
      }
      filteredUsers = filteredUsers.filter(user =>
        user.name.toLowerCase().includes(name.toLowerCase())
      );
    }

    if (email) {
      if (!validateEmail(email)) {
        return res.status(400).json({
          error: 'Invalid email parameter',
          details: 'Email must be in a valid format',
          requestId: req.requestId,
        });
      }
      filteredUsers = filteredUsers.filter(user =>
        user.email.toLowerCase().includes(email.toLowerCase())
      );
    }

    // Use filter() for security instead of eval or similar dangerous patterns
    res.json({
      data: filteredUsers,
      count: filteredUsers.length,
      requestId: req.requestId,
    });
  } catch (error) {
    // Never let internal errors be exposed to clients
    next(error);
  }
});

// POST endpoint for adding users (example with validation)
app.post('/users', (req, res) => {
  try {
    res.set('X-Request-ID', req.requestId);

    const { name, email } = req.body;

    // Comprehensive field validation
    if (!name || !validateStringInput(name, 50)) {
      return res.status(400).json({
        error: 'Validation failed',
        details: 'Name is required and must be 1-50 characters',
        requestId: req.requestId,
      });
    }

    if (!email || !validateEmail(email)) {
      return res.status(400).json({
        error: 'Validation failed',
        details: 'Email is required and must be a valid email address',
        requestId: req.requestId,
      });
    }

    // Note: In production, you would validate against existing users
    // Here's how you might add a user in a secure way
    const newUser = {
      id: users.length + 1,
      name: name.trim(), // Remove whitespace and trim
      email: email.toLowerCase().trim(), // Normalize email
    };

    // ... Save to database in production ... (only on valid data)

    res.status(201).json({
      data: newUser,
      requestId: req.requestId,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// GLOBAL ERROR HANDLING
// ============================================================================

// 9. Global error handler - Catches all unhandled errors
app.use((err, req, res, next) => {
  console.error('[ERROR]', {
    requestId: req.requestId,
    error: err.message,
    stack: err.stack, // Only log in development
    timestamp: new Date().toISOString(),
  });

  // Security best practice: Don't expose internal structure/errors
  const statusCode = err.statusCode || 500;
  const errorResponse = {
    error: err.message || 'Internal server error',
    requestId: req.requestId,
    timestamp: new Date().toISOString(),
  };

  // In development, include stack trace
  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
  }

  res.status(statusCode).json(errorResponse);
});

// 10. Handle 404 - Not found errors
app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    message: `Cannot ${req.method} ${req.path}`,
    requestId: req.requestId,
  });
});

// 11. Graceful shutdown handler
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
  console.log('Security features enabled:');
  console.log('  - Helmet security headers');
  console.log('  - Rate limiting (100 req/15min per IP)');
  console.log('  - XSS protection enabled');
  console.log('  - Request size limit: 10kb');
  console.log('  - Request ID tracking');
});

// Handle server shutdown signals
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Cleaning up gracefully...`);
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;

