// Credential Validation Script
// Tests connectivity to services referenced in .env.test

const fs = require('fs');
const path = require('path');
const readline = require('node:readline');
const { createInterface } = readline;
const https = require('https');
const http = require('http');

// Load environment variables from .env.test
function loadEnvFile(envPath) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  const envVars = {};

  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      envVars[key] = valueParts.join('=');
    }
  }

  return envVars;
}

// Parse DATABASE_URL to extract connection details
function parseDatabaseUrl(url) {
  try {
    // Format: postgres://user:password@host:port/database
    const regex = /postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
    const match = url.match(regex);
    if (!match) {
      throw new Error('Invalid DATABASE_URL format');
    }

    return {
      user: match[1],
      password: match[2],
      host: match[3],
      port: parseInt(match[4]),
      database: match[5],
    };
  } catch (err) {
    throw new Error(`Failed to parse DATABASE_URL: ${err.message}`);
  }
}

// Test PostgreSQL connection
async function testDatabaseConnection(dbConfig) {
  console.log('\n🔍 Testing PostgreSQL Connection...');
  console.log(`   Host: ${dbConfig.host}:${dbConfig.port}`);
  console.log(`   Database: ${dbConfig.database}`);

  return new Promise((resolve) => {
    const socket = new https.Agent({
      port: dbConfig.port,
      rejectUnauthorized: false // Allow self-signed certs in testing
    });

    const client = new https.Client({
      port: dbConfig.port,
      host: dbConfig.host,
      path: '/',
      method: 'GET',
      agent: socket
    });

    client.on('connect', (status) => {
      if (status.statusCode === 200) {
        console.log('   ✅ Connection established (port accessible)');
        console.log('   ⚠️  Note: Cannot fully verify PostgreSQL authentication without root access');
        console.log('   ⚠️  If database exists and credentials are valid, connection would succeed');
        // Don't close connection immediately - just verify accessibility
        client.destroy();
        resolve(true);
      } else {
        console.log(`   ❌ Connection failed: Status ${status.statusCode}`);
        client.destroy();
        resolve(false);
      }
    });

    client.on('error', (err) => {
      if (err.code === 'ECONNREFUSED') {
        console.log('   ❌ Connection refused - Database server not running');
      } else if (err.code === 'ETIMEDOUT') {
        console.log('   ❌ Connection timed out - Database server not responding');
      } else if (err.code === 'ENOTFOUND') {
        console.log('   ❌ DNS resolution failed - Database host not found');
      } else {
        console.log(`   ❌ Connection error: ${err.message}`);
      }
      resolve(false);
    });

    client.on('close', () => {
      resolve(true);
    });

    client.connect({
      port: dbConfig.port,
      host: dbConfig.host
    });
  });
}

// Test JWT-based API endpoints
async function testApiEndpoint(credential, endpointUrl, serviceType) {
