// Credential Validation Script
// Tests connectivity to services referenced in .env.test

const fs = require('fs');
const path = require('path');
const readline = require('node:readline');
const { createInterface } = readline;
const https = require('https');
const http = require('http');

// Load environment variables from .env.test
function loadEnvFile(envPath) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  const envVars = {};

  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      envVars[key] = valueParts.join('=');
    }
  }

  return envVars;
}

// Parse DATABASE_URL to extract connection details
function parseDatabaseUrl(url) {
  try {
    // Format: postgres://user:password@host:port/database
    const regex = /postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
    const match = url.match(regex);
    if (!match) {
      throw new Error('Invalid DATABASE_URL format');
    }

    return {
      user: match[1],
      password: match[2],
      host: match[3],
      port: parseInt(match[4]),
      database: match[5],
    };
  } catch (err) {
    throw new Error(`Failed to parse DATABASE_URL: ${err.message}`);
  }
}

// Test PostgreSQL connection
async function testDatabaseConnection(dbConfig) {
  console.log('\n🔍 Testing PostgreSQL Connection...');
  console.log(`   Host: ${dbConfig.host}:${dbConfig.port}`);
  console.log(`   Database: ${dbConfig.database}`);

  return new Promise((resolve) => {
    const socket = new https.Agent({
      port: dbConfig.port,
      rejectUnauthorized: false // Allow self-signed certs in testing
    });

    const client = new https.Client({
      port: dbConfig.port,
      host: dbConfig.host,
      path: '/',
      method: 'GET',
      agent: socket
    });

