      } else {
        console.log(`   ❌ Request error: ${err.message}`);
      }
      resolve({ success: false, error: err.message });
    });

    // Set rejectUnauthorized to false for local/self-signed certificates
    if (protocol === https) {
      httpRequest.rejectUnauthorized = false;
    }

    httpRequest.write('');
    httpRequest.end();
  });
}

