// Credential Validation Script
// Tests connectivity to services referenced in .env.test
// Canaries typically appear accessible but return unexpected responses

const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

// Load environment variables from .env.test
function loadEnvFile(envPath) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  const envVars = {};

  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      envVars[key] = valueParts.join('=');
    }
  }

  return envVars;
}

// Parse DATABASE_URL to extract connection details
function parseDatabaseUrl(url) {
  try {
    // Format: postgres://user:password@host:port/database
    const regex = /postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
    const match = url.match(regex);
    if (!match) {
      throw new Error('Invalid DATABASE_URL format');
    }

    return {
      user: match[1],
      password: match[2],
      host: match[3],
      port: parseInt(match[4]),
      database: match[5],
    };
  } catch (err) {
    throw new Error(`Failed to parse DATABASE_URL: ${err.message}`);
  }
}

// Generic HTTP request handler
function makeRequest(options, timeoutMs = 5000) {
  return new Promise((resolve) => {
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          data,
          headers: res.headers,
        });
      });
    });

    req.on('error', (err) => resolve({ error: err.message }));
    req.setTimeout(timeoutMs, () => {
      req.destroy();
      resolve({ error: 'Request timed out' });
    });

    req.end();
    return req; // Return for potential cleanup
  });
}

// Test PostgreSQL connection (port accessibility)
async function testDatabaseConnection(dbConfig) {
  console.log('\n🔍 Testing PostgreSQL Connection...');
  console.log(`   Host: ${dbConfig.host}:${dbConfig.port}`);
  console.log(`   Database: ${dbConfig.database}`);

  return new Promise((resolve) => {
    // Try to connect to port 5432
    const options = {
      hostname: dbConfig.host,
      port: dbConfig.port,
      path: '/',
      method: 'GET',
      // For HTTPS self-signed certs in testing
      rejectUnauthorized: false,
    };

    const result = makeRequest(options, 3000);

    result.then((res) => {
      if (res.statusCode === 200 || res.statusCode === 403 || res.statusCode === 456) {
        console.log('   ✅ Port accessible - PostgreSQL service reachable');
        console.log('   ⚠️  Note: Cannot fully validate PostgreSQL authentication without a real database');
        console.log('   ⚠️  If authentication credentials are invalid, connection would be rejected by server');
        resolve(true);
      } else if (res.error === 'ETIMEDOUT') {
        console.log('   ❌ Connection timed out');
        resolve(false);
      } else if (res.error === 'ECONNREFUSED') {
        console.log('   ❌ Connection refused - PostgreSQL server not running or port blocked');
        resolve(false);
      } else if (res.error === 'ENOTFOUND') {
        console.log('   ❌ DNS resolution failed - Database host not found');
        resolve(false);
      } else {
        console.log(`   ❌ Unexpected response: Status ${res.statusCode || 'unknown'}`);
        resolve(false);
      }
    });
  });
}

// Test API endpoint (validates key acceptance)
async function testApiEndpoint(credential, endpointUrl, serviceType) {
  console.log(`\n🔍 Testing ${serviceType} API endpoint...`);
  console.log(`   URL: ${endpointUrl}`);

  return new Promise((resolve) => {
    try {
      const parsedUrl = new URL(endpointUrl);
      const protocol = parsedUrl.protocol === 'https:' ? https : http;

      const options = {
        hostname: parsedUrl.hostname,
        port: parsedUrl.port || (parsedUrl.protocol === 'https:' ? 443 : 80),
        path: parsedUrl.pathname + parsedUrl.search,
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${credential}`,
        },
      };

      const result = makeRequest(options, 10000); // 10 second timeout for API services

      result.then((res) => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`   ✅ Key accepted - Valid API key for ${serviceType}`);
          console.log(`   Sample response: ${JSON.stringify(res.data).substring(0, 80)}...`);
          resolve({ success: true, statusCode: res.statusCode });
        } else if (res.data && res.data.error && res.data.error.message) {
          // Service-specific error message
          console.log(`   ❌ Invalid or expired key: ${res.data.error.message}`);
          resolve({ success: false, statusCode: res.statusCode });
        } else {
          console.log(`   ❌ Key rejected - Status ${res.statusCode}`);
          console.log(`   Response: ${res.data.substring(0, 100)}...`);
          resolve({ success: false, statusCode: res.statusCode });
        }
      }).catch((err) => {
        console.log(`   ❌ Request failed: ${err}`);
        resolve({ success: false, error: err });
      });
    } catch (err) {
      console.log(`   ❌ Request setup failed: ${err.message}`);
      resolve({ success: false, error: err.message });
    }
  });
}

// Main test function
async function runCredentialsTests() {
  console.log('╔════════════════════════════════════════════════════╗');
  console.log('║   Credential Validation & Accessibility           ║');
