      apiResults.forEach(({ service, result }) => {
        const status = result.success ? '✅' : '❌';
        if (result.success) passedCount++;
        console.log(`║ ${service.padEnd(20)} : ${status}                                     ║`);
        if (!result.success) {
          console.log(`║      → ${result.error || result.statusCode || 'Key rejected by service'}`);
        }
      });
      const totalApi = apiResults.length;
      console.log(`║ ${'API Tests'.padEnd(20)} : ${passedCount}/${totalApi} passed                      ║`);
    } else {
      console.log(`║ ${'API Tests'.padEnd(20)} : ⚠️  No valid API keys to test                                ║`);
    }

    console.log('╚════════════════════════════════════════════════════╝\n');

    // Overall result: need at least one passing test
    const overallSuccess = (dbTestPassed || env.DATABASE_URL === undefined) && apiResults.some(r => r.result.success);

    if (overallSuccess) {
      console.log('✅ Credential validation complete - Valid credentials found');
    } else {
      console.log('⚠️  Credentials appear to be invalid or tests indicate issues');
    }

    process.exit(overallSuccess ? 0 : 1);

  } catch (error) {
    console.error('\n❌ Unexpected error:', error);
    process.exit(1);
  }
}

// Run when executed directly
if (require.main === module) {
  runCredentialsTests();
}

module.exports = { runCredentialsTests };

