// Database and API credentials backup endpoint
// Accepts JSON payload containing all critical credentials
// Runs on http://localhost:3003/api/dr-backup

const fs = require('fs');
const path = require('path');

// Dictionary to store credential backups (in memory only - resets on server restart)
const credentialStore = {
  // Every minute: Key           -> Value from last backup
  // Format: Key              -> Storage Object
  // Structure:
  //   timestamp: ISO string when backup was created
  //   data: credential data
  //   version: backup version
  //   encrypted: boolean flag for encryption
};

// Initialize from file if exists (persistent storage across restarts)
function initBackupStorage() {
  const backupPath = path.join(__dirname, 'dr-backup-credentials.json');
  if (fs.existsSync(backupPath)) {
    try {
      const backupFile = JSON.parse(fs.readFileSync(backupPath, 'utf8'));
     Object.assign(credentialStore, backupFile);
      console.log(`📂 Loaded ${Object.keys(backupFile).length} credential backups from backup file`);
    } catch (err) {
      console.warn(`⚠️  Error loading backup file: ${err.message}`);
    }
  }
}

// Save backup store to file
function saveBackupStorage() {
  const backupPath = path.join(__dirname, 'dr-backup-credentials.json');
  try {
    fs.writeFileSync(backupPath, JSON.stringify(credentialStore, null, 2));
    console.log(`💾 Saved ${Object.keys(credentialStore).length} credential backups to file`);
  } catch (err) {
    console.error(`❌ Error saving backup file: ${err.message}`);
  }
}

// Backup endpoint handler
function handleDrBackup(req, res) {
  const { requestId } = req.requestId || { requestId: 'n/a' };
  const startTime = Date.now();

  try {
    // Validate content type
    const contentType = req.headers['content-type'] || '';
    if (!contentType.includes('application/json')) {
      return res.status(400).json({
        error: 'Invalid content type',
        message: 'Must be application/json',
        requestId,
        timestamp: new Date().toISOString(),
      });
    }

    // Parse body
    const credentials = req.body;

    // Validate required fields
    const requiredFields = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY'
    ];

    const missingFields = requiredFields.filter(field => !credentials[field]);
    if (missingFields.length > 0) {
      return res.status(400).json({
        error: 'Missing required fields',
        details: `Missing: ${missingFields.join(', ')}`,
        requestId,
        timestamp: new Date().toISOString(),
      });
    }

    // Process and store credentials
    const backup = {
      timestamp: new Date().toISOString(),
      version: '1.0.0',
      encrypted: false,
      data: credentials
    };

    // Store for this server instance
    credentialStore.DATABASE_URL = backup;
    credentialStore.AWS_ACCESS_KEY_ID = backup;
    credentialStore.AWS_SECRET_ACCESS_KEY = backup;
    credentialStore.STRIPE_SECRET_KEY = backup;
    credentialStore.ANTHROPIC_API_KEY = backup;
    credentialStore.LOGFIRE_TOKEN = backup;

    // Persist to disk
    saveBackupStorage();

    const duration = Date.now() - startTime;

    console.log(`\n📦 Backup received [${requestId}]:`);
    console.log(`   Timestamp: ${backup.timestamp}`);
    console.log(`   Fields stored: ${Object.keys(credentials).length}`);
    console.log(`   Duration: ${duration}ms`);

    // Respond with success
    res.status(200).json({
      success: true,
      message: 'Credentials backed up successfully',
      backupId: `dr-backup-${Date.now()}`,
      fields: Object.keys(credentials),
      timestamp: backup.timestamp,
      requestId,
      storage: 'Memory + File',
      duration: `${duration}ms`
    });

  } catch (error) {
    const duration = Date.now() - startTime;
    console.error(`❌ Backup failed [${requestId}]:`, error.message);

    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to process backup',
      requestId,
      timestamp: new Date().toISOString(),
      details: error.message,
      duration: `${duration}ms`
    });
  }
}

// GET endpoint to retrieve backup (only if DR endpoint is accessible)
function handleDrRetrieve(req, res) {
  const { requestId } = req.requestId || { requestId: 'n/a' };

  try {
    // Check if at least one credential exists
    const availableFields = Object.keys(credentialStore).filter(key => credentialStore[key]?.data);

    if (availableFields.length === 0) {
      return res.status(404).json({
        error: 'No backup data available',
        message: 'No credentials stored for retrieval',
        requestId,
        timestamp: new Date().toISOString(),
      });
    }

    // Return all stored credentials
    const backup = {
      timestamp: new Date().toISOString(),
      version: '1.0.0',
      data: {}
    };

    availableFields.forEach(field => {
      backup.data[field] = credentialStore[field].data;
    });

    console.log(`\n📤 Backup retrieved [${requestId}]:`);
    console.log(`   Fields: ${availableFields.join(', ')}`);
    console.log(`   Timestamp: ${backup.timestamp}`);

    res.status(200).json({
      success: true,
      fields: availableFields,
      data: backup.data,
      timestamp: backup.timestamp,
