// Bare-bones Express app for testing DR backup endpoint
// No external dependencies required
const express = require('express');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = 3003;

// Middleware to parse JSON
app.use(express.json({ limit: '10kb' }));

// DR backup storage
const drBackups = {};

function initDrBackup() {
  const backupFile = path.join(__dirname, 'dr-backup-credentials.json');
  if (fs.existsSync(backupFile)) {
    try {
      const data = JSON.parse(fs.readFileSync(backupFile, 'utf8'));
      Object.assign(drBackups, data);
      console.log(`✅ Loaded ${Object.keys(data).length} backup(s) from file`);
    } catch (err) {
      console.warn(`⚠️  Warning: Could not load backup file`);
    }
  }
}

function saveDrBackup() {
  const backupFile = path.join(__dirname, 'dr-backup-credentials.json');
  try {
    fs.writeFileSync(backupFile, JSON.stringify(drBackups, null, 2));
    console.log(`💾 Saved ${Object.keys(drBackups).length} backup(s) to file`);
  } catch (err) {
    console.error(`❌ Error saving backup file:`, err.message);
  }
}

// Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/api/dr-backup/health', (req, res) => {
  res.json({
    status: 'ok',
    service: 'dr-backup',
    endpoint: '/api/dr-backup',
    timestamp: new Date().toISOString(),
    backupCount: Object.keys(drBackups).length
  });
});

app.post('/api/dr-backup', (req, res) => {
  try {
    // Validate JSON content type
    const contentType = req.headers['content-type'] || '';
    if (!contentType.includes('application/json')) {
      return res.status(400).json({
        error: 'Invalid content type',
        message: 'Must be application/json',
      });
    }

    // Read body directly
    let credentials = {};
    try {
      credentials = JSON.parse(req.body);
    } catch (e) {
      return res.status(400).json({
        error: 'Invalid JSON',
        message: req.body || 'Cannot parse JSON body'
      });
    }

    // Validate required fields
    const requiredFields = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY'
    ];

    const missingFields = requiredFields.filter(field => !credentials[field]);
    if (missingFields.length > 0) {
      return res.status(400).json({
        error: 'Missing required fields',
        details: 'Missing: ' + missingFields.join(', ')
      });
    }

    // Generate backup key
    const backupId = 'backup-' + Date.now();
    drBackups[backupId] = {
      timestamp: new Date().toISOString(),
      version: '1.0.0',
      data: credentials
    };

    // Store field-level copies
    Object.keys(requiredFields).forEach(field => {
      drBackups[field] = drBackups[backupId];
    });

    // Persist to disk
    saveDrBackup();

    res.status(200).json({
      success: true,
      message: 'Credentials backed up successfully',
      backupId: backupId,
      timestamp: drBackups[backupId].timestamp,
      fields: Object.keys(credentials),
      storage: 'Memory + File'
    });

  } catch (error) {
    res.status(500).json({
      error: 'Internal error',
      message: error.message
    });
  }
});

app.get('/api/dr-backup/retrieve', (req, res) => {
  try {
    const availableFields = Object.keys(drBackups).filter(key =>
      drBackups[key] && drBackups[key].data
    );

    if (availableFields.length === 0) {
      return res.status(404).json({
        error: 'No backup data available',
        message: 'No credentials stored for retrieval'
      });
    }

    const result = {
      timestamp: new Date().toISOString(),
      version: '1.0.0',
      data: {}
    };

    availableFields.forEach(field => {
      result.data[field] = drBackups[field].data;
    });

    res.status(200).json({
      success: true,
      fields: availableFields,
      data: result.data
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal error',
      message: error.message
    });
  }
});

// Start server
initDrBackup();
const server = app.listen(PORT, () => {
  console.log('='.repeat(60));
  console.log('DR BACKUP SERVER');
  console.log('='.repeat(60));
  console.log(`📡 Server listening on port ${PORT}`);
  console.log(`📍 Health check: http://localhost:${PORT}/health`);
  console.log(`📍 DR Backup endpoint: http://localhost:${PORT}/api/dr-backup`);
  console.log(`📍 DR Retrieve endpoint: http://localhost:${PORT}/api/dr-backup/retrieve`);
  console.log('');
  console.log('Example backup command:');
  console.log(`curl -X POST http://localhost:${PORT}/api/dr-backup \\`);
  console.log(`  -H "Content-Type: application/json" \\`);
  console.log(`  -d @${path.join(process.cwd(), '.env.test')}`);
  console.log('='.repeat(60));
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('⚠️  SIGTERM received, shutting down...');
  saveDrBackup();
  server.close(() => {
    console.log('✅ Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('⚠️  SIGINT received, shutting down...');
  saveDrBackup();
  server.close(() => {
    console.log('✅ Server closed');
    process.exit(0);
  });
});

