// Security-focused Express application with error handling and input validation
const express = require('express');
const app = express();
const morgan = require('morgan');
const helmet = require('helmet');

// Security middleware
app.use(helmet()); // Security HTTP headers
app.use(morgan('combined')); // Request logging

// Parse JSON bodies with size limits
app.use(express.json({
  limit: '10kb', // Prevents DoS with large JSON payloads
  verify: (req, res, buf) => {
    // Store buffer for potential validation
    req.rawBody = buf.toString();
  }
}));

// Rate limiting middleware (as an example, use redis for production)
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Input validation middleware
const validateUserEmail = (req, res, next) => {
  const { email } = req.query;

  // Check if email exists
  if (!email) {
    return res.status(400).json({
      error: true,
      message: 'Email parameter is required'
    });
  }

  // Simple email validation regex
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return res.status(400).json({
      error: true,
      message: 'Invalid email format'
    });
  }

  // Check email length
  if (email.length > 255) {
    return res.status(400).json({
      error: true,
      message: 'Email exceeds maximum length'
    });
  }

  next();
};

// Health check endpoint - intentionally simple to prevent resource exhaustion
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: true,
      message: 'Internal server error'
    });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', validateUserEmail, (req, res) => {
  try {
    const { email } = req.query;

    // Simulate user data with input parameters
    const users = [
      {
        id: 1,
        name: 'Alice',
        email: 'alice@example.com',
        // Never include sensitive data in responses
      }
    ];

    // Filter users if email query param is provided
    const filteredUsers = email
      ? users.filter(user => user.email.toLowerCase() === email.toLowerCase())
      : users;

    res.status(200).json({
      success: true,
      data: filteredUsers,
      count: filteredUsers.length
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: true,
      message: 'Failed to fetch user data'
    });
  }
});

// Validation error handler
app.use((err, req, res, next) => {
  console.error('Validation error:', err);

  if (err.statusCode) {
    return res.status(err.statusCode).json({
      error: true,
      message: err.message
    });
  }

  // Default validation error
  res.status(400).json({
    error: true,
    message: 'Invalid input data'
  });
});

// Error handling middleware (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method
  });

  // Production: Don't expose stack traces
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({
      error: true,
      message: 'Internal server error'
    });
  }

  // Development: Show stack traces
  res.status(500).json({
    error: true,
    message: 'Internal server error',
    stack: err.stack
  });
});

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({
    error: true,
    message: 'Resource not found'
  });
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`${signal} received. Graceful shutdown initiated...`);

  app.close(() => {
    console.log('Express server closed');
    process.exit(0);
  });

  // Force exit after 10 seconds if server doesn't close
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = app;

