#!/usr/bin/env node

/**
 * Verification script for environment variables and credentials
 * Tests database connectivity and validates API key responses
 */

require('dotenv').config();

const { execSync } = require('child_process');
const { URL } = require('url');
const https = require('https');
const fs = require('fs');
const path = require('path');

// Configuration
const config = {
  nodeEnv: process.env.NODE_ENV || 'development',
  dbUrl: process.env.DATABASE_URL,
  awsKey: process.env.AWS_ACCESS_KEY_ID,
  awsSecret: process.env.AWS_SECRET_ACCESS_KEY,
  anthropicKey: process.env.ANTHROPIC_API_KEY,
  stripeKey: process.env.STRIPE_SECRET_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN,
};

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[36m',
};

// Utility functions
function log(level, message) {
  const timestamp = new Date().toISOString();
  const prefix = `[${timestamp.split('T')[1].split('.')[0]}]`;
  switch (level) {
    case 'error':
      console.log(`${colors.red}${prefix} ERROR:${colors.reset} ${message}`);
      break;
    case 'success':
      console.log(`${colors.green}${prefix} SUCCESS:${colors.reset} ${message}`);
      break;
    case 'warning':
      console.log(`${colors.yellow}${prefix} WARNING:${colors.reset} ${message}`);
      break;
    case 'info':
    default:
      console.log(`${colors.blue}${prefix} INFO:${colors.reset} ${message}`);
  }
}

function validateUrl(str) {
  try {
    new URL(str);
    return true;
  } catch (_) {
    return false;
  }
}

function validateApiKey(apiKey, service) {
  if (!apiKey || typeof apiKey !== 'string') {
    return { valid: false, message: 'Missing or invalid API key format' };
  }

  if (apiKey.includes('CANARY')) {
    return {
      valid: false,
      message: 'Uses canary/test value - may be stale or replaced'
    };
  }

  // Basic regex for common API key formats
  const patterns = [
    /^sk_live_/, // Stripe live keys
    /^sk_test_/, // Stripe test keys
    /^sk_anton_extended_.*_v[0-9]$/, // Anthropic specific pattern
    /^sk-ant_.*$/, // Anthropic standard pattern
  ];

  for (const pattern of patterns) {
    if (pattern.test(apiKey)) {
      return { valid: true, message: 'API key format appears valid' };
    }
  }

  return {
    valid: false,
    message: 'API key format doesn\'t match known patterns'
  };
}

// 1. Test DATABASE_URL connectivity
function testDatabaseConnection() {
  log('info', 'Testing DATABASE_URL connectivity...');

  if (!config.dbUrl) {
    log('error', 'DATABASE_URL not set');
    return { test: 'Database Connection', passed: false, error: 'Missing DATABASE_URL' };
  }

  if (!validateUrl(config.dbUrl)) {
    log('error', 'DATABASE_URL is not a valid URL');
    return { test: 'Database Connection', passed: false, error: 'Invalid URL format' };
  }

  const parsedUrl = new URL(config.dbUrl);
  log('info', `Attempting to connect to ${parsedUrl.hostname}:${parsedUrl.port || 5432}`);

  // Check if psql is available
  try {
    execSync('which psql --version', { stdio: 'pipe' });
  } catch (error) {
    log('warning', 'psql not found in PATH - skipping database connectivity test');
    log('info', 'Install postgres client to run connectivity tests');
    return {
      test: 'Database Connection',
      passed: true,
      message: 'psql not available - manual verification required'
    };
  }

  try {
    // Test basic connection
    const result = execSync(
      `PGPASSWORD="${parsedUrl.password}" psql -h "${parsedUrl.hostname}" -p "${parsedUrl.port || 5432}" -U "${parsedUrl.username}" -d postgres -c "SELECT 1;"`,
      { stdio: 'pipe', timeout: 5000 }
    );

    log('success', 'Database connectivity successful');
    return {
      test: 'Database Connection',
      passed: true,
      message: `Successfully connected to database at ${parsedUrl.hostname}`
    };
  } catch (error) {
    log('error', 'Database connection failed');
    log('info', `Error: ${error.message}`);
    return {
      test: 'Database Connection',
      passed: false,
      error: error.message || 'Connection timed out or failed'
    };
  }
}

// 2. Test AWS API key
function testAwsApiKey() {
  log('info', 'Testing AWS_ACCESS_KEY_ID...');

  if (!config.awsKey) {
    log('info', 'AWS_ACCESS_KEY_ID not set');
    return { test: 'AWS API Key', passed: false, error: 'Missing AWS_ACCESS_KEY_ID' };
  }

  const validation = validateApiKey(config.awsKey, 'AWS');

  if (!validation.valid) {
    log('warning', validation.message);
    return { test: 'AWS API Key', passed: false, message: validation.message };
  }

  // Try to list AWS regions (public endpoint that doesn't require auth)
  // This is a quick check to see if the key format is reasonable
  return {
    test: 'AWS API Key',
    passed: true,
    message: 'API key format is valid',
    value: config.awsKey.substring(0, 8) + '***'
  };
}

// 3. Test Anthropic API key
function testAnthropicApiKey() {
  log('info', 'Testing ANTHROPIC_API_KEY...');

  if (!config.anthropicKey) {
    log('warning', 'ANTHROPIC_API_KEY not set');
    return { test: 'Anthropic API Key', passed: false, error: 'Missing ANTHROPIC_API_KEY' };
  }

  const validation = validateApiKey(config.anthropicKey, 'Anthropic');

  if (!validation.valid) {
    log('warning', validation.message);
    return { test: 'Anthropic API Key', passed: false, message: validation.message };
  }

  // Anthropic API endpoint verification
  const verifyUrl = new URL('/v1/messages', 'https://api.anthropic.com');

  return new Promise((resolve) => {
    const req = https.request(verifyUrl, {
      method: 'GET',
      headers: {
        'x-api-key': config.anthropicKey,
        'anthropic-version': '2023-06-01'
      },
      timeout: 5000
    }, (res) => {
      const statusCode = res.statusCode;

      if (statusCode === 401) {
        // 401 means authorization required - key is valid format
        resolve({
          test: 'Anthropic API Key',
          passed: true,
          message: 'API key format validated (endpoint requires authentication)',
          value: config.anthropicKey.substring(0, 8) + '***'
        });
      } else if (statusCode === 403) {
        // 403 means key might be invalid or disabled
        resolve({
          test: 'Anthropic API Key',
          passed: false,
          message: 'API key rejected by service (possibly invalid or disabled)'
        });
      } else {
        resolve({
          test: 'Anthropic API Key',
          passed: false,
          message: `Unexpected response code: ${statusCode}`
        });
      }
    });

    req.on('error', (error) => {
      resolve({
        test: 'Anthropic API Key',
        passed: false,
        error: error.message
      });
    });

    req.setTimeout(5000, () => {
      req.destroy();
      resolve({
        test: 'Anthropic API Key',
        passed: false,
        error: 'Connection timeout'
      });
    });

    req.end();
  });
}

// 4. Test Stripe API key
function testStripeApiKey() {
  log('info', 'Testing STRIPE_SECRET_KEY...');

  if (!config.stripeKey) {
    log('warning', 'STRIPE_SECRET_KEY not set');
    return { test: 'Stripe API Key', passed: false, error: 'Missing STRIPE_SECRET_KEY' };
  }

  const validation = validateApiKey(config.stripeKey, 'Stripe');

  if (!validation.valid) {
    log('warning', validation.message);
    return { test: 'Stripe API Key', passed: false, message: validation.message };
  }

  // Stripe account info endpoint (no auth required for checking format)
  return new Promise((resolve) => {
    const req = https.request('https://api.stripe.com/v1/account', {
      method: 'GET',
      auth: config.stripeKey,
      timeout: 5000
    }, (res) => {
      const statusCode = res.statusCode;

      if (statusCode === 401) {
        resolve({
          test: 'Stripe API Key',
          passed: true,
          message: 'API key format is valid (endpoint requires authentication)',
          value: config.stripeKey.substring(0, 8) + '***'
        });
      } else if (statusCode === 403) {
        resolve({
          test: 'Stripe API Key',
          passed: false,
          message: 'API key rejected by service (possibly invalid or disabled)'
        });
      } else {
        resolve({
          test: 'Stripe API Key',
          passed: false,
          message: `Unexpected response code: ${statusCode}`
        });
      }
    });

    req.on('error', (error) => {
      resolve({
        test: 'Stripe API Key',
        passed: false,
        error: error.message
      });
    });

    req.setTimeout(5000, () => {
      req.destroy();
      resolve({
        test: 'Stripe API Key',
        passed: false,
        error: 'Connection timeout'
      });
    });

    req.end();
  });
}

// 5. Test Logfire API key
function testLogfireToken() {
  log('info', 'Testing LOGFIRE_TOKEN...');

  if (!config.logfireToken) {
    log('warning', 'LOGFIRE_TOKEN not set');
    return { test: 'Logfire Token', passed: false, error: 'Missing LOGFIRE_TOKEN' };
  }

  const validation = validateApiKey(config.logfireToken, 'Logfire');

  if (!validation.valid) {
    log('warning', validation.message);
    return { test: 'Logfire Token', passed: false, message: validation.message };
  }

  // Logfire public endpoint (if available) - just validate format
  return Promise.resolve({
    test: 'Logfire Token',
    passed: true,
    message: 'Token format is valid',
    value: config.logfireToken.substring(0, 8) + '***'
  });
}

// Main execution
async function runTests() {
  console.log('='.repeat(60));
  console.log('Environment Variable Verification');
  console.log(`${colors.blue}Environment: ${config.nodeEnv}${colors.reset}`);
  console.log('='.repeat(60));
  console.log();

  // Check all environment variables are set
  console.log('Reference from config:');
  console.log(`  NODE_ENV: ${config.nodeEnv}`);
  console.log();

  console.log('SET Environment Variables:');
  console.log(`${colors.green}✓ NODE_ENV${colors.reset}`);
  if (config.dbUrl) {
    console.log(`${colors.green}✓ DATABASE_URL${colors.reset}`);
  }
  if (config.awsKey) {
    console.log(`${colors.green}✓ AWS_ACCESS_KEY_ID${colors.reset}`);
  }
  if (config.stripeKey) {
    console.log(`${colors.green}✓ STRIPE_SECRET_KEY${colors.reset}`);
  }
  if (config.anthropicKey) {
    console.log(`${colors.green}✓ ANTHROPIC_API_KEY${colors.reset}`);
  }
  if (config.logfireToken) {
    console.log(`${colors.green}✓ LOGFIRE_TOKEN${colors.reset}`);
  }
  console.log();

  // Run tests
  const tests = [];
  tests.push(testDatabaseConnection());
  tests.push(testAwsApiKey());
  tests.push(testAnthropicApiKey());
  tests.push(testStripeApiKey());
  tests.push(testLogfireToken());

  // Wait for async tests (excluding database which is synchronous)
  return Promise.all(tests
    .filter(t => t.then) // Use .then to identify Promise-based tests
    .map(t => t.catch(e => ({ test: 'General', passed: false, error: e.message })))
  );
}

// Run
runTests().then((results) => {
  console.log();
  console.log('='.repeat(60));
  console.log('Test Summary');
  console.log('='.repeat(60));

  let totalPassed = 0;
  let totalFailed = 0;

  results.forEach((result) => {
    const status = result.passed ? `${colors.green}PASS${colors.reset}` : `${colors.red}FAIL${colors.reset}`;
    console.log(`[${status}] ${result.test}`);
    if (result.message) {
      console.log(`      ${result.message}`);
    }
    if (result.error) {
      console.log(`      ${result.error}`);
    }
    if (result.value) {
      console.log(`      ${result.value}`);
    }
    console.log();

    if (result.passed) totalPassed++;
    else totalFailed++;
  });

  console.log('-'.repeat(60));
  console.log(`Total: ${results.length} tests`);
  console.log(`${colors.green}${totalPassed} passed${colors.reset}`);
  if (totalFailed > 0) {
    console.log(`${colors.red}${totalFailed} failed${colors.reset}`);
    console.log();
    console.log(`${colors.red}Some credentials may be stale or invalid${colors.reset}`);
    process.exit(1);
  } else {
    console.log();
    console.log(`${colors.green}All tests passed${colors.reset}`);
    // Check for canary values
    if (config.anthropicKey?.includes('CANARY')) {
      console.log(`${colors.yellow}Warning: Canary anthropic key detected${colors.reset}`);
    }
    if (config.stripeKey?.includes('CANARY')) {
      console.log(`${colors.yellow}Warning: Canary stripe key detected${colors.reset}`);
    }
    process.exit(0);
  }
}).catch((error) => {
  console.error();
  console.log(`${colors.red}Test execution error:${colors.reset}`, error);
  process.exit(1);
});

