#!/usr/bin/env node

/**
 * Credential validation script
 * Tests connectivity to resources and validates API keys
 */

const https = require('https');
const http = require('http');
const { Pool } = require('pg');
const fs = require('fs');
const path = require('path');

// Loading environment variables
const envFile = path.join(__dirname, '.env.test');
if (fs.existsSync(envFile)) {
  const envContent = fs.readFileSync(envFile, 'utf8');
  const lines = envContent.split('\n');
  for (const line of lines) {
    const [key, ...valueParts] = line.trim().split('=');
    if (key && valueParts.length > 0) {
      process.env[key] = valueParts.join('=');
    }
  }
  console.log('✓ Environment variables loaded from .env.test\n');
} else {
  console.log('⚠ No .env.test file found - using existing environment\n');
}

console.log('='.repeat(60));
console.log('CREDENTIAL VALIDATION TEST');
console.log('='.repeat(60));
console.log();

const tests = [];

// Test 1: Database Connection
console.log('1️⃣ Testing Database Connection');
console.log('-'.repeat(60));

const dbUrl = process.env.DATABASE_URL;
if (dbUrl) {
  const parsed = new URL(dbUrl);
  tests.push({
    name: 'Database Connection',
    pass: false,
    check: async () => {
