        client.release();
        await pool.end();
        tests[tasks.findIndex(t => t.name === 'Database Connection')].pass = true;
        return { success: true, message: `Connected successfully to ${parsed.hostname}:${parsed.port}`, data: result.rows };
      } catch (error) {
