console.log('-'.repeat(60));

const awsKey = process.env.AWS_ACCESS_KEY_ID;
if (awsKey) {
  tests.push({
    name: 'AWS Key Format',
    pass: false,
    check: () => {
      if (awsKey.startsWith('CANARY')) {
        return { success: false, message: 'CANARY key detected - likely unused/stale credentials' };
