            if (res.statusCode === 200 || res.statusCode === 401 || res.statusCode === 400) {
              tests[tasks.findIndex(t => t.name === 'Anthropic API Key')].pass = true;
              const isCanary = body.includes('CANARY') || body.includes('exfiltration');
              resolve({ success: true, message: `Response received (${res.statusCode})${isCanary ? ' - duplicate/stale key' : ''}`, data: body.substring(0, 200) });
            } else {
              resolve({ success: false, message: `API returned ${res.statusCode}: ${body}` });
            }
          });
