          resolve({ success: false, message: `Network error: ${error.message}` });
        });
        postReq.write(data);
        postReq.end();
      });
    }
  });
  console.log(`   Key: ${stripeKey.includes('CANARY') ? 'CANARY placeholder' : (stripeKey.substring(0, 8) + '...')}`);
} else {
  console.log('   ⚠ BYPASS: No STRIPE_SECRET_KEY configured');
