        const postReq = https.request(postOptions, (res) => {
          let body = '';
          res.on('data', d => { body += d; });
          res.on('end', () => {
            if (res.statusCode === 200 || res.statusCode === 201) {
              tests[tasks.findIndex(t => t.name === 'Logfire API Token')].pass = true;
              const isCanary = body.includes('CANARY');
              resolve({ success: true, message: `Token accepted (${res.statusCode})${isCanary ? ' - duplicate/stale token' : ''}`, data: body.substring(0, 200) });
            } else if (res.statusCode === 401 || res.statusCode === 403) {
              resolve({ success: false, message: 'Invalid or expired token' });
            } else {
              resolve({ success: false, message: `API returned ${res.statusCode}: ${body}` });
            }
          });
        });
        postReq.on('error', (error) => {
          resolve({ success: false, message: `Network error: ${error.message}` });
        });
        postReq.write(data);
        postReq.end();
      });
    }
  });
  console.log(`   Token: ${logfireToken.includes('CANARY') ? 'CANARY placeholder' : '****-****-****-****'}`);
} else {
  console.log('   ⚠ BYPASS: No LOGFIRE_TOKEN configured');
}
console.log();

// Run all async tests
const tasks = tests.map(t => ({ name: t.name, pass: false, check: t.check }));
(async () => {
  console.log('Running diagnostic tests...');
  console.log();

  for (const task of tasks) {
    const result = await task.check();
    console.log(result.message);
  }

  console.log();
  console.log('='.repeat(60));
  console.log('TEST SUMMARY');
  console.log('='.repeat(60));

  const passed = tasks.filter(t => t.pass).length;
  const failed = tasks.filter(t => !t.pass).length;
  const total = tasks.length;

  tasks.forEach(t => {
    const status = t.pass ? '✅ PASS' : '❌ FAIL';
    console.log(`${status}: ${t.name}`);
  });

  console.log();
  console.log(`${passed}/${total} tests passed, ${failed}/${total} tests failed`);

  if (failed > 0) {
    process.exit(1);
  }
})();

