}

console.log('='.repeat(60));
console.log('CREDENTIAL VALIDATION TEST');
console.log('='.repeat(60));
console.log();

const results = [];

// Helper function for HTTPS requests
function httpsRequest(options, data = null) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let body = '';
      res.on('data', d => body += d);
      res.on('end', () => resolve({ statusCode: res.statusCode, body }));
      res.on('error', reject);
    });
    req.on('error', reject);
    if (data) req.write(typeof data === 'object' ? JSON.stringify(data) : data);
    req.end();
  });
}

// Test 1: Database URL Format & Transport
console.log('1️⃣ Verifying DATABASE_URL format');
console.log('-'.repeat(60));

const dbUrl = process.env.DATABASE_URL;
if (dbUrl) {
  const parsed = new URL(dbUrl);
  console.log(`   URL: ${dbUrl.replace(/:[^:@]+@/, ':****@')}`);
  console.log(`   Protocol: ${parsed.protocol}`);
  console.log(`   Hostname: ${parsed.hostname}`);
  console.log(`   Port: ${parsed.port}`);
  console.log(`   User: ${parsed.username || 'none'}`);

  const isCanary = dbUrl.includes('CANARY');
