  results.push({ name: 'DATABASE_URL', valid: true, bypass: true });
}
console.log();

// Test 2: AWS Key Validation
console.log('2️⃣ Verifying AWS ACCESS_KEY_ID format');
console.log('-'.repeat(60));

const awsKey = process.env.AWS_ACCESS_KEY_ID;
