} else {
  console.log('   ⚠ BYPASS: No AWS_ACCESS_KEY_ID configured');
  results.push({ name: 'AWS_ACCESS_KEY_ID', valid: true, bypass: true });
}
console.log();

// Test 3: AWS Secret Validation
console.log('3️⃣ Verifying AWS SECRET_ACCESS_KEY format');
console.log('-'.repeat(60));

const awsSecret = process.env.AWS_SECRET_ACCESS_KEY;
if (awsSecret) {
  console.log(`   Key preview: ${'*'.repeat(20)}`);
  const isCanary = awsSecret.startsWith('CANARY');
  const validLength = awsSecret.length >= 15 && awsSecret.length <= 50;

  if (isCanary) {
    console.log('   ⚠ WARNING: AWS secret starts with "CANARY" - unused credentials detected');
  } else if (!validLength) {
    console.log('   ❌ FAIL: AWS secret has invalid length');
  } else {
