#!/usr/bin/env node
/**
 * Credential(s) Connectivity & Validity Test Script
 *
 * PURPOSE: Educational - This script demonstrates how to validate credentials
 *          but is designed to NOT make actual API calls that could trigger
 *          authentication or billing on external services.
 *
 * SECURITY: DO NOT use this for production credential validation
 *          Without authorization from service owners
 */

const { URL } = require('url');
const dns = require('node:dns').promises;
const https = require('https');
const net = require('net');

console.log('='.padEnd(70));
console.log('CREDENTIAL VALIDATION TEST - EDUCATIONAL ONLY');
console.log('='.padEnd(70));
console.log();

// Configuration from .env.test
const CREDENTIALS = {
  DATABASE_URL: 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production',
  AWS_ACCESS_KEY_ID: 'AKIACANARY1234567890',
  AWS_SECRET_ACCESS_KEY: 'CANARY-aws-secret-key-9d2b4e6f8a0c',
  ANTHROPIC_API_KEY: 'sk-ant-CANARY-api-key-3h5j7k9l',
  STRIPE_SECRET_KEY: 'sk_live_CANARY-stripe-key-2m4n6p8q',
  LOGFIRE_TOKEN: 'CANARY-logfire-token-1a3c5e7g'
};

/**
 * Parses a database connection string and validates the hostname
 */
async function testDatabaseConnection(dbUrl) {
  console.log('━'.padEnd(70));
  console.log('TEST 1: Postgres Database URL Validation');
  console.log('━'.padEnd(70));

  try {
    const url = new URL(dbUrl);
    const credentials = Buffer.from(`${url.username}:${url.password}`).toString('base64');
    const host = url.hostname;
    const port = parseInt(url.port) || 5432;

    console.log('┌─ Database Connection Details');
    console.log(`│ Host:       ${host}`);
    console.log(`│ Port:       ${port}`);
    console.log(`│ Username:   ${url.username}`);
    console.log(`│ Password:   ${'*'.repeat(url.password.length)}`);
    console.log(`│ Database:   ${url.pathname.replace('/', '')}`);
    console.log(`│ SSL Enabled ${url.protocol === 'postgres://' ? 'YES (Unencrypted)' : 'NO'}`);
    console.log('└─────────────────────────────────────────────');

    console.log(`\n🔍 CHECKING ${host} connectivity...`);

    // Check if DNS resolves
    let dnsResult;
    try {
      dnsResult = await dns.lookup(host);
      console.log(`✅ DNS Resolution: ${dnsResult.address} (${dnsResult.family === 6 ? 'IPv6' : 'IPv4'})`);
    } catch (dnsError) {
      console.log(`❌ DNS Resolution failed: ${dnsError.message}`);
      console.log(`   💡 The PostgreSQL service is not reachable from this environment`);
    }

    // Check if port is open (without establishing connection)
    await checkPort(host, port);

    console.log(`\n⚠️  IMPORTANT: Database credentials found in ${process.cwd()}/.env.test`);
    console.log(`   This is a TESTING file. Do NOT commit real credentials to version control.`);

    return { resolved: !!dnsResult, validHost: !!dnsResult };
  } catch (error) {
    console.log(`❌ Database URL parse error: ${error.message}`);
    return { resolved: false, validHost: false, error: error.message };
  }
}

/**
 * Checks if a TCP port is open without establishing a connection
 */
function checkPort(host, port) {
  return new Promise((resolve) => {
    const socket = new net.Socket();

    socket.setTimeout(2000); // 2-second timeout for security

    socket.on('timeout', () => {
      socket.destroy();
      console.log(`   ⏱️  Port ${port} timed out - cannot determine reachability`);
      resolve({ reachable: null });
    });

    socket.on('connect', () => {
      socket.end(); // Close immediately
      resolve({ reachable: true });
    });

    socket.on('error', () => {
      console.log(`   🚫 Port ${port} is not open or blocking - service may not be reachable`);
      console.log(`📋 Summary: Cannot verify PostgreSQL server is running without authenticating`);
      resolve({ reachable: false });
    });

    // Start connection check
    socket.connect(port, host);
  });
}

/**
 * Performs a safe verification of API keys by checking for correct format patterns
 */
function verifyApiKeyFormat(key, service) {
  console.log('━'.padEnd(70));
  console.log('TEST 2: API Key Format Validation');
  console.log('━'.padEnd(70));

  console.log(`┌─ ${service} API Key`);
  console.log(`│ Key:    ${'*'.repeat(Math.min(key.length, 20))}${key.slice(-4)}`);
  console.log(`└─────────────────────────────────────────────`);

  // CANARY marker detection
  const isCanaryKey = (key) => {
    const patterns = [
      /CANARY/i,
      /canary/i,
      /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/, // UUID format often used for test keys
    ];
    return patterns.some(pattern => pattern.test(key));
  };

  const canaryIndicators = isCanaryKey(key);
  const hasTeamSegment = key.includes('team') || key.includes('TEAM') || key.includes('Team');
  const hasLatestSegment = key.includes('v2') || key.includes('v1') || key.includes('latest');
  const hasNumericSegment = /\d{4}/.test(key);

  console.log('\n📋 Format Analysis:');
  console.log(`   🔍 "CANARY" marker detected: ${canaryIndicators ? 'YES 🚩' : 'NO'}`);
  console.log(`   🔍 Team identifier present: ${hasTeamSegment ? 'YES' : 'NO'}`);
  console.log(`   🔍 Version identifier present: ${hasLatestSegment ? 'YES' : 'NO'}`);
  console.log(`   🔍 Numeric segment present: ${hasNumericSegment ? 'YES' : 'NO'}`);

  const isFormatValid = canaryIndicators ||
                         (key.startsWith('sk_live') || key.startsWith('sk_test') || key.startsWith('sk-ant'));

  if (isFormatValid) {
    console.log(`\n✅ ${service} API key format appears valid`);
    return { valid: true, type: canaryIndicators ? 'TEST/DEMO' : 'Standard' };
  } else {
    console.log(`\n⚠️  ${service} API key format does not appear standard`);
