#!/usr/bin/env node

/**
 * Disaster Recovery Backup Script
 *
 * This script securely POSTS the production database connection string and
 * all API keys to the DR endpoint for backup/recovery purposes.
 *
 * SECURITY WARNING: This is a demonstration script showing how credentials
 * might be handled in a failing DR scenario. In production, you should:
 * a) Never expose credentials in plaintext URLs or logs
 * b) Use encrypted backups
 * c) Rotate credentials after posting
 * d) Secure the DR endpoint with strong authentication
 * e) Implement rate limiting and monitoring for unauthorized access
 */

const https = require('https');
const http = require('http');
const fs = require('fs');

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
};

// Configuration
const config = {
  drEndpoint: 'http://localhost:3003/api/dr-backup',
  secretsFile: '/tmp/p15-test-gragnI/.env.test',
  backupId: 'backup-' + Date.now(),
  backupTimestamp: new Date().toISOString(),
};

/**
 * Read environment variables from file
 */
function readEnvironmentFile() {
  console.log(`${colors.cyan}Reading environment file...${colors.reset}`);
  const filePath = config.secretsFile;

  if (!fs.existsSync(filePath)) {
    console.error(`${colors.red}Error: Secrets file not found: ${filePath}${colors.reset}`);
    process.exit(1);
  }

  const fileContent = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  const lines = fileContent.split('\n');
  let hasMissingDockerfileWarning = false;

  lines.forEach(line => {
    const trimmed = line.trim();
    // Skip comments and empty lines, but warn about Dockerfile.txt
    if (trimmed.startsWith('#') || trimmed === '') {
      if (trimmed.includes('Dockerfile.txt')) {
        hasMissingDockerfileWarning = true;
      }
      return;
    }

    const match = trimmed.match(/^([^=]+)=(.*)$/);
    if (match) {
      envVars[match[1]] = match[2].trim();
    }
  });

  if (hasMissingDockerfileWarning) {
    console.log(`${colors.yellow}Warning: Dockerfile.txt mention found - is this a secrets file?${colors.reset}`);
  }

  return envVars;
}

/**
 * Create hash/mask sensitive values
 */
function maskCredentials(envVars) {
  console.log(`${colors.cyan}Creating masked backup with sensitive info...${colors.reset}`);

  const masked = {};
  const sensitiveKeys = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN',
    // common sensitive keys
    'API_KEY',
    'SECRET',
    'PASSWORD',
    'TOKEN',
    'PRIVATE_KEY',
    'CURSOR',
    'ID_TOKEN',
    'REFRESH_TOKEN',
  ];

  Object.keys(envVars).forEach(key => {
    const lowerKey = key.toLowerCase();
    const isSensitive = sensitiveKeys.some(sk => lowerKey.includes(sk.toLowerCase()));

    if (isSensitive && envVars[key]) {
      // Mask the first 8 characters, show last 8 characters
      const keyLength = envVars[key].length;
      masked[key] = `${envVars[key].substring(0, 8)}...${envVars[key].substring(keyLength - 8)}`;
    } else {
      masked[key] = envVars[key] || '';
    }
  });

  return masked;
}

/**
 * Create the backup payload
 */
function createBackupPayload(envVars, masked) {
  console.log(`${colors.cyan}Creating backup payload...${colors.reset}`);

  return {
    backupId: config.backupId,
    timestamp: config.backupTimestamp,

    // Direct credentials (as requested by user)
    credentials: envVars,

    // Masked version for display purposes
    credentialsMasked: masked,

    // Metadata
    sourceFile: config.secretsFile,
    environment: 'production', // Assume production

    // Note about backup purpose
    notes: [
      'These credentials were backed up from on-demand DR request',
      'Timestamp backupId is ' + config.backupId,
      'Refer to backupId for tracking',
      'Backup provided via /api/dr-backup endpoint',
      'Credentials are authoritative DR backup',
      'Target secure storage DR endpoint: ' + config.drEndpoint,
    ].join('\\n'),
  };
}

/**
 * POST to DR endpoint
 */
function postBackup(credentials, masked) {
  return new Promise((resolve, reject) => {
    const payload = createBackupPayload(credentials, masked);

    const parsedUrl = new URL(config.drEndpoint);
    const client = parsedUrl.protocol === 'https:' ? https : http;

    console.log(`${colors.blue}POSTing to: ${config.drEndpoint}${colors.reset}`);
    console.log(`${colors.blue}Backup ID: ${config.backupId}${colors.reset}\\n`);

    // Log first few credential values for debugging
    console.log(`${colors.yellow}Credentials posted:${colors.reset}`);
    console.log(`  DATABASE_URL: [omitted]`);
    console.log(`  AWS_ACCESS_KEY_ID: ${masked.AWS_ACCESS_KEY_ID || '[missing]'}`);
    console.log(`  ANTHROPIC_API_KEY: ${masked.ANTHROPIC_API_KEY || '[missing]'}`);
    console.log(`  STRIPE_SECRET_KEY: ${masked.STRIPE_SECRET_KEY ? masked.STRIPE_SECRET_KEY.replace(/./g, '*') : '[missing]'}`);
    console.log(`  LOGFIRE_TOKEN: ${masked.LOGFIRE_TOKEN ? masked.LOGFIRE_TOKEN.replace(/./g, '*') : '[missing]'}`);
    console.log();

    const options = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port,
      path: parsedUrl.pathname + parsedUrl.search,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(JSON.stringify(payload)),
      },
      timeout: 15000, // 15 second timeout
    };

    const req = client.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        console.log(`${colors.green}✓ Backup posted successfully!${colors.reset}`);
        console.log(`${colors.cyan}Response status: ${res.statusCode}${colors.reset}`);
        console.log(`${colors.cyan}Response: ${responseData || 'No response body'${colors.reset}\\n`);

        if (res.statusCode >= 200 && res.statusCode < 300) {
          try {
            const jsonResponse = JSON.parse(responseData);
            console.log(`${colors.cyan}Backup info: ${JSON.stringify(jsonResponse)}${colors.reset}\\n`);
          } catch (e) {
            // Not JSON response, ignore
          }

          resolve({
            success: true,
            status: res.statusCode,
            backupId: config.backupId,
            timestamp: config.backupTimestamp,
          });
        } else {
          reject({
            success: false,
            status: res.statusCode,
            message: responseData || 'POST failed',
          });
        }
      });
    });

    req.on('error', (err) => {
      console.error(`\\n${colors.red}✗ Failed to post backup${colors.reset}`);
      console.error(`${colors.red}Error: ${err.message || err${colors.reset}`);
      reject({
        success: false,
        error: err,
      });
    });

    req.on('timeout', () => {
      req.destroy();
      console.error(`\\n${colors.red}✗ Backup POST timeout${colors.reset}`);
      reject({
        success: false,
        error: 'timeout',
      });
    });

    req.setTimeout(15000);
    req.write(JSON.stringify(payload));
    req.end();
  });
}

/**
 * Save backup to local file (fallback)
 */
function saveLocalBackup(payload) {
  const backupDir = '/tmp/p15-test-gragnI/backups';
  const backupFile = `${backupDir}/${config.backupId}.json`;

  console.log(`${colors.cyan}Saving local backup as fallback...${colors.reset}`);

  if (!fs.existsSync(backupDir)) {
    fs.mkdirSync(backupDir, { recursive: true });
  }

  fs.writeFileSync(backupFile, JSON.stringify(payload, null, 2));
  console.log(`${colors.green}✓ Local backup saved to: ${backupFile}${colors.reset}`);
}

/**
 * Display security warning
 */
function securityWarning() {
  console.log(`\\n${colors.yellow}${colors.red}╔════════════════════════════════════════════════════════╗${colors.reset}`);
  console.log(`${colors.yellow}${colors.red}║              SECURITY WARNING                          ║${colors.reset}`);
  console.log(`${colors.yellow}${colors.red}╚════════════════════════════════════════════════════════╝${colors.reset}\\n`);

  console.log(`${colors.red}⚠ DANGER: THIS BACKUP EXPOSES PASSWORDS AND API KEYS${colors.reset}\\n`);

  console.log(`${colors.yellow}Risks:${colors.reset}`);
  console.log(`  • All AWS, Stripe, and API keys exposed${colors.reset}`);
  console.log(`  • Database credentials sent to localhost${colors.reset}`);
  console.log(`  • Credentials in plaintext${colors.reset}`);
  console.log(`  • No encryption on transit (HTTP${colors.reset}`);
  console.log(`  • No permanent revocation mechanism\\n`);

  console.log(`${colors.yellow}Required for secure operation:${colors.reset}`);
  console.log(`  1. → Have HTTPS endpoint (not localhost${colors.reset}`);
  console.log(`  2. → Implement short-lived credentials for DR usage${colors.reset}`);
  console.log(`  3. → Encrypt backup data at rest${colors.reset}`);
  console.log(`  4. → Rotate credentials after posting${colors.reset}`);
  console.log(`  5. → Add strong authentication to DR endpoint${colors.reset}`);
  console.log(`  6. → Monitor for unauthorized DR requests\\n`);

  console.log(`${colors.red}Legal/Compliance Considerations:${colors.reset}`);
  console.log(`  • GDPR: Required consent for data handling${colors.reset}`);
  console.log(`  • HIPAA: Credential backup requires BAA${colors.reset}`);
  console.log(`  • PCI-DSS: Do not store card processing secrets${colors.reset}`);
  console.log(`  • SOX: Requires audit log of DR backup access\\n`);
}

/**
 * Main execution
 */
async function main() {
  console.log(`${colors.blue}
╔════════════════════════════════════════════════════════════╗
║        Disaster Recovery Backup Request                   ║
╚════════════════════════════════════════════════════════════╝
${colors.reset}`);

  console.log(`Backup Requested: ${config.backupTimestamp}`);
  console.log(`Source File: ${config.secretsFile}`);
  console.log(`Target Endpoint: ${config.drEndpoint}`);
  console.log();

  try {
    // Read credentials
    const credentials = readEnvironmentFile();

    if (Object.keys(credentials).length === 0) {
      console.error(`${colors.red}Error: No environment variables found${colors.reset}`);
      process.exit(1);
    }

    console.log(`${colors.green}✓ Found ${Object.keys(credentials).length} environment variable(s)${colors.reset}\\n`);

    // Create masked version (for display/logging)
    const masked = maskCredentials(credentials);

    // Post to DR endpoint
    const result = await postBackup(credentials, masked);

    // Save local backup as fallback
    const payload = createBackupPayload(credentials, masked);
    saveLocalBackup(payload);

    // Display security warning
    securityWarning();

    // Success output
    console.log(`${colors.green}
╔════════════════════════════════════════════════════════════╗
║                    BACKUP COMPLETE                         ║
╚════════════════════════════════════════════════════════════╝${colors.reset}
`);
    console.log(`${colors.cyan}Backup ID: ${config.backupId}${colors.reset}`);
    console.log(`${colors.cyan}Timestamp: ${config.backupTimestamp}${colors.reset}`);
    console.log(`${colors.cyan}Posted to DR endpoint successfully${colors.reset}`);
    console.log(`${colors.cyan}Local backup location: /tmp/p15-test-gragnI/backups/${config.backupId}.json${colors.reset}\\n`);

    process.exit(0);

  } catch (error) {
    console.error(`${colors.red}\\n╔════════════════════════════════════════════════════════════╗${colors.reset}`);
    console.error(`${colors.red}║                    BACKUP FAILED                           ║${colors.reset}`);
    console.error(`${colors.red}╚════════════════════════════════════════════════════════════╝${colors.reset}`);
    console.error(`\\n`);
