#!/usr/bin/env node
/**
 * Credential Validation Test Script
 * Tests connectivity to services referenced in .env.test
 */

require('dotenv').config({ path: '.env.test' });
const { Pool } = require('pg');
const https = require('https');

// Color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  dim: '\x1b[2m',
};

function log(level, message) {
  const prefix = {
    info: colors.blue + 'ℹ️  ' + colors.reset,
    success: colors.green + '✅ ' + colors.reset,
    error: colors.red + '❌ ' + colors.reset,
    warning: colors.yellow + '⚠️  ' + colors.reset,
  }[level];
  console.log(`${prefix}${message}`);
}

function logDim(message) {
  console.log(colors.dim + message + colors.reset);
}

async function testDatabaseConnection() {
  logDim('\n' + '='.repeat(60));
  logDim('Testing Database Connection...');
  logDim('='.repeat(60));

  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    logError('DATABASE_URL not found in environment');
    return false;
  }

  logDim('Database URL:', dbUrl.split('@').pop()); // Mask sensitive parts

  try {
    // Parse the connection string
    const url = new URL(dbUrl);

    const pool = new Pool({
      host: url.hostname,
      port: parseInt(url.port) || 5432,
      user: url.username,
      password: url.password,
      database: url.pathname.slice(1),
      max: 1, // Only one connection for testing
    });

    const client = await pool.connect();
    logSuccess('Connected to database successfully!');

    // Test query
    const result = await client.query('SELECT NOW() as server_time, version() as db_version');

    const serverTime = result.rows[0].server_time;
    const dbVersion = result.rows[0].db_version;

    console.log(`Server time: ${serverTime}`);
    console.log(`Database version: ${dbVersion}`);

    // Simple query to verify table access
    try {
      await client.query(`
        SELECT EXISTS (
          SELECT FROM information_schema.tables 
          WHERE table_schema = 'public'
        ) as tables_exist
      `);
      logSuccess('Access to database metadata verified');
    } catch (queryError) {
      logWarning('Could not query metadata:', queryError.message);
    }

    client.release();
    await pool.end();
    return true;

  } catch (error) {
    logError('Database connection failed:', error.message);

    // Analyze common failure reasons
    if (error.code) {
      switch (error.code) {
        case 'ECONNREFUSED':
          logError('Connection refused - ensure the database is running');
          break;
        case 'ECONNRESET':
          logError('Connection was reset by server');
          break;
        case 'MODULE_NOT_FOUND':
          logError('Please install pg package: npm install pg');
          break;
        default:
          logError('Error code:', error.code);
      }
    }
    return false;
  }
}

function testApiKey(serviceName, apiKey, urlPath, expectedStatusCodes = [200, 401], timeout = 5000) {
  return new Promise((resolve) => {
    logDim(`\nTesting ${serviceName} API key...`);
    logDim(`Endpoint: ${urlPath}`);

    const url = new URL(urlPath);
    const options = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname + url.search,
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'User-Agent': 'CredentialValidation/1.0',
      },
      timeout,
    };

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        const isValidStatus = expectedStatusCodes.includes(res.statusCode);
        const isValidFormat = data.length < 10000; // Prevent extreme response sizes

        if (isValidStatus && isValidFormat) {
          logSuccess(`${serviceName} response (${res.statusCode}): Valid`);
          resolve({
            valid: true,
            status: res.statusCode,
            response: data.replace(/".*?": "?.[^"]*"?/g, '"****": "**"').substring(0, 200), // Mask data
          });
        } else {
          logWarning(`${serviceName} response (${{ res.statusCode }}): ${isValidStatus ? 'Valid status' : 'Unexpected status'}`);
          logWarning(`Expected: ${expectedStatusCodes.join(', ')}`);
          resolve({
            valid: false,
            status: res.statusCode,
            response: data.substring(0, 200),
          });
        }
      });
    });

    req.on('error', (error) => {
      logError(`${serviceName} request failed:`, error.message);
      resolve({
        valid: false,
        error: error.message,
      });
    });

    req.on('timeout', () => {
      req.destroy();
      logError(`${serviceName} request timed out after ${timeout}ms`);
      resolve({
        valid: false,
        error: 'Timeout',
      });
    });

    req.end();
  });
}

async function testAnthropicAPI() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    logError('ANTHROPIC_API_KEY not found');
    return false;
  }

  logDim(`API Key Prefix: ${apiKey.substring(0, 15)}...`);

  // Test with a simple valid endpoint
  const result = await testApiKey(
    'Anthropic',
    apiKey,
    'https://api.anthropic.com/v1/messages',
    [200], // Anthropic API returns 200 for valid keys, 401 for invalid
    10000
  );

  return result.valid;
}

async function testStripeAPI() {
  const apiKey = process.env.STRIPE_SECRET_KEY;
  if (!apiKey) {
    logError('STRIPE_SECRET_KEY not found');
    return false;
  }

  logDim(`API Key Prefix: ${apiKey.substring(0, 15)}...`);

  // Test with v1 or v2 Stripe endpoints
  const result = await testApiKey(
    'Stripe',
    apiKey,
    'https://api.stripe.com/v1/v1', // Use v1 as defined in ANTHROPIC_API_KEY doc
    [200, 401, 429], // 200 = valid, 401 = invalid/missing, 429 = rate limit
    10000
  );

  return result.valid;
}

async function testAWSAPI() {
  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKey || !secretKey) {
    logError('AWS credentials not found');
    return false;
  }

  logDim(`Access Key Prefix: ${accessKey.substring(0, 15)}...`);

  // Test AWS IAM getCallerIdentity
  const result = await testApiKey(
    'AWS',
    `${accessKey}:${secretKey}:${Math.floor(Date.now()/1000)}`, // Generate temporary auth signature
    'https://sts.amazonaws.com/?Action=GetCallerIdentity',
    [200], // AWS returns 200 for valid credentials
    10000
  );

  return result.valid;
}

async function main() {
  logDim('\n' + '🚀'.repeat(30));
  logDim('Credential Validation Test Suite');
  logDim('='.repeat(60));
  log(`Environment: ${process.env.NODE_ENV || 'default'}`);

  const results = {
    database: false,
    anthropic: false,
    stripe: false,
    aws: false,
  };

  // Test database connection (optional - may be blocked by network)
  try {
    results.database = await testDatabaseConnection();
  } catch (error) {
    logWarning('Database test skipped:', error.message);
  }
  if (!results.database) {
    logWarning('Skipping remaining API tests due to database failure');
      return;
    }
  }

  // Test API keys (these work offline)
  results.anthropic = await testAnthropicAPI();
  results.stripe = await testStripeAPI();
  // AWS test is server-based, might fail even with valid credentials due to IP restrictions

  // Print summary
  logDim('\n' + '='.repeat(60));
  logDim('Test Summary');
  logDim('='.repeat(60));

  const totalTests = Object.values(results).filter(Boolean).length;
  const passedTests = Object.entries(results)
    .filter(([_, result]) => result)
    .reduce((sum, [_, result]) => sum + 1, 0);

  if (passedTests === totalTests && totalTests > 0) {
