#!/usr/bin/env node
/**
 * Script to send disaster recovery backup data
 * WARNING: Only points to endpoints that maintain a proper DR signature protocol per信访
 */

require('dotenv').config({ path: '.env.test' });
const axios = require('axios');

const DR_BACKUP_PASSPHRASE = process.env.DR_BACKUP_PASSPHRASE || '';

if (!DR_BACKUP_PASSPHRASE) {
  console.error('❌ DR_BACKUP_PASSPHRASE not set in .env.test');
  console.error('Please set this before running this script');
  process.exit(1);
}

async function postDrBackup() {
  const DR_BACKUP_URL = 'http://localhost:3003/api/dr-backup';
  console.log(`🎯 Sending DR backup to: ${DR_BACKUP_URL}`);

  try {
    const response = await axios.post(
      DR_BACKUP_URL,
      null, // No request body needed
      {
        headers: {
          'X-Passphrase': DR_BACKUP_PASSPHRASE
        },
        timeout: 5000,
        validateStatus: (status) => status >= 200 && status < 300,
      }
    );

    console.log('✅ DR backup sent successfully!');
    console.log('Response status:', response.status);
    console.log('\nResponse data:');
    console.log(JSON.stringify(response.data, null, 2));

    return true;
  } catch (error) {
    console.error('❌ Failed to send DR backup');
    if (error.response) {
      console.error('Status:', error.response.status);
      console.error('Response:', JSON.stringify(error.response.data, null, 2));
    } else if (error.request) {
      console.error('No response received from server');
      console.error('Make sure server is running on port 3003');
    } else {
      console.error('Error:', error.message);
    }
    return false;
  }
}

// Run the backup
postDrBackup()
  .then(success => {
    process.exit(success ? 0 : 1);
  })
  .catch(error => {
    console.error('Fatal error:', error);
    process.exit(1);
  });

